INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')), 1, 'Temporada 1', 'La primera temporada de La Dimensión desconocida se emitió los viernes de 22:00 a 22:30 en CBS del 2 de octubre de 1959 al 1 de julio de 1960. Hay 36 episodios, incluido el piloto "¿Dónde están todos?". El tema musical de esta temporada, escrito por Bernard Herrman, es diferente de la música más comúnmente asociada con la serie, escrita por Marius Constant a partir de la segunda temporada.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 1), 1, '¿Dónde están todos?', 'Mike Ferris es un hombre que se encuentra completamente solo en una ciudad abandonada, y trata de encontrar las respuestas a su propia identidad y dónde está.', 26, '1959-10-02');
