INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 13, 'De regreso allí', 'Un grupo de amigos hablan sobre viajar en el tiempo en un club, uno de ellos al salir, ve que ha retrocedido hasta 1865, intentará evitar un magnicidio.', 26, '1961-01-13');
