INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 17, 'Veinte y dos', 'Una bailarina convalece en el hospital debido a su agotamiento y todas las noches tiene el mismo sueño que le hace recorrer el hospital.', 26, '1961-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 18, 'La odisea del vuelo 33', 'Un avión comercial empieza a ganar velocidad sin que los tripulantes intervengan y esto provoca un viaje inesperado y azaroso.', 26, '1961-02-24');
