INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 21, 'El primero que mueve', 'Un par de compañeros de trabajo empiezan a ganar dinero en los casinos gracias a la habilidad especial de uno de ellos.', 26, '1961-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 22, 'Llamada de larga distancia', 'El amor que se tienen abuela y nieto va mas allá de la muerte de esta.', 26, '1961-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 23, 'Cien Yardas sobre el Rim', 'Un pionero del oeste norteamericano realiza un viaje repentino para salvar a su hijo enfermo.', 26, '1961-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 24, 'La alcaparra desgarrada de Van Winkle', 'Cuatro ladrones esperan cien años después de un robo para poder disfrutar del botín de oro sin ser molestados.', 26, '1961-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 25, 'El silencio', 'Dos caballeros se apuestan a que uno de ellos no puede estar un año entero sin hablar.', 26, '1961-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 26, 'Juego de Sombras', '¿Es el sueño la realidad o es la realidad un sueño?', 26, '1961-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 27, 'La mente y el asunto', 'Nuestros deseos no son tan satisfactorios como esperamos.', 26, '1961-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 28, 'Marciano Verdadero', 'Dos especies de alienígenas se disputan crear una colonia terrestre.', 26, '1961-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 2), 29, 'El hombre obsoleto', '¿Tiene el estado el derecho a decidir cuando una persona deja de ser util?', 26, '1961-06-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')), 3, 'Temporada 3', 'La tercera temporada de La Dimensión Desconocida se transmitió los viernes de 22:00 a 22:30 en CBS del 15 de septiembre de 1961 al 1 de junio de 1962. Hay 37 episodios.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 1, 'Dos', 'Un hombre y una mujer en bandos opuestos de una guerra futura, se encuentran en una ciudad desierta.', 26, '1961-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 2, 'La llegada', 'Un avión aterriza sin problemas en el aeropuerto, pero la tripulación, los pasajeros y el piloto han desaparecido sin dejar rastro.', 26, '1961-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 3, 'El refugio', 'Cuando un ataque nuclear parece inminente, un grupo de amigos y vecinos luchan por el control de un bunker cercano.', 26, '1961-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 4, 'Los transeuntes', 'Un soldado confederado de regreso a casa después de la Guerra Civil, decide descansar en una casa incendiada. En ella conoce a una mujer enviudada recientemente.', 26, '1961-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 5, 'Una partida de billar', 'El campeón de billar Fats Brown, regresa de la tumba para una última partida.', 26, '1961-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 6, 'El espejo', 'Después de que un pobre pero ambicioso granjero centroamericano derrote al dictador de su país, cree ver asesinos por todas partes. Pero al mirarse al espejo, este le revela a su enemigo más peligroso.', 26, '1961-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 7, 'La tumba', 'Antes de morir, el famoso pistolero Pinto Sykes maldice a Conny Miller, un pistolero que llevaba detrás de Pinto cuatro meses. Pinto le reta a un último encuentro junto a su tumba.', 26, '1961-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 8, 'Es una buena vida', 'El pequeño Anthony Fremont controla una ciudad entera gracias a que puede controlar la mente de las personas y hacer que estas hagan lo que él quiera.', 26, '1961-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 9, 'Retorno a la calavera', 'Un excapitán de las SS Nazis, decide regresar a las ruinas del campo de concentración donde estuvo destinado. Allí se encuentra con una de sus víctimas.', 26, '1961-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 10, 'Sol de medianoche', 'La órbita terrestre se ha visto alterada y la Tierra se acerca cada vez más al sol. Su destrucción es inminente.', 26, '1961-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 11, 'El valle tranquilo', 'Durante una exploración rutinaria, el sargento confederado Joseph Paradine, haya un pueblo lleno de soldados de la Unión y a un misterioso anciano que dice haberlos paralizado con ayuda de la brujería.', 26, '1961-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 12, 'La jungla', 'Alan Richards planea construir una presa en las tierras de una tribu ancestral africana. El chamán de la tribu lo maldice por su atrevimiento.', 26, '1961-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 13, 'Erase una vez', 'Woodrow es conserje en 1890 y activa accidentalmente una máquina del tiempo que lo transporta a 1962. El problema es que esta deja de funcionar.', 26, '1961-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 14, 'Cinco personas en busca de una salida', 'Un vagabundo, un payaso, un gaitero, una bailarina y un oficial militar están atrapados en un enorme cilindro.', 26, '1961-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 15, 'La cualidad de la misericordia', 'Un joven soldado obtiene un punto de vista diferente de la guerra, cuando misteriosamente cambia de lugar con un oficial japonés, que intenta evitar que su superior cargue contra las fuerzas americanas.', 26, '1961-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 16, 'Nada en la oscuridad', 'Una anciana solitaria se niega a abandonar su apartamento por temor a encontrarse con el "Sr. Muerte".', 26, '1962-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 17, 'Un portador del féretro más', 'Paul Radin invitado a tres personas a unirse a él en su refugio antiaéreo.', 26, '1962-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 18, 'Los zapatos del muerto', 'Un vagabundo roba los zapatos de un gángster asesinado y es confundido con el fantasma de este, que permanece en la tierra para vengarse de su asesino.', 26, '1962-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 19, 'La cacería', 'Mientras cazaba en el bosque, Hyder Simpson y su perro se sumergen en un lago mientras perseguían un mapache. Cuando llega a casa, Hyder se da cuenta de que nadie puede verle ni oírle.', 26, '1962-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 20, 'Momento decisivo con Range McGrew', 'El actor Rance McGrew se gana la vida en una serie televisiva del Oeste. Es un actor pésimo y aún peor vaquero, pero siempre "gana" contra los malos cada semana. Viendo esto, los malos se cansan y envían a Jesse James a la tierra para que le dé una lección al inútil de McGrew..', 26, '1962-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 21, 'Patear la lata', 'Para los residentes del asilo para mayores Sunnyvale, el secreto para permanecer jóvenes es actuar de forma juvenil y más concretamente, jugar a un juego llamado "patear-la-lata".', 26, '1962-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 22, 'Un piano en casa', 'Fortune descubre que el piano que le regaló a su esposa por su cumpleaños, tiene propiedades mágicas. Su música hace que las personas revelen sus verdaderos sentimientos.', 26, '1962-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 23, 'El último funeral de Jeff Myrtlebank', 'Jeff Myrtlebank vuelve a la vida durante su funeral y pronto comienza a actuar de manera muy extraña...', 26, '1962-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 24, 'Para servir al hombre', 'Los Kanamitas son unos amigables extraterrestres de 3 metros de altura, que llegan a la tierra con un único objetivo: servir al hombre.', 26, '1962-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 25, 'El fugitivo', 'El viejo Ben tiene el extraño don de convertirse en cualquier cosa y con ese poder intentará ayudar a una niña lisiada.', 26, '1962-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 26, 'La niña perdida', 'Una niña de seis años rueda debajo de su cama y desaparece en una cuarta dimensión. Sus padres y un vecino luchan por liberarla antes de que el agujero entre las dimensiones se cierre para siempre.', 26, '1962-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 27, 'Persona o personas desconocidas', 'David Gurney se despierta por la mañana dispuesto a empezar un nuevo día. Sin embargo todo se torna una pesadilla cuando nadie a su alrededor le reconoce.', 26, '1962-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 28, 'Gente pequeña', 'Cuando un astronauta aterriza en un planeta poblado por gente diminuta, se auto proclama "Dios".', 26, '1962-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 29, 'Las cuatro en punto', 'Oliver Crangle es un hombre amargado y mezquino, que se dedica a juzgar a todo el mundo por las cosas que hacen. Su plan maestro consiste en reducir de tamaño a todos los que considera malvados a las 4 en punto.', 26, '1962-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 30, 'Abracadabra y Frisby', 'Las bravuconadas y mentiras de un hombre fanfarrón, atraen la atención de algunos alienígenas.', 26, '1962-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 31, 'Nueva vida, sociedad anónima', 'Una pareja de ancianos visita la New Life Corporation, una empresa que se dedica a transferir la mente de sus clientes a cuerpos jóvenes y saludables.', 26, '1962-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 32, 'El obsequio', 'Un extraterrestre aterriza en una remota población montañosa, levantando temores y suspicacias entre sus ciudadanos. Sin embargo se hace amigo de un muchacho, al que le hace entrega de un extraño regalo.', 26, '1962-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 33, 'El muñeco', 'Un ventrílocuo está convencido de que su marioneta, Willie, está vivo y es malvado, por lo que decide sustituirlo por otra marioneta. Pero Willie tiene otros planes...', 26, '1962-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 34, 'El capricho de un hombre joven', 'Una pareja de recién casados decide visitar la casa donde él se había criado, pero los lazos del pasado son demasiado fuertes.', 26, '1962-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 35, 'Yo canto al cuerpo eléctrico', 'Un hombre que acaba de perder a su esposa, compra un robot con forma de entrañable abuelita para cuidar de sus tres hijos.', 26, '1962-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 36, 'Las alas de Cavender', 'Cavender es un ángel que trata de conseguir sus alas ayudando a Agnes, una mujer que acaba de perder su empleo.', 25, '1962-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 3), 37, 'Cambio de guardia', 'Un anciano profesor de una escuela privada, se plantea el suicidio mientras se pregunta si su vida ha significado algo. Esa nochebuena, sus antiguos alumnos, le muestran que él les ha influenciado a todos a lo largo de sus años de enseñanza.', 25, '1962-06-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')), 4, 'Temporada 4', 'La cuarta temporada de La Dimensión Desconocida se transmitió los jueves de 21:00 a 22:00 en CBS del 3 de enero al 23 de mayo de 1963.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 1, 'A su imagen', 'Un científico intenta corregir sus imperfecciones construyendo una imagen mecánica de sí mismo, que incluye todas las cualidades de las que él carece.', 53, '1963-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 2, 'La tumba a 30 brazas', 'Un destructor naval de los Estados Unidos investiga un misterioso sonido que proviene de un submarino hundido.', 53, '1963-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 3, 'El valle de las sombras', 'Un periodista se encuentra atrapado en una pequeña ciudad donde la gente puede invertir el tiempo y hacer muchas otras cosas sorprendentes.', 53, '1963-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 4, 'Está vivo', 'Peter Vollmer es desde hace poco tiempo un líder neonazi, que anhela conseguir más poder. Aconsejado por un misterioso benefactor, los seguidores de Vollmer crecen, al igual que su ego...', 53, '1963-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 5, 'Silencio', 'Una niña de 12 años que perdió a sus padres en un incendio, no habla porque ha crecido en una sociedad secreta de telépatas. La pareja que la acoge y su maestra, están decididos a ayudarla a adaptarse a su sociedad, sin importar el coste.', 53, '1963-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 6, 'Navio muerto', 'Una nave espacial aterriza en un planeta y la tripulación se encuentra con una nave idéntica a la suya siniestrada. Los tripulantes de la nave están convencidos de que murieron en ese accidente, pero el capitán se niega a ver la verdad.', 53, '1963-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 7, 'Jess-Belle', 'Jess-Belle le pide ayuda a una bruja, para que Billy-Ben Turner se enamore de ella.', 53, '1963-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 8, 'Miniatura', 'Un hombre solitario se enamora de una muñeca expuesta en un museo y que considera está viva.', 53, '1963-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 9, 'La imprenta del diablo', 'El editor de un periódico en bancarrota, contrata a un astuto anciano, que tiene la habilidad de predecir las noticias que están por suceder y dice ser el diablo.', 53, '1963-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 10, 'Cualquier tiempo pasado fue mejor', 'Un hombre viaja en el tiempo para intentar prevenir algunas de las mayores catástrofes de la historia.', 53, '1963-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 11, 'El paralelo', 'Un astronauta se desmaya mientras orbita la tierra y termina en un universo paralelo.', 53, '1963-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 12, 'Sueño de genio', 'Un hombre considera varias posibilidades cuando un genio le ofrece un deseo.', 52, '1963-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 13, 'La nueva exposición', 'El encargado de un museo de cera sobre los mayores asesinos de la historia, que está a punto de cerrar, consigue convencer al director de que le permita una última exposición. Pero cuando intentan destruir las figuras de cera, a los asesinos no les hace mucha gracia intentar ser asesinados...', 53, '1963-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 14, 'Últimamente pienso en Cliffordville', 'Un rico empresario, aburrido de su vida, tiene la oportunidad de volver atrás en el tiempo y volver a empezar, armado con todo el conocimiento que ha adquirido en su vida... un arsenal que no es tan poderoso como él cree.', 53, '1963-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 15, 'El increible mundo de Horace Ford', 'El diseñador de juguetes Horace Ford, pasa la mayor parte de su tiempo recordando su idílica infancia. Pero cuando tiene la oportunidad de volver a esos años, no todo era tan maravilloso como lo recordaba.', 52, '1963-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 16, 'El jueves volvemos a casa', 'El líder de una expedición a un asteroide, trata de convencer a los demás de que no vale la pena volver a la Tierra.', 53, '1963-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 17, 'Pasaje en el Lady Anne', 'Una joven pareja se encuentra viajando en el Lady Anne, un viejo transatlántico que transporta a un grupo de pasajeros igualmente viejos.', 52, '1963-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 4), 18, 'El bardo', 'La carrera de un escritor novel sin talento, despega cuando el fantasma de William Shakespeare escribe su libro.', 52, '1963-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')), 5, 'Temporada 5', 'La quinta y última temporada de La Dimensión Desconocida se transmitió los viernes de 21:30 a 22:00 p. m. en CBS del 27 de septiembre de 1963 al 19 de junio de 1964. Presentaba la misma introducción que la cuarta temporada, pero volvió a la mitad original. formato de hora.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 1, 'Elogios a Pit', 'Max Phillips es un corredor de apuestas alcohólico que lamenta no haber sido mejor padre para su hijo, Pip, herido de gravedad en Vietnam. Una visita a un parque de atracciones les da a ambos una segunda oportunidad.', 26, '1963-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 2, 'Acero', 'Un promotor de poca monta que necesita dinero desesperadamente, sustituye a su robot averiado en una pelea ilegal, donde los humanos no pueden participar.', 26, '1963-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 3, 'Pesadilla a 20000 pies', 'Nadie puede ver a la criatura que está destrozando el ala del avión. Nadie excepto un paciente mental al que acaban de dar el alta.', 26, '1963-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 4, 'El cronómetro', 'El tipo más bocazas y cansino, recibe un cronometro que lo puede detener todo. Todo, excepto a él.', 26, '1963-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 5, 'La última noche de un jockey', 'Al tocar fondo en su vida, el jinete de carreras Grady decide que ya es hora de abandonar su actual vida y convertirse en un hombre de provecho. Su deseo le es concedido por su doble, pero el precio a pagar es muy alto.', 26, '1963-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 6, 'La muñeca viviente', 'Erich no se ha tomado nada bien que su esposa haya comprado una carísima muñeca para su hijastra. Pero su enfado se incrementa aún más, cuando la muñeca habla para decirle que él no le gusta.', 26, '1963-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 7, 'El viejo de la gruta', 'Un misterioso guardián ayuda a una pequeña comunidad a sobrevivir, cuando una bomba destruye la mayor parte del planeta.', 26, '1963-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 8, 'El tío Simon', 'Para poder heredar las propiedades de su tío, una mujer debe probar el último invento de este. El problema radica en que el invento, tiene la insoportable personalidad del fallecido.', 26, '1963-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 9, 'Vuelo 7 a la base', 'Los supervivientes de dos planetas aniquilados, quedan varados juntos en un planeta distante.', 26, '1963-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 10, 'La caballería fantasma', 'Una unidad moderna de la Guardia Nacional, queda atrapada junto al teniente Custer en la batalla de Little Big Horn.', 26, '1963-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 11, 'Un trago de esa fuente', 'Tratando de seguir el ritmo de su joven esposa, Harmon convence a su hermano para que le administre un suero rejuvenecedor experimental.', 26, '1963-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 12, '90 años de insomnio', 'Un anciano teme que su vida llegue a su fin, si el reloj de su abuelo deja de funcionar.', 26, '1963-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 13, 'La chica rutilante', 'Un regalo de un club de fans, hace que una famosa estrella de cine regrese a su hogar. Cuando llega, está a punto de comenzar una feria campestre anual, por lo que decide montar un espectáculo coincidiendo con la feria y obligando a la gente a elegir a cual acudir.', 26, '1963-12-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 14, 'La conciencia', 'Conduciendo de regreso a casa en una tarde lluviosa, Oliver Pope atropeña a un niño en bicicleta y asustado, decide escapar del lugar. Pero su coche tiene otras intenciones.', 26, '1964-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 15, 'La larga jornada', 'Antes de partir en una importante misión que durará décadas, el astronauta Douglas Stansfield conoce a una mujer y se enamora de ella.', 26, '1964-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 16, 'El perfeccionamiento de Salvadore Ross', 'Un hombre se percata de que puede intercambiar ciertas características con otras personas.', 26, '1964-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 17, 'El número 12 es exactamente como usted', 'En un futuro lejano, todos están obligados a parecerse. Para tal fin, todos aquellos que cumplen 19 años, deben someterse a una operación, pero una mujer trata desesperadamente de aferrarse a su propia identidad.', 26, '1964-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 18, 'Los invasores', 'Tres moteros de aspecto rudo se mudan a un tranquilo vecindario. Los vecinos no pueden ni imaginar, lo peligrosos que pueden llegar a ser estos hombres...', 26, '1964-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 19, 'Llamada nocturna', 'Una anciana en silla de ruedas, recibe extrañas llamadas anónimas durante la noche.', 26, '1964-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 20, 'A Agnes con amor', 'Un ingeniero informático debe lidiar con una mujer realmente peligrosa: una computadora llamada Agnes, la cual causa estragos en su vida amorosa.', 26, '1964-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 21, 'La emoción del momento', 'Después de ser perseguida a caballo por una aterradora figura de negro, Anne Henderson se enfrenta a la decisión más importante de su vida.', 26, '1964-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 22, 'El suceso del puente de Owl Creek', 'Cuando un espía confederado está a punto de ser ahorcado, la cuerda se rompe y cae al río. Finalmente libre, corre desesperadamente hacia su casa, donde le espera su familia... al igual que la terrible verdad sobre su futuro.', 26, '1964-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 23, 'Reina del Nilo', 'El periodista Jordan Herrick se sorprende al saber que una famosa actriz de cine no ha envejecido en años. Intrigado, decide investigar... y pronto descubre un aterrador secreto.', 26, '1964-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 24, 'El programa del canal 10', 'Un marido infiel ve su secreto revelado y sus horribles consecuencias, en la televisión que acaban de repararle.', 26, '1964-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 25, 'Las máscaras', 'Un hombre moribundo le entrega a su familia una serie de máscaras y les exige que las usen durante el Mardi Gras (Carnaval de Nueva Orleans).', 26, '1964-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 26, 'Yo soy la noche... píntame de negro', 'El día que se procede a la ejecución de un hombre condenado a muerte por el asesinato de un conocido racista, el pueblo se sorprende al ver como el cielo se vuelve negro.', 26, '1964-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 27, 'Sonidos y silencio', 'Un hombre desea escuchar ruidos fuertes. Pero a veces hay que tener cuidado con lo que se desea.', 26, '1964-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 28, 'Cesar y yo', 'Un muñeco de ventrílocuo incita a su propietario a cometer robos.', 26, '1964-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 29, 'La habitación siniestra', 'Un agente de la KGB ha recibido la orden de acabar con un desertor. Sin embargo, le propone un juego, dándole tres horas para encontrar y desactivar una bomba, que ha escondido en su habitación.', 26, '1964-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 30, 'El pueblo silencioso', 'Bob y Millie despiertan en una ciudad que no conocen y en donde no hay nadie. Mientras investigan los alrededores se percatan de que todo es falso: los árboles, los animales, los coches...', 26, '1964-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 31, 'El encuentro', 'Un veterano de la Segunda Guerra Mundial y un jardinero japonés-estadounidense, luchan entre sí por una guerra que terminó hace más de 20 años.', 26, '1964-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 32, 'El señor Garity y los muerto', 'Jared Garrity llega a la ciudad de Happiness, en Arizona, proclamando que puede revivir a los muertos.', 26, '1964-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 33, 'El centro de control de Whipples', 'El director general de una fábrica, reemplaza a los trabajadores humanos por máquinas.', 26, '1964-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 34, 'Ven a vagar conmigo', 'Un cantante busca una canción que se haga famosa.', 26, '1964-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 35, 'El temor', 'Dos personas aisladas en un remoto lugar, encuentran signos de vida extraterrestre.', 26, '1964-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 5), 36, 'La piscina encantada', 'Dos niños que juegan en la piscina de su casa, son teletransportados a otro lugar, donde conocen a unas personas muy interesantes.', 26, '1964-06-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')), 1, 'Temporada 1', 'Es el año 2264.201 años después de que el hombre viajara por primera vez a mayor velocidad que la luz, y 113 años después del primer viaje de la Enterprise NX-01, el capitán James T. Kirk y su tripulación parten en la nave de clase Constitución USS Enterprise. En el transcurso de los 3 primeros años, la tripulación del Enterprise se encontrará con criaturas que cambian de forma y artistas del engaño, asesinos y locos, seres lo bastante poderosos como para controlar las mentes de sociedades enteras, y seres demasiado débiles como para controlar sus propios poderes mentales. Los tripulantes de la Enterprise serán amados, amenazados, engatusados, asesinados, les ofrecerán parejas para copular, serán divididos en dos, resucitados, y lanzados hacia atrás en el tiempo. Se verán forzados a luchar por sus vidas y por las vidas de sus amigos. Y a lo largo de todas esas pruebas, se irá forjando un vínculo entre tres insólitos amigos: el valiente y carismático capitán, el irascible doctor, y el Vulcaniano sin emociones. El viaje ha comenzado.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 1, 'La trampa humana', 'Durante una visita a una colonia de la Tierra, el Doctor McCoy se encuentra con una antigua novia. A pesar de seguir tan atractiva como hace años, la mujer guarda un secreto terrorífico.', 50, '1966-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 2, 'Charlie X', 'El Enterprise recoge a un niño de 17 años, Charles Evans, que ha sido criado por seres alienígenas. La tripulación pronto descubrirá que Charlie cuenta con unos extraordinarios poderes que pueden ser muy peligrosos en manos de una persona de tan corta edad.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 3, 'Un lugar jamás visitado por el hombre', 'El USS Enterprise viaja hasta los límites de la galaxia donde se encuentra con un gran campo de fuerza. Influenciado por este fenómeno físico, uno de los tripulantes adquiere grandes poderes que van aumentando hasta llegar a convertirle en un ser todo poderoso. También es influenciada por este fenómeno una doctora.', 51, '1966-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 4, 'Horas desesperadas', 'Un extraño virus provoca que la tripulación del Enterprise se comporte de un modo extraño, perdiendo todo tipo de vergüenza y comportándose de una forma cada vez más desinhibida. En esta situación, el Enterprise pierde la órbita y va siendo atraído por la gravedad de un planeta.', 51, '1966-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 5, 'El propio enemigo', 'Una avería en el transportador provoca que el Capitán Kirk se materialice como dos personas diferentes. Una extremadamente malvada y la otra totalmente opuesta. Pronto descubrirán que la dependencia entre uno y otro es mayor de lo que podían imaginar.', 50, '1966-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 6, 'Las chicas de Mudd', 'El Enterprise rescata a la tripulación de una nave que se encuentra en el interior de un campo de asteroides. Al frente de esta tripulación se encuentra Harry Mudd, uno de los mayores timadores de la galaxia, que, acompañado de tres bellas mujeres, causará grandes problemas al Capitán Kirk.', 50, '1966-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 7, '¿De qué están hechas las niñas pequeñas?', 'La tripulación del Enterprise encuentra al Doctor Korby, que está trabajando en un extraño proyecto. Pronto descubrirán que se trata de crear androides idénticos a una persona y capaces de sustituirla, y empieza por el Capitán Kirk.', 50, '1966-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 8, 'Miri', 'El Enterprise encuentra un planeta que está habitado solamente por niños. El equipo de salida contrae un extraño virus que mata a los adultos pero que no afecta a los niños.', 50, '1966-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 9, 'La daga de la mente', 'Kirk descubre que un loco que ha escapado de la Colonia Penal Tántalus es en realidad uno de los miembros del personal psiquiátrico. Este hecho tan extraño le lleva a investigar y descubre que allí se están haciendo una serie de experimentos para controlar la mente.', 50, '1966-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 10, 'Las maniobras de la corbomita', 'El Enterprise se enfrenta a una poderosa nave alienígena. Ante la superioridad armamentística del enemigo, Kirk decide inventar que lleva una poderosa arma que destruiría ambas naves como único argumento para sobrevivir.', 50, '1966-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 11, 'La colección de fieras (1)', 'Kirk, Spock y McCoy visitan al antiguo Capitán Christopher Pike, que estuvo al mando del Enterprise y que se encuentra paralítico y deformado. Tras su encuentro, Spock secuestra el Enterprise para llevarlo a un extraño planeta y se entrega después.', 49, '1966-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 12, 'La colección de fieras (2)', 'En el transcurso del Consejo de Guerra a Spock, cuenta cómo visitó junto al Capitán Pike el planeta Talos IV y cómo Cristopher Pike fue secuestrado por sus habitantes con el fin de que se aparease con una mujer humana.', 50, '1966-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 13, 'La conciencia del rey', 'Kirk está persiguiendo a un conocido asesino en serie, tras haber sido contactado por una persona que asegura haber sido testigo de sus crímenes. Sospecha que puede estar camuflado en un grupo de actores de teatro.', 50, '1966-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 14, 'El equilibrio del terror', 'El Enterprise se enfrenta a una nave romulana. Esta raza no ha sido nunca antes vista con anterioridad y su asombroso parecido con los vulcanianos hace que la tripulación empiece a tener sospechas de Spock.', 50, '1966-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 15, 'El permiso', 'Durante una visita a un planeta, McCoy cree estar sufriendo una alucinación cuando ve al conejo de Alicia en el país de las maravillas. Pronto descubre que ese planeta tiene la peligrosa capacidad de hacer realidad cualquier pensamiento.', 50, '1966-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 16, 'Galileo séptimo', 'La lanzadera Galileo siete sufre un aterrizaje forzoso en un planeta habitado por unos seres hostiles. Todo intento de comunicarse con el Enterprise para huir se ve frustrado.', 50, '1967-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 17, 'El escudero de Gothos', 'El Enterprise encuentra un planeta desconocido en el que habita un ser todo poderoso con grandes poderes psicológicos.', 50, '1967-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 18, 'La arena', 'Kirk y un capitán alienígena con forma de reptil son enviados a un planeta por unos seres que pretenden que luchen hasta la muerte para que salven sus vidas y la de sus tripulaciones.', 51, '1967-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 19, 'El mañana es ayer', 'El Enterprise viaja en el tiempo hasta la Tierra del Siglo XX, donde rescatan a un piloto de un avión de combate. Pronto surge el problema de cómo hacer regresar a esta persona sin alterar el futuro del planeta.', 50, '1967-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 20, 'Consejo de guerra', 'Kirk se enfrenta a un Consejo de Guerra, acusado de una negligencia que ha matado a un miembro de su tripulación. Cuando descubre que uno de los miembros del Tribunal es una antigua amante, Kirk teme por el futuro de su carrera, que parece estar acabada.', 50, '1967-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 21, 'El retorno de los Arcontes', 'Durante la visita al planeta Beta III, Kirk y su tripulación descubren una sociedad aparentemente seria hasta la llegada de lo que denominan la Hora Roja.', 50, '1967-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 22, 'Semilla espacial', 'El Enterprise encuentra a la deriva a la nave SS Bahía Botánica que transporta en estado de hibernación a hombres tratados genéticamente que pertenecen al siglo XX. El líder de esta tripulación es el malvado Khan.', 50, '1967-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 23, 'El apocalipsis', 'Durante años, los planetas Eminiar VIII y Vendikar han sufrido una extraña guerra en la que los ordenadores deciden las personas que deben presentarse para ser ejecutadas como víctimas de guerra. Pronto los miembros de la tripulación del Enterprise serán seleccionados como víctimas.', 50, '1967-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 24, 'Esa cara del paraíso', 'Unos colonos han estado sobreviviendo durante años a una radiación mortal gracias a unas esporas del planeta en el que habitan. La tripulación de Kirk pronto descubre que esas esporas tienen otros efectos mucho más preocupantes.', 50, '1967-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 25, 'El diablo en la oscuridad', 'Kirk y Spock investigan la muerte de varios mineros en el planeta Janus VI. Pronto descubren una extraña criatura que parece ser la causante de esas muertes y gracias a la fusión mental de Spock descubren el motivo que ha llevado a la criatura a matar.', 50, '1967-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 26, 'Tentativa de salvamento', 'Kirk y Spock se ofrecen para proteger a los habitantes de un planeta que se encuentra entre los límites de la Federación y el Imperio Klingon. Con lo que no cuentan es con la respuesta de una raza llamada Organianos.', 50, '1967-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 27, 'El factor alternativo', 'El Enterprise contacta con un hombre llamado Lazarus que parece tener una doble personalidad que hace que su comportamiento por momentos parezca el de dos personas diferentes y opuestas.', 51, '1967-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 28, 'La ciudad en el límite del tiempo', 'McCoy se interna en un portal temporal que le lleva a la Tierra del Siglo XX. Conscientes de que las acciones del Doctor pueden cambiar el futuro, Kirk y Spock deciden ir en su búsqueda para traerle de regreso.', 50, '1967-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 29, 'Operación: Aniquilación', 'McCoy está tratando de ayudar a los habitantes de un planeta que sufre una inexplicable epidemia de locura. Durante el transcurso de los experimentos para tratar de encontrar una vacuna, el Doctor provoca la ceguera de Spock, sin saber cuál ha sido la causa.', 50, '1967-04-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')), 2, 'Temporada 2', 'Es el año 2267. Para la tripulación de la USS Enterprise, la galaxia debe parecer un sitio abiertamente hostil. Este año, la vía láctea será víctima de los ataques de al menos tres entes destructores de planetas y que incluyen a una máquina que busca la perfección, a un robot gigante y a una criatura parecida a una inmensa ameba unicelular. La fe en nuestros superiores se verá debilitada ya que un Comodoro de la Flota Estelar pierde el juicio tras perder a toda su tripulación, un embajador de alto rango es acusado de asesinato en la nave Enterprise y un capitán de la Flota Estelar traiciona a su tripulación al ofrecerles que elijan entre una vida de lujo o el estadio de los gladiadores de un planeta al estilo romano.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 1, 'La época de Amok', 'Spock tiene que regresar rápidamente a su planeta al sufrir el Pon farr, un síndrome que provoca la necesidad de apareamiento en los vulcanianos cada siete años. Kirk se verá involucrado en Vulcano en un ritual que le enfrentará en una lucha a muerte con su primer oficial.', 50, '1967-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 2, '¿Quién llora por Adonis?', 'Ante su incredulidad, Kirk y su tripulación se encuentran en el planeta Polux IV con el Dios griego Apolo, que no duda en secuestrarles y que pretende que se queden con él hasta la eternidad. Kirk tendrá que diseñar un plan para poder escapar de la amenaza.', 51, '1967-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 3, 'El suplantador', 'Kirk busca la forma de desactivar una poderosa máquina que ya ha destruido gran cantidad de planetas y que ahora está atacando a su tripulación. La máquina cree que Kirk es su creador y éste intentará utilizar este hecho como ventaja en la desactivación del engendro mecánico.', 50, '1967-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 4, 'Espejo, espejito', 'Por una avería del transportador, Kirk, Spock, McCoy y Uhura se encuentran en un universo alternativo en el que todo es diferente y en el que reina el mal. La sorpresa será enorme cuando se enfrenten a sus propios homólogos en forma de malvados villanos y tengan que buscar la forma de volver a su propia realidad.', 50, '1967-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 5, 'La manzana', 'La tripulación del Enterprise visita el planeta Gamma Trianguli VI, habitado por unos humanoides de aspecto siempre joven. Pronto descubren que el propio planeta parece intentar asesinarles a través de una especie de Dios artificial.', 50, '1967-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 6, 'La máquina del día del Juicio Final', 'El comodoro Matt Decker es el único superviviente de un enfrentamiento contra una poderosa nave-máquina que ha destruido varios planetas de la galaxia: la máquina del Juicio Final. Abusando de su rango, Decker quiere vengar su nave, utilizando el Enterprise como arma contra el poderoso enemigo.', 51, '1967-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 7, 'Los cuatro gatos', 'Unos extraños alienígenas se divierten con la tripulación del Enterprise y convierten a Scotty y Sulu en una especie de zombis. Kirk tratará de encontrar la forma de liberar a la nave y a su tripulación.', 50, '1967-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 8, 'Yo, Mudd', 'Harry Mudd se encuentra atrapado en un planeta en el que unas hermosas androides femeninas le tienen secuestrado. Como plan para escapar, decide atraer al Enterprise para que su tripulación pueda sustituirle y así marcharse.', 51, '1967-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 9, 'Metamorfosis', 'Kirk viaja en una lanzadera transportando a Nancy Hedford, una diplomática en la última fase de una enfermedad llamada Sakuro. La lanzadera es desviada por alguien a un planeta donde está Zefram Cochrane, el descubridor de la velocidad warp.', 50, '1967-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 10, 'El viaje a Babel', 'El Enterprise transporta a varios embajadores que van a participar en una conferencia. Durante el trayecto el embajador telarita es asesinado y todas las pruebas apuntan a que el causante de su muerte ha sido el embajador de Vulcano, Sarek, el padre de Spock.', 50, '1967-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 11, 'Hijo de un jefe', 'Durante las negociaciones de la Federación con una colonia minera, un klingon convence a un grupo de mineros para que asesinen a su jefe y tomen el poder. Kirk tendrá que proteger a su esposa y a su futuro hijo de la rebelión.', 50, '1967-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 12, 'Los años de la muerte', 'La tripulación del Enterprise encuentra a los habitantes de la colonia Gamma Hidra IV muriendo a causa de una vejez anticipada y acelerada. Cuando regresan a la nave descubren que todos los tripulantes están sufriendo el mismo proceso de envejecimiento salvo uno, Pavel Chekov.', 50, '1967-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 13, 'Obsesión', 'Kirk vuelve a encontrarse de nuevo con un ser que obtiene los glóbulos rojos de la tripulación causando su muerte. Para evitar caer en el mismo error que la anterior vez en la que se enfrentó con un ser similar, Kirk decide que la única solución es eliminar a la criatura.', 50, '1967-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 14, 'Un lobo en el redil', 'Scotty está disfrutando de un permiso en un local argeliano con una hermosa bailarina. Pronto la bailarina aparece asesinada y todas las pruebas conducen a que el autor del crimen ha sido el propio Scotty. Así comenzará una difícil lucha para demostrar su inocencia.', 51, '1967-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 15, 'Los Tribbles y sus tribulaciones', 'Durante una misión de escolta de un cargamento a una estación espacial, Kirk descubre un plan de los Klingon contra la Federación ayudándose de unos diminutos seres peludos que se reproducen continuamente, los tribbles.', 50, '1967-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 16, 'Los jugadores de Triskelion', 'Kirk, Uhura y Chekov son obligados a luchar como gladiadores en el planeta Triskelion. Como única opción de liberación, Kirk se verá obligado a apostar el Enterprise para tratar de escapar de semejante infierno.', 50, '1968-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 17, 'Parte de la acción', 'Los habitantes de un extraño planeta han reconstruido su sociedad basándola en las bandas de la ciudad de Chicago en la segunda década del Siglo XX. Con el fin de obtener su cooperación, Kirk se ve obligado a asumir el papel de líder de la mafia.', 50, '1968-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 18, 'Síndrome de inmunidad', 'El Enterprise descubre que toda la vida existente en un sistema solar ha sido aniquilada por una extraña criatura similar a una ameba. Kirk y su tripulación tendrán que buscar la forma de salvar sus vidas y la de los millones de seres que habitan sistemas solares cercanos.', 50, '1968-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 19, 'Una pequeña guerra privada', 'La tripulación del Enterprise descubre una primitiva civilización que sorprendentemente ha desarrollado rápidamente la capacidad de armarse. Durante su investigación Kirk resulta herido y es curado por una mujer cuya mayor obsesión es hacerse con el armamento de la Federación.', 51, '1968-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 20, 'Vuelta al mañana', 'Durante una inspección a un planeta que parece estar deshabitado, una patrulla del Enterprise descubre tres seres incorpóreos de gran inteligencia que les piden temporalmente el cuerpo de tres tripulantes.', 50, '1968-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 21, 'Por medio de la fuerza', 'El historiador John Gill parece haber violado la primera Directriz que implica no involucrarse en culturas no desarrolladas lo suficientemente, al haber introducido en una raza llamada ekosianos la ideología nazi. Kirk decide descubrir qué es lo que ha ocurrido, simulando ser un oficial nazi.', 50, '1968-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 22, 'Con cualquier otro nombre', 'El Enterprise cae en una trampa al acudir a una llamada de socorro falsa. Cinco Kelvanos secuestran la nave con el fin de realizar un viaje que durará 300 años para regresar a su planeta, situado en la galaxia de Andrómeda.', 50, '1968-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 23, 'El esplendor de Omega', 'La tripulación del Enterprise se encuentra con la tripulación fallecida del USS Exeter a causa de un virus desconocido. En un planeta cercano existe la cura y allí encuentran al capitán del Exeter que no ha dudado en violar la primera directriz con tal de salvarse.', 50, '1968-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 24, 'El mejor ordenador', 'La Federación está investigando una potente máquina que puede llegar a sustituir a los capitanes de las naves estelares. Durante unas prácticas, la máquina, instalada en el Enterprise, no funciona correctamente y destruye a varias naves de la Federación. Recuperar el control no va a ser tarea fácil.', 50, '1968-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 25, 'Pan y circo', 'El Enterprise se encuentra con la USS Beagle, que lleva desaparecida varios años. La tripulación de la Beagle se ha refugiado en un planeta en el que han fundado una sociedad similar a la antigua civilización romana de la Tierra y en la que el antiguo Capitán ha sido nombrado Emperador.', 50, '1968-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 2), 26, 'Misión: La Tierra', 'El Enterprise ha sido enviado a una misión al año 1968. En Nueva York, Kirk y Spock descubren a un tal Gary Seven que dice haber sido criado y entrenado por extraterrestres con el fin de impedir la destrucción de la humanidad.', 50, '1968-03-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')), 3, 'Temporada 3', 'Es el año 2268. Éste no va a ser un buen año para el capitán James T. Kirk. En los próximos meses, a Kirk le borrarán la memoria, se verá forzado a tomar parte en el duelo de O.K. Corral, quedará atrapado entre universos alternativos, su tiempo personal será acelerado de tal forma que será invisible para sus amigos, será torturado por sádicos Vianos, su cuerpo se cambiará por el de una hermosa mujer, y será “asesinado” por su primer oficial vulcaniano. Mientras la nave Enterprise se enfrenta a naves de guerra romulanas, un asteroide está a punto de colisionar, y suceden aventuras más allá de los límites de la Galaxia. La tripulación tendrá que vérselas con sicópatas criminales que cambian de forma, asesinos en serie, “hippies” revolucionarios interplanetarios, y seres con el poder de matar a los miembros de la tripulación simplemente tocándoles. Afortunadamente, los oficiales de Kirk demostrarán tener el valor, la inteligencia y la resolución que les ha convertido en una leyenda dentro de la Federación. A menos, claro está, que contraigan una enfermedad terminal; o que les roben los cerebros.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 1, 'El cerebro de Spock', 'Una hermosa alienígena roba el cerebro de Spock dejando inconsciente a toda la tripulación del Enterprise. Comenzará una angustiosa cuenta atrás para recuperar el cerebro y evitar su muerte.', 51, '1968-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 2, 'El incidente del Enterprise', 'El Enterprise se dirige a la zona neutral donde es emboscado por dos naves romulanas. Kirk se verá obligado a demostrar todo su ingenio con la complicidad de Spock para poder salir de una situación tan complicada.', 51, '1968-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 3, 'Síndrome del paraíso', 'Un gran asteroide está a punto de chocar contra un planeta y la nave Enterprise acude en su ayuda. Intentando detener el choque, el capitán Kirk sufre un accidente que le borra la memoria y esto provoca que el impacto no vaya a poder ser evitado.', 51, '1968-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 4, 'Y los niños dirigirán', 'Los adultos de la colonia situada en Triacus han fallecido mientras que los niños se encuentran en perfecto estado. La tripulación descubre que los niños están siendo manipulados por una extraña fuerza que busca un objetivo.', 51, '1968-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 5, '¿No hay en verdad belleza?', 'El Enterprise transporta a tres peculiares pasajeros. Uno de ellos provoca que la nave estelar sea desplazada a los límites de la galaxia dificultando su retorno.', 51, '1968-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 6, 'Espectros', 'El Enterprise establece contacto con el planeta Melkotian a pesar de sus advertencias para que se alejen. A la tripulación se le acusa de intrusa y se les castiga con una simulación del Oeste Americano que podría conducirles a una muerte segura.', 51, '1968-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 7, 'El día de la paloma', 'Un comandante klingon reclama el Enterprise como botín de guerra por los daños causados a su nave. Durante la disputa, un alienígena se aprovecha para atacar por igual a klingon y humanos.', 51, '1968-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 8, 'Pues el mundo es hueco y yo he tocado el cielo', 'Kirk descubre que McCoy sufre una extraña enfermedad terminal y se ve obligado a investigar un asteroide que resulta ser una nave espacial tripulada por humanoides. McCoy se enamora de la dirigente de este grupo de seres.', 51, '1968-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 9, 'La telaraña Tholiana', 'El Enterprise se encuentra con el USS Defiant con toda su tripulación muerta y oscilando entre dos universos. Kirk se ve atrapado en este proceso y unas naves enemigas aprovechan el momento para intentar capturar al Enterprise.', 50, '1968-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 10, 'Los hijastros de Platón', 'McCoy acude a ayudar a un Platoniano enfermo. Tras conseguir curarle, esta raza decide que es una persona demasiado valiosa como para que se marche y los extraordinarios poderes psicológicos de estos seres dificultarán su regreso al Enterprise.', 51, '1968-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 11, 'El parpadeo de un ojo', 'La tripulación del Enterprise descubre una ciudad desierta en el planeta Scalos. Pronto descubren que todo el que bebe algún tipo de líquido allí desaparece sin dejar rastro, tratándose de una trampa para poder secuestrarlos.', 51, '1968-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 12, 'La empática', 'Kirk, Spock y McCoy se encuentran atrapados en un planeta a causa de una tormenta. Allí conocen a una alienígena con poderosos poderes curativos. Sin embargo, son capturados por una raza que les provoca horribles torturas que podrían llevarles a la muerte.', 51, '1968-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 13, 'Elaan de Troyius', 'El Enterprise lleva a una pasajera a una boda que favorecerá la paz entre dos planetas en guerra. Amenazados por los Klingon, se ven obligados a realizar el viaje con las comunicaciones desconectadas. Pero el comportamiento de la ilustre pasajera no es el ideal.', 51, '1968-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 14, 'A quienes los dioses destruyan', 'El Enterprise llega a un planeta en el que se encuentra situado un hospital de alta seguridad para asesinos psicópatas. La sorpresa será mayúscula al descubrir que el hospital es controlado por un peligroso interno con la capacidad de poder cambiar de forma.', 51, '1969-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 15, 'Que ése sea su último campo de batalla', 'El Enterprise acaba de rescatar a Lokai, un extraterrestre que tiene la mitad del rostro negro y la otra mitad blanco. Pronto contacta con ellos Bele, un extraterrestre similar a Lokai pero con los colores inversos y que denuncia que Lokai es un traidor.', 51, '1969-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 16, 'La marca de Gídeon', 'Kirk se transporta al planeta Gídeon pensando que se trata de un lugar idílico. Sin embargo, al llegar allí se encuentra con un planeta superpoblado en el que se están asesinando a grandes cantidades de habitantes y además descubre que ha perdido repentinamente la memoria.', 51, '1969-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 17, 'Aquello que sobrevive', 'Un planeta ha desarrollado un medio ambiente habitable en menos de 10000 años. El Enterprise acude a investigar el fenómeno y allí son atacados por un ser capaz de matar con un solo roce.', 51, '1969-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 18, 'Las luces de Zetar', 'La Memoria Alfa ha sido diseñada para almacenar todo el conocimiento científico y cultural de todos los planetas que forman la Federación. De repente sufre un ataque de una especie de tormenta que destruye toda la vida del planeta y que pretende hacer lo mismo con la tripulación del Enterprise.', 51, '1969-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 19, 'Réquiem por Matusalén', 'Kirk está buscando un antídoto contra la fiebre rigeliana. Durante la búsqueda conoce a un hombre llamado Flint y a una mujer llamada Rayna. Aunque Flint parece poder ayudar en la búsqueda del antídoto, su comportamiento pronto empieza a cambiar al no estar muy conforme con el comportamiento de Rayna y Kirk.', 51, '1969-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 20, 'El camino al Edén', 'El Enterprise persigue a una nave que ha sido robada. Durante la persecución la nave perseguida explota, siendo transportada su tripulación antes de la explosión a bordo del Enterprise. Su líder es un demente portador de una extraña enfermedad.', 51, '1969-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 21, 'Los guardianes de la nube', 'El Enterprise visita el planeta Ardana, habitado por dos sociedades de la que una es esclava de la otra. Kirk descubre que ambas sociedades son una misma raza y decide que es el momento de que la situación en la que se encuentran finalice.', 51, '1969-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 22, 'El telón salvaje', 'Durante la inspección de un planeta aparentemente deshabitado, Kirk y Spock se encuentran con un hombre que dice ser Abraham Lincoln y que les presenta a otros famosos personajes históricos. Kirk y Spock se dan cuenta que se trata de un truco cuya única finalidad es que peleen entre ellos.', 51, '1969-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 23, 'Todos nuestros ayeres', 'El sol del planeta Sarpeidón está a punto de estallar. Cuando el Enterprise acude al rescate de la población, se encuentran con que el planeta está desértico. Sus habitantes han utilizado una máquina del tiempo para viajar al pasado y escapar de la amenaza. Kirk, Spock y McCoy no dudan en utilizar la máquina para ir en su búsqueda.', 51, '1969-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 24, 'La intrusa traidora', 'Durante un proceso de fusión mental y física para tratar de salvar a una mujer de un envenenamiento por radiación, Kirk intercambia su personalidad con la de Janice Lester dejando a Kirk con el cuerpo de Janice y a ésta con la posibilidad de disponer del cuerpo de Kirk.', 51, '1969-06-03');
