INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 3), 1, 'Episodio 1', NULL, 25, '1974-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 3), 2, 'El puente del arcoiris', 'Mientras Hawkeye y Trapper planean partir hacia Tokio, llega una oferta inusual para intercambiar pacientes prisioneros de guerra entre los chinos y el 4077. Henry, después de mucho debate, acepta enviar a Hawkeye, Trapper, Frank, Radar y Klinger a territorio enemigo. Frank casi arruina el intercambio cuando trae una pistola de agua al intercambio. Afortunadamente, el Dr. chino Lin Tam tiene sentido del humor; después de todo, fue a la Universidad de Illinois.', 25, '1974-09-17');
