INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 1, 'Aparece y desaparece.', 'Frank Burns se enoja por el matrimonio de Margaret mientras estaba en R&R en Tokio, y el mayor Charles Emerson Winchester III es enviado al 4077 como reemplazo por un vengativo oficial superior.', 50, '1977-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 2, 'Ídolo caído', 'Radar siempre ha admirado a Hawkeye y lo admiraba como su héroe. Pero después de sufrir un accidente de Jeep en camino a R&R a instancias de Hawkeye. Radar cuestiona su propio culto al héroe. Particularmente cuando él y su héroe tienen una pelea.', 25, '1977-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 3, 'Última risa', 'La locura golpea cuando B.J. y su viejo amigo Bardonaro juegan una serie de bromas prácticas el uno al otro, justo cuando Bardonaro está a punto de abandonar Corea. Hawkeye consigue la última risa. Envía a Bardonaro sin sus papeles de viaje, y en un jeep con muy poca gasolina.', 25, '1977-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 4, 'Guerra de nervios', 'El 4077, atrapado en la tensión y los nervios, crea una hoguera para liberar su presión. Mientras tanto, Sidney Freedman está deprimido por un joven soldado que lo culpa por sus heridas, porque Freedman lo había enviado nuevamente al combate.', 25, '1977-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 5, 'Las grabaciones de Winchester', 'Hawkeye intenta sin éxito llegar a Seúl para ver a la enfermera Gilmore durante el fin de semana. Mientras tanto, Winchester ha grabado una carta en su casa pidiéndole a sus influyentes padres que lo ayuden a regresar a los Estados Unidos. Para desquitarse, Hawkeye y B.J. cambian la ropa de Winchester, haciendo que Winchester altere sus patrones de alimentación.', 25, '1977-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 6, 'La luz que falló', 'Con suministros bajos, el 4077th recibe una gran cantidad de heladeras y tabletas de sal. Pero lo que necesita son bombillas, y en el postoperatorio poco iluminado, Charles comete un error por el cual dibuja la ira de sus dos compañeros cirujanos. Mientras tanto, B.J. recibe una novela de misterio que todos en el campamento leen a su vez. Falta la última página y la solución al misterio no se descubre hasta que B.J. llama al autor a larga distancia.', 25, '1977-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 7, 'En el amor y la guerra', 'Hawkeye se enamora de Kyong Soon, una mujer coreana que cuida a su madre enferma y a sus hijos huérfanos. Pero toda esperanza se pierde cuando Kyong se lleva sus posesiones y los niños al sur después de que su madre ha muerto.', 25, '1977-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 8, 'Cambiar día', 'Charles planea un plan para hacerse rico cuando descubre que la escritura azul se cambiará por roja. Hawkeye y B.J. lo engañaron, y se quedó con el scrip inútil. Klinger intenta ingresar a West Point para poder salir de Corea.', 25, '1977-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 9, 'Imágenes', 'Radar nota varios tatuajes en uno de los heridos y se convence de que con un tatuaje será irresistible para las mujeres. Todos tratan de desanimarlo, y él admite haber recibido un tatuaje que desaparecerá. Mientras tanto, Margaret se siente frustrada con una nueva enfermera que se molesta al ver las lesiones de combate.', 25, '1977-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 10, 'Los Juegos Olímpicos M * A * S * H', 'El coronel Potter, al decidir que el campamento no está en forma, aplica un curso de calistenia. Cuando nadie lo disfruta, se divierte dividiendo el campamento en dos equipos. Estos equipos compiten por pases de R&R de tres días. Klinger intenta salir del ejército engordando.', 25, '1977-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 11, 'La parca', 'El coronel Bloodworth amenaza con presentar cargos de corte marcial contra Hawkeye, quien lo empujó en el bar. Pero luego se vuelve paciente y es testigo de las habilidades de Hawkeye. Klinger se une con un paciente de su ciudad natal.', 25, '1977-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 12, 'Camaradas de armas: parte 1', 'Perdidos detrás de las líneas enemigas, Hawkeye y Margaret forman una tregua personal y buscan refugio en una cabaña en la carretera.', 25, '1977-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 13, 'Episodio 13', NULL, 25, '1977-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 14, 'El mercader de Corea', 'Después de que Charles le entrega a BJ doscientos dólares, comienza a aprovechar. Todos se reúnen y persuaden a Charles para que juegue al póker. Tiene una increíble suerte de principiante hasta que Radar descubre que Charles silba ruidosamente cuando farolea. Todos recuperan su dinero y algo más.', 25, '1977-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 15, 'El olor de la música', 'Hawkeye y BJ se niegan a ducharse hasta que Charles deja de tocar su trompa y el Coronel Potter trata con un paciente que quiere suicidarse porque ahora está desfigurado.', 25, '1978-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 16, 'Patente 4077', 'Al necesitar una pinza quirúrgica especial, Hawkeye y B.J. contratan al Sr. Shin, un distribuidor local de joyas, para que lo haga. Días después, la pinza se usa para salvar la pierna de un soldado herido. El Sr. Shin entra en el negocio de suministros quirúrgicos.', 25, '1978-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 17, 'Té y empatía', 'Con las bajas británicas y estadounidenses pesadas, el suministro de penicilina de la 4077a ha sido robado. El padre Mulcahy descubre, del cabo Bryant, la ubicación de un poco de penicilina, y él y Klinger salen a buscarla. Les disparan, pero regresan con seguridad con la droga y salvan el día.', 25, '1978-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 18, 'Su  Hit Parade', 'Con la llegada de un envío de discos, Radar interpreta el papel de un disc jockey y ayuda a todos a superar el increíblemente largo diluvio de heridos.', 25, '1978-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 19, '¿Lo que hay de nuevo viejo?', 'Hot Lips, creyendo estar embarazada, le pide a Hawkeye que la pruebe. El único conejo disponible para la prueba es la mascota de Radar, Fluffy. Mientras tanto, Martinson, un paciente, retiene a Charles a punta de pistola y exige que lo envíen de regreso a Ohio.', 25, '1978-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 20, 'Tres llamadas de correo', 'Después de un retraso de tres semanas, llegan cinco sacos de correo, y todos en el campamento reaccionan a las buenas y malas noticias de casa. Hawkeye recibe cartas de amor dirigidas a otro Benjamin Pierce, otro hombre se ha acercado a la esposa de B.J. y la madre de Radar ha encontrado un novio. Klinger: "Puede que no tenga una familia en Toledo, pero tengo una aquí".', 25, '1978-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 21, 'Deber temporal', 'Con una transferencia temporal de personal entre el 4077 y el 8063, el Capitán Roy Dupree reemplaza a Hawkeye, mientras que Lorraine Anderson mira a Charles. Temiendo que esto sea permanente, Charles y BJ conspiran exitosamente para que Dupree sea removido permanentemente del 4077. Charles (a Hawkeye): "¡Dios, te extrañé!"', 25, '1978-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 22, 'Retiro de Potter', 'Cuando se presentan malos informes en la sede, el Coronel Potter contempla la jubilación.', 25, '1978-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 23, 'Dr. Winchester y Sr. Hyde', 'Charles toma anfetaminas para mantener su nivel de energía, e incluso droga el ratón de Radar, "Daisy", para que gane una carrera contra el ratón de un marine, "Sluggo".', 25, '1978-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 6), 24, 'Mayor Topper', 'Los médicos tienen que lidiar con una escasez de morfina y demasiados pacientes, mientras que Klinger tiene que lidiar con un cabo que puede estar más loco que él: derriba enemigos imaginarios.', 25, '1978-03-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')), 7, 'Temporada 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 1, 'Episodio 1', NULL, 25, '1978-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 2, 'Episodio 2', NULL, 25, '1978-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 3, 'Lil', 'El coronel Potter conoce a una soldado de la misma edad e intereses que él mismo, llamado Lil. Los otros en el campamento piensan que podría estar engañando a Mildred, a pesar de que su amistad con Lil es completamente platónica. Mientras tanto Hawkeye trata de averiguar qué significan las iniciales de B.J. Resulta que fue nombrado en honor a sus padres, Bea y Jay Hunnicutt.', 25, '1978-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 4, 'Nuestra mejor hora', 'La presentadora de noticias Clete Roberts, reporeuna de una aparición anterior en una entrevista, regresa para actualizar las condiciones de la Guerra de Corea, cuando lleva a cabo una serie de conversaciones televisivas con los personajes principales del 4077.', 45, '1978-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 5, 'El Síndrome de Billfold', 'Charles se vuelve tan irrateso, cuando es rechazado para un futuro puesto médico en casa, que se niega a hablar con nadie en la unidad, hasta que Hawkeye y B.J. le envían un telegrama falso desde casa. Mientras tanto, un joven soldado, Jerry Wilson, no puede recordar su propia identidad, así que Sidney Freedman es llamado a pedir ayuda.', 25, '1978-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 6, 'Calor insoportable', 'A medida que las temperaturas alcanzan tres dígitos, Hawkeye y BJ reciben su nueva bañera de goma de Abercrombie & Fitch. Sin embargo, pronto todo el campamento está caliente bajo el cuello como la palabra se filtra sobre la bañera y todo el mundo quiere un chapuzón, excepto Klinger, que está tratando de conseguir su Sección 8 por el uso de un abrigo de piel.', 25, '1978-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 7, 'Llaman al viento Corea', 'Una fuerte tormenta de viento afecta al personal de M * A * S * H  de diversas maneras: Hawkeye y la mayoría de la unidad se ocupan de asegurar elementos que pueden volar; Radar prepara su conejera animal para lo peor; Charles disgustado cambia su transporte de salida de Tokio de aire a tierra, y se encuentra con una situación médica difícil en el camino a Seúl.', 25, '1978-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 8, 'Episodio 8', NULL, 25, '1978-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 9, 'Bebe esta frio afuera', 'Mientras todos se quejan de la ola de frío récord, Charles se convierte en el hombre más impopular en el campamento, cuando sus padres le envían un traje polar invernal que insiste en alardear frente a todos.', 25, '1978-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 10, 'Punto de vista', 'En este episodio único, la cámara se convierte en los ojos de un joven soldado herido. Registra sus respuestas sensoriales a ser herido, llevado en helicóptero a la 4077a, examinado, operado y tratado en la operación posterior.', 25, '1978-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 11, 'Querido camarada', 'Hawkeye y B.J. descubren que Charles está viviendo la vida de Riley, gracias a las atenciones de su sirviente coreano, Comrade Park, un hombre de habilidades inusuales. Tiene una contribución importante que hacer: un remedio nativo para un problema médico aparentemente insoluble.', 25, '1978-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 12, 'Sin gasolina', 'Están llegando muchas bajas, creando graves problemas para la unidad M * A * S * H ​​porque están casi fuera de Pentothal. Mulcahy toma una colección de todos, incluida una caja de vino del suministro privado de Charles, y él y Charles toman el jeep para hacer un intercambio con los vendedores negros por Pentothal.', 25, '1978-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 13, 'Un ojo por diente', 'El padre Mulcahy toma la promoción filosófica hasta que se entera del rápido avance realizado por un heroico piloto de helicóptero. Luego, sus acciones inusualmente audaces aturden al Coronel Potter y a toda la compañía.', 25, '1978-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 14, 'Querida hermana', 'El padre Mulcahy escribe una carta prenavideña a su hermana, que es una monja. Él relata sus frustraciones por no ser más efectivo en el 4077.', 25, '1978-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 15, 'B.J. Papa San', 'B.J. casi se convierte en el padre sustituto de una familia coreana. Al encontrarlos como sustitutos de su propia familia ausente, B.J. pasa tanto tiempo con ellos que su eficiencia médica comienza a sufrir, y Hawkeye se preocupa por su salud. B.J .: "Primero me quitan de mi esposa y mi hijo, y justo cuando encuentro algo para ayudar a llenar el vacío, también se lo quitan".', 25, '1979-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 16, 'inga', 'Hawkeye es una atracción instantánea cuando un hermoso médico sueco, llamado Inga, llega para observar una cirugía de combate. Es decir, hasta que ella lo eclipsa en la sala de operaciones con una técnica superior, y su ego está magullado.', 25, '1979-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 17, 'El precio', 'La 4077 se enfrenta a dos crisis: la yegua del coronel Potter, Sophie, desaparece misteriosamente de su corral, y Hawkeye y BJ se encuentran con un joven coreano en sus manos, que está tratando de evitar el servicio militar obligatorio.', 25, '1979-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 18, 'Episodio 18', 'Una conferencia sobre las últimas técnicas realizada por un joven cirujano de Tokio, y una demostración posterior de su habilidad quirúrgica, convierte a Winchester en un borracho y a Potter en un inválido, mientras le informa a Hawkeye y BJ que están fuera de contacto con las nuevas prácticas médicas. .', 25, '1979-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 19, 'Hot Lips está de vuelta en la ciudad', 'Radar, quien está enamorada de la nueva y linda enfermera, Linda Nugent, confía en la experiencia de Hawkeye sobre cómo hacer frente a la situación. Hot Lips, mientras tanto, celebra su divorcio recién otorgado dando un paso que despierta la ira del coronel Potter.', 25, '1979-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 20, 'CUEVA', 'La evacuación número 4077 a una cueva cercana para evitar el fuego de artillería estadounidense contra un objetivo chino plantea problemas para Hawkeye, que tiene un problema de claustrofobia del que el coronel Potter no es consciente. Por otro lado, Margaret odia los ruidos fuertes. Y luego está el problema de un soldado herido de gravedad ...', 25, '1979-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 21, 'Rally ''alrededor de la bandera, muchachos', 'El siniestro coronel Flagg aparece de nuevo en el 4077, jugando sus juegos espías habituales, convencido de que Hawkeye es un simpatizante comunista, después de que salva la vida de un soldado norcoreano. Además, un soldado estadounidense está menos que impresionado.', 25, '1979-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 22, 'Episodio 22', NULL, 25, '1979-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 23, 'Una noche en casa de Rosie', 'Un día típico en la vida del bar de Rosie, completo con bebedores con problemas de AWOL, un Winchester atado y amordazado y un esquema de juego.', 25, '1979-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 7), 24, 'No es amor grandioso', 'Lo imposible le sucede al Charles snob cuando comparte una experiencia emocional con Klinger, quien descubre que una enfermera estadounidense, Debbie, lo encuentra atractivo a él y a su atuendo extraño, mientras Charles sucumbe a los encantos exóticos de una niña coreana, llamada Sooni, a quien conoce en el bar de Rosie.', 25, '1979-03-05');
