INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0068098')) AND numero_temporada = 11), 12, 'No digas más', 'Un estratega militar se niega a aceptar la responsabilidad de los juegos de guerra que han herido mortalmente a su propio hijo. Y Margaret desarrolla laringitis, cuando está a punto de conocer a su héroe, el Dr. Chesler.', 25, '1983-01-24');
