INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 6, 'Episodio 6', NULL, 49, '1991-02-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 1, 'Temporada 1', 'Enviados a prisión por un tribunal militar por un delito que no cometieron, estos cuatro soldados escaparon de una prisión de máxima seguridad y ahora sobreviven en el mundo clandestino de Los Ángeles como soldados de fortuna. Así que, si tienes un problema y no hay nadie más que pueda ayudarte, y si crees que puedes encontrarlos, quizá puedas contratar al Equipo A.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 1, 'Pueblo de San Rio Blanco', 'Un periodista llamado Al Masi fue al pueblo de san río blanco para hacer un reportaje. Un bandido llamado Malavida Valdes que está aterrorizando a los pueblos de las montañas ha capturado al periodista.', 95, '1983-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 2, 'Los Hijos de Jamestown', 'El equipo A rescata a una chica de una secta y luego se enfrenta al líder de la secta para salvar al los demás chicos y recuperar las botas de Hannibal.', 48, '1983-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 3, 'Presos y convictos', 'El Equipo acude a una prisión de Florida donde el sádico alcaide obliga a los presos a luchar en combates clandestinos.', 49, '1983-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 4, 'Una guerra pequeña y mortal', 'Un inspector de policía recurre al Equipo A para que le ayude a acabar con las actividades clandestinas de un equipo SWAT corrupto.', 49, '1983-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 5, 'Día negro en Bad Rock', 'Como M.A. está gravemente herido, Hannibal decide parar en un pueblo remoto para recibir ayuda médica. Como consecuencia, Hannibal y Fénix son detenidos por el Sheriff.', 49, '1983-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 6, 'El conejito que se comió Las Vegas', 'El Equipo A se dirige a Las Vegas para rescatar a un profesor universitario que ha perfeccionado un sistema de juego infalible.', 49, '1983-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 7, 'Los forasteros', 'El Equipo A acepta ayudar a un maltratado barrio neoyorquino a deshacerse de la extorsión de un brutal mafioso.', 49, '1983-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 8, 'Vacaciones en las colinas', 'Después de que el Equipo A complete una misión, se estrellan de camino a casa y tienen que enfrentarse a unos pueblerinos.', 49, '1983-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 9, 'Operación Costa Oeste', 'El Equipo A es contratado para ayudar a un agricultor de sandías a llevar su cosecha al mercado.', 49, '1983-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 10, 'Una vez más', 'El Equipo A es capturado por el gobierno federal y se le ofrece una misión a cambio de su puesta en libertad.', 49, '1983-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 11, 'Hasta que la muerte nos separe', 'El Equipo A es contratado para ayudar a salvar a una heredera de un empresario corrupto que pretende casarse con ella por su fortuna.', 49, '1983-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 12, 'Pasajeros insólitos', 'El Equipo A es contratado cuando unos terroristas secuestran un avión y exigen 5 millones de dólares.', 49, '1983-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 13, 'Un sitio agradable de visitar', 'La familia Watkins intenta echar al Equipo A de la ciudad cuando acuden al funeral de un amigo del Vietnam.', 47, '1983-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 2, 'Temporada 2', 'Súbete a la famosa furgoneta negra para vivir otra temporada de aventuras llenas de adrenalina con Hannibal, Fénix, Murdock y M.A. mientras luchan por la justicia contra peligrosos criminales y van un paso por delante de su acérrimo perseguidor, el coronel Decker.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 1, 'Diamantes en la arena', 'El Equipo A se dirige a Sudáfrica para defender una mina de diamantes tras el asesinato de su propietario.', 48, '1983-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 2, 'Receta para un pan relleno', 'El Equipo A ayuda a un compañero huido de la guerra que trabaja como pastelero y está amenazado por un traficante de drogas.', 48, '1983-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 3, 'La unica iglesia de la ciudad', 'Fénix recibe una críptica carta de su novia de la universidad y le pide que vaya a Ecuador a ayudarla.', 49, '1983-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 4, 'Marejada en la frontera', 'El Equipo A se dirige a México para encontrar a la madre de una niña y poner fin a una operación de esclavización de inmigrantes ilegales.', 49, '1983-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 5, 'Cuando Volverás, Llanero Solitario parte 1', 'El Equipo A tiene que ayudar a un indio americano que esta en peligro de perder sus caballos por culpa de un traficante de caballos que luego los lleva al matadero para que los sacrifiquen.', 90, '1983-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 6, 'La guerra de los taxis', 'El Equipo A es contratado para ayudar a una pequeña empresa de taxis a acabar con una empresa rival decidida a llevarla a la ruina.', 49, '1983-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 7, 'Con el sudor de tu frente', 'Mientras eluden al coronel Decker, el Equipo A ayuda a los trabajadores agrícolas de un pequeño pueblo que son maltratados por su jefe.', 46, '1983-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 8, 'Siempre se pesca algo', 'El Equipo A actúa para ayudar a una empresa pesquera familiar víctima de una extorsión.', 47, '1983-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 9, 'Agua por todas partes', 'Cuando unos veteranos de Vietnam son amenazados por un rico terrateniente para que renuncien a su propiedad, el Equipo A les ayuda a contraatacar.', 48, '1983-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 10, 'Acero', 'Cuando el Equipo A es contratado por un constructor, descubren por qué su competencia intenta detener su proyecto de demolición.', 47, '1983-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 11, 'Joe Morgan para sheriff', 'Fénix se presenta a las elecciones para Sheriff cuando el Equipo A tiene que impedir que un sheriff corrupto asesine a sus competidores.', 47, '1983-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 12, 'La vaca maltesa', 'El Equipo A acude al rescate del propietario de un restaurante y amigo suyo que está en el punto de mira de unos extorsionadores locales que no traman nada bueno.', 47, '1983-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 13, 'A vista de avión', 'Cuando el piloto de un avión de carga tiene problemas con el motor sobre Venezuela, aterriza a salvo sólo para verse encarcelado por las autoridades al descubrirse cocaína a bordo de su avión.', 48, '1984-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 14, 'La batalla de Bel Air', 'Una reportera de investigación que se infiltra en una empresa de seguridad por encargo, descubre que el Equipo A está a punto de ser capturado por el coronel Decker y sus hombres.', 48, '1984-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 15, 'Díselo con balas', 'La cabo Brown contrata al Equipo A para sacar de la armería de la base al hombre que asesinó a su hermano cuando vendía armas.', 47, '1984-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 16, 'Veneno puro', 'En el condado de Arcadia, un tabernero local vende (incluso a adolescentes) una bebida que realmente te puede llegar a pudrir las tripas, y el reverendo Taylor quiere que el Equipo A le ponga fin.', 47, '1984-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 17, 'Ahi fuera hay un desierto', 'El casino de una pequeña ciudad desierta gana dinero extra robando a sus clientes en una solitaria carretera rural.', 48, '1984-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 18, 'Un negocio de desguace', 'El equipo persigue al vendedor de coches corrupto que robó la furgoneta de M.A.', 48, '1984-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 19, 'Más difícil de lo que parecía', 'El Equipo A es contratado por el hombre de negocios rico Warren Teasdale para rescatar a su hija, que ha sido secuestrada por un grupo terrorista, el GLA.', 46, '1984-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 20, 'Maniobras mortales', 'Mientras el equipo aprovecha un periodo de descanso para retirarse a entrenar físicamente al estilo militar, un sindicato de señores del crimen está tan harto de que el equipo A les arruine el negocio.', 48, '1984-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 21, 'Persuasion semiamistosa', 'Kale Sykes y sus hombres intentan intimidar a la pacífica Sociedad de Hombres para que se vaya de Kellysburg porque no están de acuerdo con su forma de vida.', 47, '1984-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 22, 'Recuerdos de un amigo', 'Decker se entera de que el Equipo A está acabando con el ladrón de ganado Russ Clayton. Cuando llega al lugar de los hechos, el equipo ya no está, pero hay sangre en el suelo.', 48, '1984-03-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 3, 'Temporada 3', 'En la temporada más popular de la historia, Hannibal, Fénix, Murdock y M.A. se enfrentan a nuevos criminales con los planes más escandalosos hasta la fecha: desde vertidos de residuos tóxicos hasta caza furtiva y sabotaje de restaurantes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 1, 'Balas y bikinis', 'Dos chicas piden ayuda al Equipo A cuando se sienten acosadas por un hombre que está decidido a comprarles su hotel en la playa, a pesar de que ellas le han dicho en varias ocasiones que no quieren vender. Hanibal se hace pasar por el nuevo dueño del hotel para evitar la venta.', 46, '1984-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 2, 'El recodo del río', 'Tawnia pide ayuda al Equipo A para encontrar a su prometido, un arqueólogo que fue visto por última vez cuando formaba parte de una expedición al Amazonas que fue atacada por un pirata.', 88, '1984-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 3, 'Fuego', 'El Equipo A es contratado por un jefe de bomberos de una pequeña ciudad, que está tratando de luchar contra un violento grupo privado de bomberos que quieren sustituir su departamento. Mientras tanto, la policía militar, bajo la nueva dirección del Coronel Briggs, se cierne sobre el equipo.', 48, '1984-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 4, '¡Árbol va!', 'Un importante sindicato organizado trata de sacar a un pequeño grupo de madereros del negocio a base de extorsiones. El Equipo A intercede para ayudarlos. Mientras Murdock trata de encontrar al Bigfoot.', 48, '1984-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 5, 'Ataque doble', 'El Equipo A es contratado por un contable cuya hija ha sido secuestrada. Además la chica se ha convertido en la diversión de dos bandas rivales.', 47, '1984-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 6, 'Problemas sobre ruedas', 'Hanibal se hace pasar por otra persona para investigar a un empleado de una fábrica de coches que roba neumáticos para venderlos en contrabando.', 48, '1984-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 7, 'La isla', 'Un médico del ejército, que una vez le salvo la vida a M.A., le pide ayuda al Equipo A para acabar con unos mafiosos que se han apoderado de una isla donde él ha establecido su consultorio médico.', 48, '1984-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 8, 'Una gira por Europa', 'El Coronel Lynch establece una operación de vigilancia para capturar al Equipo A. En ella, un grupo de mafiosos se hace pasar por ellos en un espectáculo del viejo oeste para que Murdock, Hanibal y el resto del equipo se presenten en el lugar y así poder atraparlos.', 46, '1984-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 9, 'Los sheriffs de Rivertown', 'El Equipo A viaja a Sudamérica y allí se convierten en los policías de una pequeña población construida para albergar a los trabajadores de una planta de energía que ha experimentado una serie de accidentes mortales un tanto sospechosos.', 48, '1984-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 10, 'Esta noche, “Las Belles”', 'Un cantante de un grupo musical, que fue compañero de colegio con Fénix, contrata al Equipo A para que los protejan de las continuas amenazas que están recibiendo por parte de un grupo de extorsionadores.', 48, '1984-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 11, 'La última moda', 'El Equipo A tiene que rescatar a la última novia de Fenix, pues se encuentra en manos de unos secuestradores.', 48, '1984-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 12, 'Fuera de combate', 'M.A. y Murdock son tomados como rehenes en un atraco a un banco. Después, cuando la policía consigue liberar a los secuestrados, ambos son llevados a prisión porque se creen que forman parte del grupo de los atracadores.', 47, '1984-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 13, 'Un café en Joe', 'El dueño de una importante cadena de restaurantes trata de convencer por todos los medios al propietario de un pequeño negocio para que se lo venda, pero éste no esta dispuesto a perder su trabajo y contrata al Equipo A para que lo ayude.', 46, '1985-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 14, 'Aprieta, pero no ahogues', 'El Equipo A abre su propio restaurante para poder capturar a un prestamista sin escrúpulos que tiene aterrorizados a los dueños de otros locales.', 49, '1985-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 15, 'Campeón', 'M.A. se tiene que hacer pasar por un boxeador profesional para poder detener a un traficante de drogas que trabaja en los ring de boxeo.', 48, '1985-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 16, 'Pieles', 'El Equipo A viaja a Kenia donde tiene que resolver un importante problema con unos cazadores furtivos que se dedican al tráfico de pieles.', 49, '1985-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 17, 'Un casino en un camión', 'Fénix tiene que infiltrarse dentro de una red de apuestas ilegales para limpiar las deudas de juego de un hombre y acabar con esa situación.', 49, '1985-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 18, 'Blancos móviles', 'Un hombre muy poderoso de Oriente Medio contrata al Equipo A para que vigile a su hija ya que esta no se quiere casarse con el hombre que él ha elegido para ella.', 47, '1985-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 19, 'Caballeros de la ruta', 'El Equipo A ayuda a un mecánico que tiene un pequeño negocio a no tener que venderlo ya que un desleal competidor se ha instalado cerca de su taller haciéndole la competencia y robándole los clientes.', 50, '1985-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 20, 'Desperdicios', 'El Equipo A descubre un complot para verter desechos tóxicos cuando un hombre y su hermana ciega les piden protección.', 47, '1985-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 21, 'Recompensa', 'Murdock es raptado por un cazador de recompensas que espera usarle de cebo para capturar al resto del Equipo A. Cuando El Equipo A acude a rescatarlo, Murdock se ha enamorado de una veterinaria que le ha ayudado en su fuga.', 47, '1985-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 22, 'Asalto en Beverly Hills', 'El Equipo A conoce a un falsificador de obras de arte que ha estado remplazando en diversos museos los originales por obras hechas por él.', 49, '1985-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 23, 'Se está cociendo un problema', 'Dos mujeres se ven presionadas por convertir su planta de embotellado de soda en una fabrica de cerveza, y El Equipo A tiene sed de justicia.', 47, '1985-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 3), 24, 'Incidente en Lago Cristal', 'El Equipo A ha planeado marcharse unos días de vacaciones a un lago en Crystal Lake, pero sus planes se vienen abajo cuando el Coronel Decker y sus hombres aparecen para atraparlos.', 47, '1985-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 4, 'Temporada 4', 'Vuelve a formar equipo con M.A., Hannibal, Murdock y Fénix para enfrentarte a secuestradores despiadados, millonarios corruptos, narcotraficantes implacables e incluso a un capo de la mafia.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 1, 'El día del juicio', 'El Equipo A viaja a Italia para rescatar a la hija de un juez de unos mafiosos. El rescate no resulta fácil ya que estos bandidos saben que El Equipo A se encuentra en su territorio y están alerta.', 95, '1985-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 2, '¿Dónde está el monstruo cuando lo buscas?', 'El Equipo A tiene que ayudar a un amigo de Hanibal, que está haciendo una película en México, cuando un grupo de mafiosos intenta arruinar el rodaje.', 49, '1985-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 3, 'Alquiler con opción a muerte', 'Varios hombres musculosos cometen un gran error al intentar sacar por la fuerza a la abuela de M.A. de su apartamento.', 49, '1985-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 4, 'El camino de la esperanza', 'Hanibal se tiene que hacer pasar por un borracho para impedir ser capturado por el ejército militar.', 49, '1985-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 5, 'El corazón del rock and roll', 'El cantante de rock, Rick James, contrata al Equipo A para que ayude a una vieja leyenda del rock que está en la cárcel y cuya vida bajo rejas corre serio peligro.', 48, '1985-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 6, 'Lucha libre', 'Un viejo amigo de M.A., le pide que le ayude para impedir que un mafioso cierre un centro social de ayuda para jóvenes al que pertenece y él no está de acuerdo.', 49, '1985-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 7, 'Sangre, sudor y victoria', 'En una carrera de coches a nivel regional, alguien sabotea uno de los coches. La cosa no habría ido a más si el dueño del coche no fuera el sobrino de Hanibal.', 50, '1985-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 8, 'Cambio de personalidad', 'Fénix abandona El Equipo A después de recibir una carta en la que el gobierno le pide públicamente perdón por la forma en la que se le ha tratado. Poco después, éste se convierte en una celebridad. El resto del Equipo A se propone vigilarle ya que sospecha que el perdón no es completamente verdadero.', 49, '1985-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 9, 'Como buenos vecinos', 'Una popular estrella del rock sufre una amenaza de secuestro así que contrata al Equipo A para ayudarlo. éstos le trasladan a un tranquilo barrio a las afueras de la ciudad, pero la tranquilidad se termina cuando los vecinos se enteran de quien está viviendo allí.', 48, '1985-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 10, 'El doctor no está', 'El psiquiatra de Murdock es secuestrado mientras realiza una terapia. El Equipo A viaja a América del Sur para encontrarlo, acompañados por una mujer que dice ser la hija del médico.', 48, '1985-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 11, 'El tío partenueces', 'Hanibal realiza una audición para el papel de Ruff Bear en el espectáculo "El tío partenueces". Allí descubre que el tío Buckle está en problemas, ya que alguien está usando sus juguetes para el contrabando de heroína.', 48, '1985-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 12, 'La rueda de la fortuna', 'Murdock se presenta al conocido concurso "La rueda de la fortuna" y durante la grabación del concurso es secuestrado para que robe una poderosa arma soviética.', 48, '1986-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 13, 'Viene El Equipo A, viene El Equipo A', 'Unos espías soviéticos contratan al Equipo A ya que un grupo de ladrones profesionales quiere apoderarse de un satélite americano. Si los ladrones consiguieran su objetivo la paz mundial estaría en grave peligro.', 47, '1986-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 14, 'Sólo para socios', 'Fénix quiere entrar a formar parte de un club muy selecto, pero sus oportunidades se ven truncadas cuando El Equipo A se enfrenta con el dueño del club.', 48, '1986-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 15, 'Comboy George', 'Fénix cree que ha contratado al famosísimo cantante de country George, el cowboy para que actúe en su local, pero cuando llega el día de la actuación quien se presenta es el pequeño George', 49, '1986-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 16, 'Esperando a Wayne el loco', 'Unos mercenarios se hacen pasar por ciudadanos indefensos y contratan los servicios del Equipo A para engañarlos y entregarlos al ejercito. Cuando estos se dan cuenta de lo que sucede, es demasiado tarde.', 49, '1986-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 17, 'Misterio en Whispering Pines', 'Una ex novia de M.A. le pide ayuda al Equipo A porque tiene un gran problema. Su ex marido, un viejo rival de M.A. en la Universidad, ha desaparecido y estos tienen que encontrarlo.', 49, '1986-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 18, 'Bajo la superficie', 'Fénix acude a una reunión en su antiguo orfanato y se encuentra allí con una vieja amiga de su hermana. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 19, 'La misión de la paz', 'Un grupo de la tercera edad contrata al Equipo A para proteger su lugar de reunión, un antiguo edificio histórico que además es una atracción turística y que los especuladores de terreno quieren derribar a toda costa.', 49, '1986-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 20, '¿Qué ocurre con Harry?', 'Un viejo amigo de M.A. va a visitarlo, pero la reunión es interrumpida por el grito de ayuda de un adolescente que tiene problemas con su padre alcohólico.', 48, '1986-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 21, 'El equipo y la familia', 'El Equipo A descubre al jefe de una banda organizada especializada en secuestros que se suponía que estaba muerto y sin embargo se dedica a extorsionar a los propietarios de varias gasolineras.', 48, '1986-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 22, 'El ruido del trueno', 'El General Fulbright captura al Equipo A y les ofrece darle pruebas de su inocencia a cambio de que le acompañen a Vietnam y le ayuden a rescatar a un hombre que podría aclarar lo que allí sucedió.', 48, '1986-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 5, 'Temporada 5', 'M.A., Hannibal, Murdock y Fénix se enfrentan a sus mayores desafíos hasta la fecha cuando el misterioso General Stockwell se une a ellos para luchar contra los villanos que incluyen sicarios, secuestradores y monjes mercenarios.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 1, 'El Hombre de los Efectos', 'Hannibal es secuestrado y llevado ante el misterioso general retirado Hunt Stockwell, que le propone una misión para liberar a los pasajeros de un avión que ha sido secuestrado.', 49, '1986-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 2, 'Juicio a Muerte', 'Traicionados por Josh Curtis, el Equipo A ha sido finalmente capturado y juzgado por el asesinato de su oficial al mando en Vietnam, el coronel Samuel Morrison.', 48, '1986-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 3, 'Línia de Fuego', 'El Equipo A ha sido condenado por homicidio y se enfrentará a un pelotón de fusilamiento en 24 horas.', 49, '1986-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 4, 'El Quarterback Vendido', 'Un científico de Alemania Oriental está perfeccionando una poderosa arma química y está dispuesto a desertar.', 49, '1986-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 5, 'La teoría de la revolución', 'Los miembros del Equipo A están viviendo la buena vida con un grupo de chicas en bikini en su resort privado en Langley, Virginia, cuando el General Stockwell llega con su ayudante Carla y el Scout Murdock.', 47, '1986-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 6, 'Operación Ruidosa', 'Stockwell es localizado por Ivan Trigorin, alias "Zorro Marrón", su antiguo compañero en la CIA durante casi diez años.', 48, '1986-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 7, 'Asesinato en el auditorio', 'Fénix planea dejar El Equipo A para llevar una vida normal pero se ve envuelto en el rescate de una mujer que estaba secuestrada por el jefe de una banda de mafiosos.', 48, '1986-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 8, 'Reunión familiar', 'La hija de un político está saliendo con Fénix. Como el padre de la chica no se fía mucho del novio de su hija quiere conocerle. Poco después Murdock descubre que el hombre podría ser el padre de Fenix y la hija la hermana de su amigo.', 49, '1986-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 9, 'El punto sin retorno', 'El General Stockwell no permite que el resto del Equipo A intente averiguar el paradero de Hanibal, después de que éste se haya ocupado de una misión de alto riesgo en un país muy peligroso.', 48, '1986-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 10, 'La calavera de cristal', 'El Equipo A debe hacer todo lo posible para mantener a buen recaudo una valiosa pieza religiosa que pertenece a una tribu indígena de una pequeña isla. Además, los habitantes del lugar confunden a Murdock con un extraño Dios.', 48, '1986-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 11, 'La espía que se burló de mí', 'Murdock se hace pasar por el agente secreto Logan Ross, para capturar a un peligroso asesino a sueldo antes de que este complete su siguiente encargo.', 49, '1986-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 12, 'El equipo de la tercera edad', 'El Equipo A tiene que encontrar a una niña que ha robado una importante maletín. La chica pensaba que el maletín contenía un material secreto que su padre está vendiendo a los soviéticos.', 48, '1986-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 13, 'La emboscada', 'Frankie y Fénix van a visitar a Murdock a su puesto de trabajo en un restaurante. Durante la comida, los tres se convierten en rehenes de un hombre que quiere matar a su jefe. Hanibal y M.A. tienen que salvarlos.', 48, '1987-03-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')), 1, 'Temporada 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 1, 'Bulma y Son Goku', 'Son Goku, un niño huérfano pero fuerte que vive solo en el Monte Paoz, y Bulma, una adolescente de 16 años, se conocen cuando ella lo atropella con su coche. Bulma está buscando, las Bolas de Dragón, 7 bolas mágicas que, al juntarse, convocan a Shenron, el Dios Dragón que otorga cualquier deseo. Antes de morir, el abuelo de Goku le regaló a éste la bola de cuatro estrellas, llamada Sūshinchū. Bulma, que ya tiene dos bolas mágicas, le pide a Goku que le ayude a buscar las demás, para lo que utilizará un radar, fabricado por ella misma.', 25, '1986-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 2, 'La primera parte del viaje', 'Ya es de noche. Con las Cápsulas Hoipoi de Bulma (unas pequeñas cápsulas enumeradas que contienen en su interior todo tipo de objetos), Goku y Bulma establecen un refugio en donde descansar. Mientras, Mai le cuenta al emperador Pilaf que a cien kilómetros al norte de su castillo, en el Valle del Dragón, se ve un resplandor que emana de la noche. Pilaf, que también está buscando las Bolas de Dragón, y planea usarlas para gobernar el mundo, envía a sus siervos Mai y Shū para ver si se trata de una esfera. Goku va a buscar algo de comida, y ve el avión volando de Mai y Shū. Pensando que se trata de un pájaro, va corriendo detrás de él, y los alcanza después de que Mai y Shū bajen del avión. Los resplandores rojos son los ojos de unos lobos salvajes, y Goku, viéndolos apetitosos, lucha contra ellos mientras salva involuntariamente a Mai y Shū. Al día siguiente, Goku y Bulma se encuentran con Umigame, una tortuga marina que está buscando el mar, así que deciden interrumpir su búsqueda para ayudar a la tortuga.', 25, '1986-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 3, 'Las nubes de Tortuga Duende', 'Cuando llegan al mar, Umigame les pide a Goku y a Bulma que la esperen. Mientras, Pilaf recibe una llamada telefónica de alguien y le cuenta que en una pequeña isla, a 250 kilómetros al sureste de su castillo, un anciano conocido como Ermitaño Tortuga, tiene una Esfera del Dragón. Cuando llegan a la casa del anciano, Pilaf trata de abrir la puerta con una llave. Shū y Mai, que entraron por la ventana, le dijeron a Pilaf que había cerrado la puerta porque ya estaba abierta. Umigame regresa con un anciano en su espalda, el Ermitaño Tortuga. Como recompensa por haber salvado a la tortuga, le regala a Gokū una nube llamada Nube Kintō. El anciano no puede subirse a la nube, porque sólo la gente buena y de corazón puro puede. Bulma tampoco puede subirse, pero Goku sí, porque tiene un buen corazón. El Ermitaño Tortuga le regala a Bulma la esfera de tres estrellas, la Sanshinchū, sin saber qué importancia tiene. Cuando el anciano llega a su isla, se entera de que Pilaf y sus siervos estuvieron revolviendo su casa buscando la Esfera del Dragón. Después de que cuenta que la regaló, los tres abandonan la isla', 25, '1986-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 4, 'Oolong. el secuestrador', 'El Radar del Dragón lleva a Goku y a Bulma a Villa Aru, y se enteran de que la villa está siendo aterrorizada por un monstruo que puede cambiar su apariencia llamado Oolong. Una anciana de la villa tiene la Ryūshinchū (Bola del Dragón de seis estrellas), y acepta dársela a los chicos si ellos hacen que Oolong se marche de la villa. El monstruo quiere casarse con una chica de la villa, así que Goku se disfraza de ella para engañar a Oolong. Cuando el monstruo descubre el engaño, se enoja mucho, se convierte en un toro y huye de la villa. Porque puede transformarse las veces que quiera, pero sólo en un período de cinco minutos, y luego tiene que esperar un minuto más para volver a transformarse. Goku lo sigue y finalmente lo atrapa y lo derrota. Todos descubren que la verdadera forma de Oolong es un cerdo indefenso. Con la villa salvada, la anciana les regala la Ryūshinchū.', 25, '1986-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 5, 'El terrible y solitario Yamcha', 'Bulma obliga a Oolong a que se una a ellos, pensando que su habilidad de transformarse les será útil. El barco de Bulma se queda sin combustible, así que cruzan el desierto. Se dice que un bandido peligroso llamado Yamcha vive en este desierto, acompañado de su gato Puar, quien también puede transformarse. Mientras Goku, Bulma y Oolong caminan por el desierto, Yamcha y Puar les tienden una emboscada. Luego, Goku y Yamcha empiezan a pelear. Yamcha cree que ganó después de usar su técnica Rōgafūfūken, pero Goku puede levantarse. Yamcha está a punto de atacar de nuevo, pero ve a Bulma. Como se pone nervioso con las chicas, entra en pánico y huye con Puar.', 25, '1986-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 6, '¡Vigilad las Bolas de Dragón!', 'Oolong recuerda que tiene una casa rodante en una Cápsula Hoipoi, así que los tres pasan la noche ahí. Mientras, Mai y Shū localizan la casa rodante, y tratan de poner una bomba de tiempo debajo de ella, pero Shū se pega el lado adhesivo de la bomba en su mano accidentalmente, y huye con Mai. Goku le cuenta a Oolong sobre las Bolas de Dragón. Oolong pone somníferos en las bebidas de Goku y Bulma, haciendo que se queden dormidos, para poder manosear a Bulma mientras duerme sin que Goku se dé cuenta. Yamcha y Puar, que estuvieron afuera escuchando la conversación de Goku y Oolong, planean ahora robar las bolas. Puar se transforma en Goku para sacar a Oolong (quien se transformó en Bulma, pensando que Puar es Goku) afuera de la casa rodante, mientras Yamcha sube al piso de arriba donde Bulma duerme. Pero lo que él creía que eran las Bolas de Dragón eran los pechos de Bulma. Oolong y Puar descubren la verdadera identidad de cada uno. Luego, Yamcha huye junto con Puar. Al día siguiente, Shū y Mai terminan de restablecer la bomba y la ponen debajo de la casa rodante. Con el fin de obtener las Bolas de  Dragón, Yamcha le dispara a la casa rodante con una bazuca, y vuelve a pelear contra Goku, quien le saca un diente. Yamcha se retira con Puar, y planea esperar a que Goku y los demás junten las siete bolas para robarlas. Shū y Mai están junto a la casa rodante destruida y dañada y, creyendo que la bomba ya explotó, entran para buscar las Bolas de Dragón. La bomba explota con ellos dentro.', 25, '1986-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 7, 'Ox-Satán en el Monte Frypan', 'Goku, Bulma y Oolong, seguidos por Yamcha y Puar, llegan al monte Frypan a por la siguiente Bola del Dragón, donde vive Ox-Satán. Ox-Satán encuentra a Goku, Bulma y Oolong, cuando esta a punto de matarlos por tratar de robarle su tesoro reconoce la Nube Kinto que el Maestro Roshi le regalo a Goku y le pidió al niño que fuera a buscar a su hija Chichi, y la acompañara a pedirle prestado el abanico Bashō Sen al anciano.', 25, '1986-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 8, 'La ola Kame Hame de Tortuga Duende', 'Dado que hace años que perdió el Bashō Sen, el Maestro Roshi decide acompañar a Goku y Chichi a apagar el fuego de la montaña personalmente. Ahí usa el Kame Hame Ha, logrando apagar el fuego, a costa de destruir la montaña y el castillo. Por suerte, la Bola del Dragón no sufre daños y Bulma la encuentra con ayuda del radar. Mientras tanto, Goku intenta copiar la técnica del anciano maestro y lo logra al primer intento, arruinando el coche que les había regalado Yamcha. Ox-Satán les presta un nuevo coche y los héroes prosiguen su camino.', 25, '1986-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 9, 'El truco especial del Jefe Conejo', 'Goku y compañía llegan a un pueblo a reabastecerse. Ahí son atacados para la banda del Jefe Conejo, un ser extraño que convierte a la gente en zanahorias con sólo tocarlas. Tras convertir a Bulma en una zanahoria, Goku y Yamcha pelean contra él, y la pelea termina con Bulma de vuelta a la normalidad y la banda del Jefe Conejo en la Luna. ', 25, '1986-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 10, '¡Han robado las Bolas de Dragón!', 'Estando cerca de llegar a donde se encuentra la última Bola de Dragón son atacados por Shū, quien les roba el maletín donde estaban las Bolas del Dragón, dejando atrás la que estaba en posesión de Goku. Gracias al radar Goku, Oolong, Bulma, Yamcha y Puar llegan al castillo de Pilaf, donde donde caen en una trampa y son encerrados.', 25, '1986-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 11, 'Invocando al dragón', 'Gracias a un gas somnífero, Mai logra robar la bola de dragón de Goku, aunque por error deja la puerta abierta y los héroes logran escapar del cuarto. Tras terribles obstáculos del castillo, son atrapados de nuevo. Pilaf se prepara para invocar al dios de las Bolas de Dragón Shenlong, mientras que Goku intenta escapar usando un Kame Hame Ha. Logra abrir un hueco por el cual salen Puar y Oolong convertidos en murciélago.', 25, '1986-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 12, 'Se le pide un deseo al Dios Dragón', 'Pilaf convoca a Shenlong, pero mientras pide su deseo, Oolong se interpone de un salto y pide unas bragas. Goku y los demás consiguen escapar del cuarto, pero los cinco son capturados de nuevo. Esta nueva sala tiene paredes de acero y un techo de vidrio blindado. Mientras esperan la muerte calcinados por el sol del desierto, Goku mira la luna llena y se transforma en Ōzaru, un gigantesco primate salvaje. ', 25, '1986-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 13, 'La metamorfosis de Goku', 'Goku, transformado en Ozaru, empieza a destruir todo el castillo, mientras Pilaf y sus secuaces tratan de atacarlo, sin conseguir ningún resultado. Yamcha y los demás escapan y tratan de calmar a Goku. Al no lograrlo, Yamcha le pide a Puar que se transforme en tijeras para cortarle la cola, con lo que Goku vuelve a la normalidad. En la mañana, Goku despierta y se despide de sus amigos, que irán a la ciudad, mientras él se va en la nube Kinton a entrenar con el Maestro Roshi.', 25, '1986-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 14, 'A Goku le sale un rival', 'Son Goku llega a Kame House a pedirle a Kame Sen''nin que lo entrene. Le pregunta por Bulma y al darse cuenta que ya se ha marchado, le pone como requisito que le traiga una mujer hermosa. En el primer intento Goky falla, trayendo una mujer enorme; en el segundo intento logra traer a una hermosa mujer, con el único inconveniente de que es una sirena. Cuando Goky estaba a apunto de salir de nuevo, llega un barco a la isla. Es Krilin, quien le pide a Kame Sen''nin convertirle en su alumno. Acepta con la condición de que entre ambos jóvenes le logren traer una mujer hermosa.', 25, '1986-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 15, 'Lunch, una chica misteriosa', 'En su viaje, Goku y Krilin se encuentran a una joven llamada Lunch siendo perseguida por la policía, al verla en peligro Goku la salva. Los chicos la llevan consigo a Kame Sen''nin para que los entrenen. Cuando llegan a Kame House el maestro, el anciano les pide a los tres que se cambien en el uniforme de entrenamiento, el cual es en realidad ropa interior femenina para ver a Lunch, pero cuando iban a empezar a entrenar Lunch estornuda y cambia su personalidad, la cual les dispara a los 3 artistas marciales.', 25, '1986-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 16, 'Entrenamiento para la búsqueda de piedras', 'Kame Sen''nin lleva la Kame House a otra isla mas espaciosa para entrenar. Al llegar a la isla el anciano pone a los niños una prueba de velocidad en 100 m. Al atardecer Kame Sen''nin propone otra prueba: marca una piedra con el kanji tortuga (亀 kame?) y la tira a una espesa jungla. El primero que la encuentre en 30 minutos podrá cenar, si no, ninguno podrá comer. Krilin, al darse cuenta de la complejidad de la prueba, intenta falsificar la piedra, pero Kame Sen''nin descubre la trampa. Más tarde, Goku encuentra la piedra, pero Krilin se la arrebata y la entrega como suya, dándole el derecho a cenar.', 25, '1986-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 17, 'Repartidores de leche', 'Kame Sen''nin despierta a los niños a las 4:30 de la madrugada para el primer día de entrenamiento. Comienzan repartiendo leche a pie, recorriendo kilómetros alrededor de la isla, incluyendo subir montañas, atravesar acantilados, cruzar desiertos y ser perseguidos por dinosaurios; al volver a casa el anciano maestro anuncia que el entrenamiento de madrugada ha terminado y es hora de iniciar con el entrenamiento de la mañana.', 25, '1986-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 18, 'Entrenamiento al estilo de Tortuga Duende', 'Goku y Krilin continúan con el entrenamiento. Por la mañana, aran una granja con las manos. Tras del desayuno y hasta el almuerzo estudian y después de almorzar toman una siesta y siguen con el entrenamiento ayudando en una construcción como albañiles, nadando en un lago lleno de tiburones y evitando una colmena de abejas mientras están atados al árbol. Al final del día, Kame Sen''nin les informa que a partir de día siguiente y durante varios meses entrenaran usando unos caparazones de 20 kilogramos en la espalda.', 25, '1986-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 19, 'Se inicia el Gran Torneo', 'Tras varios meses de entrenamiento, faltando un mes para el Tenkaichi Budōkai, Kame Sen''nin les entrega nuevos caparazones, esta vez de 40 kilogramos cada uno, con los que continúan entrenando hasta que llega el día del torneo. Antes de partir hacia el torneo el anciano les dice que se quiten los caparazones y salten con todas sus fuerzas para ver el resultado de su entrenamiento, logrando una altura increíble. Al llegar al sitio del torneo se encuentran con Yamcha, Bulma, Puar y Oolong, y la mañana siguiente comienzan las preliminares.', 25, '1986-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 20, '¿Podrá ser eliminada la fuerza lograda?', 'Comienzan las preliminares, los 137 participantes son divididos en cuatro grupos, lo dos ganadores de cada grupo podrán participar en la fase final del torneo. Goku participa en la primera pelea del grupo 3 contra un enorme luchador a quien elimina tocándolo en la pierna, debido a la fuerza obtenida por el entrenamiento. Krilin, por su lado, le toca enfrentarse a uno de sus viejos compañeros del templo Orin, al cual vence con una sola patada. Gracias a sus entrenamientos Goku, Krilin y Yamcha no tuvieron problema para clasificarse a la fase final.', 25, '1986-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 21, '¡Peligro Krilin!', 'Los 8 finalistas son llamados al Ring principal al descubierto y se determina el orden de las peleas: Bacterian vs. Krilin, Jackie Chun vs. Yamcha, Ranfan vs. Nam y Goku vs. Giran. Después de que el presentador explique las reglas, comienza la primera pelea. Bacterian tiene la ventaja la mayor parte de la pelea hasta que Goku le recuerda a Krilin que no tiene nariz, por lo que los olores no deberían afectarle, y tras ello el joven vence a Bacterian fácilmente.', 25, '1986-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 22, 'Yamcha contra Jackie Chun', 'Continua el torneo con la segunda pelea: Yamcha contra Jackie Chun. Yamcha comienza atacando, pero todos sus golpes son esquivados por el anciano, quien tras esquivar el Rōgafūfūken lanza a Yamcha fuera del ring con un simple golpe de viento de uno de sus ataques. Justo después, se realiza la tercera pelea, Ranfan contra Nam. Al principio, Nam es fácilmente abatido por los engaños de Ranfan, llevándolo incluso a estar al borde del ring, pero la convicción de Nam le lleva a la victoria.', 25, '1986-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 23, 'Giran, un rival peligroso', 'Comienza el último combate, Goku contra Giran, después de una inesperada lluvia. Tras varios golpes, Goku logra lanzar al monstruo fuera del ring, pero gracias a sus alas, Giran logra regresar. Es entonces cuando utiliza su Guru Guru Gum para atrapar al niño y lanzarlo fuera, pero es salvado por la nube Kinton justo a tiempo. Giran reclama a los jueces por el uso de la nube y deciden dejarlo como un única excepción. En un nuevo intento por sacar a Goku del ring, el monstruo golpea con toda su fuerza, pero el chaval se agarra al brazo de Giran con su cola, que ha crecido de nuevo. Gracias a ella, Goku tiene la suficiente fuerza como para romper el Guru Guru Gum que le atrapa y al ver una demostración de dicha fuerza, Giran se rinde.', 25, '1986-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 24, 'Frenético ataque de Krilin', 'En el intermedio antes de las semifinales Goku y Krilin son entrevistados. Yamcha, entre bastidores, intenta descubrir la verdadera identidad de Jackie Chun. En la primera semifinal, Krilin se enfrenta a Jackie Chun. La pelea llega a ser tan veloz que en un momento detienen la pelea para que ambos luchadores expliquen lo que sucedió. Después, Krilin usa unas bragas para engañar al anciano y lo manda volando de una patada, pero Jackie Chun usa un Kame Hame Ha para impulsarse de vuelta a la plataforma. El anciano decide terminar la pelea y logra colocarse detrás de Krilin para darle un golpe a ambos lados del cuello, dejándolo fuera de combate.', 25, '1986-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 25, 'El temible golpe aéreo de Karate', 'La segunda semifinal, entre Goku y Nam, comienza con el niño imitando el Zanzōken de Jackie Chun, pero logra evadirlo y contraatacar. Tras intercambiar varios golpes, Goku intenta atacar con una técnica recién inventada, pero no sale como esperaba y Nam lo golpea con su temible técnica Tenkū Pekeji Ken (El Golpe Aéreo). Goku logra recuperarse increíblemente, por lo que Nam vuelve a intentar la técnica, pero el niño salta detrás de él y, al volver al suelo, Goku logra tomar la iniciativa y patear a Nam fuera del ring. Al finalizar el combate, Jackie Chun le regala a Nam una Capsula Hoi Poi para que lleve agua a su pueblo y le pide como favor que se disfrace para que sus alumnos y Yamcha dejen de sospechar que Jackie Chun es realmente Kame Sen''nin.', 25, '1986-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 26, 'La gran final', 'Después de un resumen de las peleas del torneo y una pequeña entrevista a los participantes da comienzo la final. Tras un par de golpes, Jackie Chun logra enviar a Goku volando lejos del ring con una patada, pero el niño logra volver usando su cola como una hélice de helicóptero. Al continuar la pelea ambos concursantes utilizan el Kame Hame Ha lo cual resulta en una enorme explosión. Jackie Chun usa un doble Zanzōken para atacar a Goku por la espalda. Cuando el niño se levanta de nuevo imita esta técnica, haciéndolo triple y atacando a Jackie desde el cielo. A continuación, el anciano utiliza el Suiken, a lo cual Goku responde con el Saruken. Jackie Chun se enoja y decide detenerlo usando otra técnica, moviendo misteriosamente las manos.', 25, '1986-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 27, 'El combate más fuerte de Goku', 'La final continua. Jackie Chun utiliza el Yoiko Minmin Ken para hacer dormir a Goku, pero es despertado cuando Bulma grita que es hora de cenar. El combate se reanuda y para acabar Jackie Chun decide usar su técnica más poderosa, el Bankoku Bikkuri Shō, la cual usa su energía para electrocutar al oponente. Cuando Goku esta a punto de rendirse, mira la luna llena y se convierte en Ōzaru, con lo que vence la técnica del anciano y comienza a destruirlo todo. Al ver el peligro en que se encuentra Jackie Chun decide usar un Kame Hame Ha con todo su poder.', 25, '1986-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 28, 'La final', 'Tras el Kame Hame Ha de Jackie Chun todos piensan que Goku a muerto, pero el anciano explica que el ataque no estaba dirigido al niño, sino a la luna, volviendo a la normalidad. Goku consigue ropa la pelea y el combate continua con ambos contendientes ya exhaustos. Se enfrentan con una doble patada voladora y ambos caen. Tras finalizar la cuenta a diez, y dado que debe haber un ganador, el que pueda levantarse y decir «He ganado» con una sonrisa será el vencedor. Goku logra levantarse, pero cae de nuevo antes de terminar la frase, lo que da tiempo a Jackie a convertirse en el campeón del Torneo. Al final del mismo, se encuentran de nuevo con el maestro y los invita a cenar, quien termina gastando casi todo el premio del torneo.', 25, '1986-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 29, 'El lago mágico', 'Goku se despide de sus amigos y parte en buscar la Suu Shinchuu (Bola de dragón de 4 Estrellas) de su abuelo, pero en su camino se encuentra con Nam, al parecer el río esta seco por culpa de un dique, el cual prohíbe que fluya de nuevo, el cual logra destruir (Goku) con un Kame Hame Ha. Luego continua con su camino en busca de las Bolas de Dragón.', 25, '1986-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 30, 'La bola de cuatro estrellas', 'Pilaf y sus secuaces han regresado buscando nuevamente las Bolas de Dragón. También aparece un ejército misterioso comandado por el Coronel Silver que también está detrás de ellas. Mientras Goku se baña un chico le roba todas sus pertenencias, pero logra recuperar todo menos el radar, ya que el chico se lo lleva para venderlo. Pilaf llega al lugar donde el chico vendió el radar y para su sorpresa la Suu Shinchuu que busca Gokū se vende ahí y la compra. Goku pasa por ahí por casualidad y encuentra el radar. Luego se encuentra con Pilaf y lo persigue, pero este escapa en una nave voladora enorme. Silver llega al negocio y compra otra Bola de Dragón de 4 estrellas, pero se da cuenta de que el dependiente vende Bolas falsas y lo asesina de un disparo. Unos pájaros que estaban cerca de ahí tienen la verdadera que detectaba el Radar, pero nadie se percata y salen volando con ella. Más tarde Pilaf también se da cuenta de que su Bola de Dragón es falsa.', 25, '1986-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 31, '¡Viva el novio!', 'Goku alcanza a Pilaf y este le da la Bola de Dragón rota pegada con pegamento, pero se le cae y se quiebra de nuevo cuando la alcanza. Gyūmaō, que ahora vive en una aldea, comienza a preparar la boda de Goku y Chichi porque una adivina le dice que se dirige hacia allí. El Coronel Silver persigue a al pájaro que se llevó la bola, pero estos es comido por un pterodáctilo que posteriormente atrapa Gyūmaō para el festín. El pueblo de Gyūmaō avista la nave de Pilaf y cree que se trata de su futuro yerno, oportunidad que aprovechan para disfrazar a Shū de Goku. Mientras tanto, Chichí que está cogiendo flores, se encuentra por casualidad con el verdadero Goku. Cuando están comiendo, el ejército del lazo rojo ataca el lugar y Pilaf aprovecha para encontrar la Bola de Dragón. Gyūmaō se enfrenta al ejército pero es atrapado y Pilaf logra escapar con la Bola. Goku y Chichi se dan cuenta de que algo malo ocurre en la aldea y corren hacia ella.', 25, '1986-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 32, 'Veinte mil leguas bajo tierra', 'Pilaf escapa en su nave y es perseguido por el ejército misterioso logrando perderlos y esconderse. Goku y Chichi rescatan a Gyūmaō, Goku se despide y le promete a Chichi que algún día volverá. El coronel Silver y Goku encuentran la base de Pilaf sumergida en la arena y empiezan a atacarla, pero el chico cae en una trampa. La nave de Pilaf despega al verse acorralados, pero es atacada por muchos aviones enemigos y la derriban. Goku desparece en la explosión y Pilaf y sus secuaces, al ser vencidos, entregan la Bola de Dragón al Coronel Silver.', 25, '1986-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 33, 'La leyenda del Dragón', 'Goku, quien logró sobrevivir a la explosión con la ayuda de la Kintōun, llega a un bosque siguiendo el radar, en el que salva a unos monos de una pantera, y juega con ellos. El regimiento de Silver también detecta la señal del bosque. Mientras, Muten Rōshi le cuenta a Krilin y Lunch la leyenda de las Bolas de Dragón. Hace mucho tiempo, las siete Bolas de Dragón eran una sola, pero como personas malvadas querían robarla, ésta se separó en siete partes, pero si se reúnen todas, puede convocarse a Shenlong, quien cumplirá un deseo. El regimiento llega a la ubicación de la señal y encuentran a los monos jugando con la Ūshinchū, así que empiezan a incendiar el bosque. Goku derrota a un par de soldados, un mono y su bebé salen corriendo con la Ūshinchū, pero accidentalmente la suelta y cae en un río.', 25, '1986-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 34, 'La derrota del Coronel Silver', 'Mientras que la Ūshinchū es arrastrada por la lluvia a tierra firme, Goku duerme esa noche en el bosque con los monos. Al día siguiente, sigue el Radar del Dragón y encuentra la Ūshinchū entre unos arbustos. Dos soldados de Silver, quienes estaban en ese lugar buscándola, tratan de robársela sin éxito. Antes de que Goku pueda escapar, Silver destruye la Kintōun. Furioso, Goku lo derrota fácilmente. Luego, toma unas Cápsulas Hoipoi de su cabina y encuentra un robot y un avión. El robot pilotea el avión hacia las montañas del norte, siguiendo el Radar del Dragón. Mientras, el cuarter general de la Red Ribbon detecta que la Ūshinchū que Silver debía encontrar se está moviendo a la base del General White, y se comunican con Silver para enterarse que fue derrotado por un chico y que escapó con la Ūshinchū. El Comandante Red se comunica con el general para advertirle. Goku le pide al robot que aterrice, pero los circuitos del robot se congelan por el frío extremo, así que el avión se estrella. Dos soldados de White encuentran el avión de Silver con el robot, y White ordena que busquen el cuerpo de Goku y la Ūshinchū. El cuerpo de Goku, congelado, es arrastrado por una misteriosa joven, mientras los soldados siguen las huellas en la nieve.', 25, '1986-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 35, 'El coronel White', 'Debido a una tormenta de nieve, los dos soldados de White afortunadamente pierden el rastro de Goku. La misteriosa chica, Suno, lleva a Goku a su casa, en la Aldea Jingle. Goku, ya recuperado, explica qué está buscando. Los dos soldados están destruyendo casa por casa, buscando a Goku. Suno y su mamá explican que la Red Ribbon está amenazando a los esclavos a que busquen las Bolas de Dragón para cumplir su objetivo, y si no lo hacen, matarán al jefe de la aldea, quien ha sido capturado en la Muscle Tower, la base de White. Los soldados encuentran la casa de Suno, pero Goku los derrota fácilmente. Goku, con unos abrigos nuevos, promete salvar al jefe, y se marcha. Finalmente llega a la base de White y, después de derrotar a los soldados que cuidan la entrada, se mete en el segundo piso.', 25, '1986-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 36, 'La torre de acero', 'Goku derrota fácilmente a cuatro guardas en el segundo piso y sube al tercero para empezar una pelea contra un enorme androide, el sargento Metallic. El general White y el sargento mayor Ninja Púrpura están sorprendidos por los poderes de Goku, aunque sus ataques no son efectivos. Metallic dispara un misil de su boca, pero Goku afortunadamente lo esquiva, y contraataca con un Kamehameha. El ataque de Goku le hizo volar la cabeza y causarle un gran daño, pero continúa peleando hasta que se le acaban las pilas. Goku sube al cuarto piso.', 25, '1986-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 37, 'Ninja Murasaki entra en acción', 'El cuarto piso está oscuro. Unos bumerangs vuelan en dirección a Goku, pero él los esquiva. La luz se enciende y se encuentra en medio de un bosque. Goku arroja una piedra a un árbol para golpear a Púrpura. El ninja juega al escondite con Goku, en el que se esconde detrás de una bandera, pero Goku logra encontrarlo. Luego, el ninja le pide a Goku que cierre los ojos y cuente hasta 30, pero como no sabe qué sigue después del 18, abre los ojos y descubre que Púrpura estaba por esconderse dentro de una roca falsa. Goku cuenta de nuevo hasta 30, y lo encuentra escondido en un estanque. ahora, corren una carrera para ver quién es más veloz, pero Goku lo supera. Entonces empiezan a pelear, y Goku le rompe su espada con su Nyoibō. El ninja le arroja un bumerang a Goku, y le golpea en la cabeza.', 25, '1986-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 38, 'Cinco Murasakis contra Goku', 'Goku afortunadamente se levanta, y empieza a perseguir a Púrpura, quien usa unos zapatos especiales para cruzar un lago infestado de pirañas. Goku cruza el lago saltando sobre él. Púrpura usa la técnica de la clonación, en la que se separa en cinco clones de sí mismo. Goku empieza a pelear contra los cinco ninjas, que en realidad son quintillizos, y logra vencer uno por uno. Púrpura sube al quinto piso y libera de su celda a un gigante monstruo humanoide, el Androide #8.', 25, '1986-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 39, 'Súper 8, el robot de gran corazón', 'Púrpura le ordena al Androide #8 que acabe con Goku, pero él se rehúsa ya que un fallo de programación le hace odiar la violencia. El ninja saca un control remoto y le dice al robot que hay una bomba puesta en su cuerpo, y que si no obedece, lo detonará. Antes de que pueda tocar el botón, Goku destruye el control, y derrota a Púrpura. Luego, llega a una habitación donde hay un laberinto muy difícil. Con ayuda del Androide #8, Goku sigue el camino correcto. Cinco soldados llegan a la habitación, pero Goku los derrota fácilmente, y llegan al sexto piso. White activa una trampa en el suelo, y Goku y Androide Nº8 caen en ella.', 25, '1986-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 40, 'Buyon, el monstruo invencible', 'Goku y el Androide Nº8 caen en una misteriosa habitación en la que aparece un monstruo enorme llamado Buyon. Los ataques de Goku son inefectivos, incluso el Kamehameha. Goku rompe un agujero en la pared y se mete en la chaqueta del Androide Nº8. El frío entra por el agujero y Buyon se congela. Después de destruir el cuerpo de Buyon con una patada, Goku salta bien alto hacia el piso de White, y hace subir al Androide #8 con su Nyoibō. Goku le dice a White que libere al jefe de la aldea.', 25, '1986-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 41, 'El último día en la torre de control', 'Goku y White comienzan a pelear. El general se ve claramente superado por las artes marciales del joven hasta que aprovecha un descuido y agarra la cola de Goku, lo cual enfada al joven que devuelve el ataque a White con toda su fuerza, pero es detenido de pronto por Hatchan antes de acabar con él. Hatchan convence al joven de dejar en paz al general, cosa que él aprovecha para engañarlos y tomar al alcalde como rehén. El androide intenta convencer al general de dejar libre al alcalde, pero en su lugar White le dispara a Son Goku, lo que enfurece a Hatchan, quien ataca al general con toda su fuerza mandándole muy lejos. Libres, los tres, regresan a la villa.', 25, '1986-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 42, 'El secreto del Doctor Flappe', 'Goku disfruta de una buena comida como agradecimiento de los padres de Suno. Hatchan revela que él ha tenido la Uh Shinchuu (Bola de 5 estrellas) guardada desde hace algún tiempo, ocultándola para que el General White no matará a los habitantes de la villa. El alcalde, viendo la bondad de Hatchan lo invita a vivir con él, pero el androide no acepta por tener una bomba dentro de él. Suno y Goku deciden ayudarle a encontrar un científico que vive cerca de la villa para que saque la bomba. En el camino son atacados sin saberlo por el ninja Murasaki, quien sobrevivió al la destrucción de la torre. El Dr. Frappe decide ayudarles, pero cuando se va a preparar para realizar la operación es sorprendido por Murasaki, quien lo obliga a robar las Bolas de Dragón de Goku (que al final resulta ser solo su almuerzo). El Joven persigue a Murasaki hasta conseguir recuperar su almuerzo, pero congelado, y Hatchan es liberado de la bomba por el Doctor.', 25, '1986-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 43, 'Goku descubre la ciudad', 'Goku parte hacia la capital del Oeste para pedirle a Bulma que arregle el Radar de Dragón. Gracias a un anciano, Goku recupera a Kinton y no tiene que caminar hasta la ciudad. Cuando llega a la ciudad intenta localizar a Bulma pero nadie la conoce. Tras hablar con un taxista, Goku cae en la cuenta de que necesita dinero. Se encuentra con un luchador de artes marciales, apostando que nadie lo puede vencer, pero el joven lo vence fácilmente y consigue 100000 zenis(1000 Dólares). Al final, gracias a la ayuda de un agente de policía, Goku logra encontrar la casa de Bulma: La Capsule Corp.', 25, '1986-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 44, 'El reencuentro con los amigos', 'Goku logra llegar a casa de Bulma, pero esta se encuentra en clases. La joven llega a casa mientras Goku decide que hacer y lo invita a pasar. Ya dentro Bulma le presenta a su padre, el Dr. Brief, y va a arreglar el Radar Dragón. Tras arreglar el radar, la joven decide acompañar a Goku y para ello ha inventado el Micro Band que le permite encogerse. Con ello pretende viajar sobre Goku cuando el joven suba a la nube Kinton. Mientras tanto, el ejército Red Ribbon envía a Husky para robar las dos Bolas de Dragón de Goku. Bulma y Goku hacen una visita por la ciudad y se encuentran con Yamcha, Oolong y Puar, decidiendo ir todos a un parque de atracciones en lo alto de un obelisco.', 25, '1986-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 45, 'Hasky, la gata', 'Goku y sus amigos llegan al parque de atracciones, seguidos justo detrás de ellos por Husky, que falla al atacar al muchacho. La ladrona decide usar un plan más complicado y se hace pasar por una adivina que es atracada por dos matones (sus secuaces) para ser rescatada por Goku y sus amigos. Como agradecimiento, les ofrece ver su futuro para engañarlos y quitarles las Bolas de Dragón, pero el plan falla por culpa de sus secuaces. Goku, Oolong y Puar persiguen a los ladrones dejando a Yamcha al cuidado de las Bolas de Dragón con la supuesta adivina, lo que Husky aprovecha para seducirle. Goku vuelve una vez que ha atrapado a los ladrones y encuentra a Yamcha amordazado, quien le informa que Husky ha robado las Bolas de Cristal y puesto una bomba en el parque. Husky intenta huir pero es alcanzada por Goku con la Nube Kinton, logrando salvar el parque y las Bolas de Dragón. Una vez que vuelven a casa de Bulma, ella y Goku parten en busca de la siguiente Bola de Dragón dejando a los demás.', 25, '1987-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 46, 'Una isla no tan desierta', 'Goku y Bulma se acercan a la Bola de Dragón que busca el General Blue. Esta se encuentra en el fondo del océano, por lo que deciden ir a una isla cercana. El joven deja a Bulma en la isla y va a bucear en busca de la Bola de Dragón, pero no logra llegar al fondo y vuelve. Mientras tanto la joven comienza a explorar la isla y se encuentra con dos soldados del ejército Red Ribbon que la atacan pensando que es Son Goku. Bulma intenta huir en busca de Goku y cuando lo encuentra el joven vence fácilmente a los soldados. Sabiendo que no pueden llegar nadando al fondo del océano y no tienen un submarino, deciden ir en busca de Kame Sen''nin para pedirle ayuda.', 25, '1987-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 47, 'En busca del tesoro del pirata', 'Goku y Bulma llegan a Kame House en busca del anciano maestro Kame Sen''nin, quien decide prestarles un submarino capaz de volar a cambio del Micro Band para encoger de tamaño, pero deben esperar a que Lunch y Krilin vuelvan de hacer compras con el vehículo. Mientras tanto, el ejército ve en el radar la ubicación de la isla del anciano y supone que esa es la base de los aliados de Goku por lo que ordenan a Blue investigar la isla. Mientras que uno de los soldados de Blue va a inspeccionar la zona, Goku, Bulma y Krilin parten en busca de la Bola de Dragón y, si tienen suerte, encontrar Tesoro del Pirata del que les habla el Maestro.', 25, '1987-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 48, 'El general Blue ataca', 'Goku y sus compañeros llegan al punto que indica el radar y se sumergen en el mar, pero son vistos por el General Blue, quien al recibir la orden del Cuartel General de atacar la Kame House envía al Capitán Doc con la mitad de la brigada, mientras que Blue decide ir detrás del joven con la otra mitad. Krilin conduce el submarino hasta el fondo del océano y Goku sale del mismo a investigar, pero no encuentran la Bola de Dragón. Descubren entonces la entrada a una gruta donde podría estar oculta la Bola, momento justo en que son atacados por el submarino del ejército Red Ribbon.', 25, '1987-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 49, 'Una gruta misteriosa', 'Goku y compañía prosiguen su camino a través de la gruta submarina escapando por los pelos del General Blue. La otra parte de la brigada azul ataca la Kame House, pero son vencidos fácilmente por el anciano maestro y Lunch. Goku, Bulma y Krilin acaban llegando a una parte con aire dentro de la gruta, se adentran dentro de la cueva y Goku encuentra un interruptor que enciende un alumbrado eléctrico indicando que alguien ya había estado ahí antes. Más tarde encuentran un esqueleto de un pirata, que les hace llegar a la conclusión de que se encuentran dentro de una base pirata y donde puede estar escondido su tesoro.', 25, '1987-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 50, 'La guarida del pirata', 'Adentrándose en la cueva Goku y sus compañeros, al igual que los oficiales del ejército del General Blue, se encuentran varias trampas, entre ellas un pasillo lleno de botones que hacen disparar lanzas de lado a lado, una fosa con lava y una fosa con anguilas eléctricas. Los soldados del General Blue caen en la trampa de las lanzas acabando con todos ellos. Los Héroes y Blue llegan a salvo por diferentes caminos a un gran puerto subterráneo de los piratas. Sin embargo, éste resulta no estar abandonado y Bulma y los demás son atacados por un Robot-Pirata que hace guardia entre las sombras.', 25, '1987-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 51, 'El robot pirata', 'Goku y Krilín se enfrentan al robot guardián, pero tienen muchas dificultades para acabar con él: Ni el cañón de un barco ni arrollarlo con un camión parecen poder derrotarle, así que todos comienzan a huir. No es hasta que Goku, desde lo alto de un edificio, cuando le destruye la cabeza de un fuerte puñetazo en caída libre. Mientras el muchacho se enfrenta al robot, Bulma y Krilin se adelantan seguidos de cerca por el General Blue. El General cambia una señal que le dejan sus amigos a Goku y ésta envía al joven en la dirección equivocada. Bulma y Krilín llegan a un túnel lleno de agua y continúan su camino buceando, seguidos con perseverancia por Blue.', 25, '1987-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 52, 'El tesoro existe', 'Goku continua por otro camino por el engaño de Blue hasta llegar a una pared, donde cae en una trampa que lo envía con un pulpo gigante que intenta comérselo, pero termina cocinado por un Kame Hame Ha. Por su lado Bulma y Krilin atraviesan un túnel acuático para escapar y llegan al lugar del tesoro pero son atacados por un sistema de seguridad, Krilin logra desactivarlo y encuentran una llave dentro de un cofre y logran usarla para encontrar el tesoro; pero en ese momento aparece Blue, quien los estaba siguiendo. Krilin empieza a pelear con el y Goku los escucha, pero no logra llegar antes de que Krilin sea vencido debido a los poderes del general, y apenas logra salvarle de su muerte.', 25, '1987-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 53, 'La gruta de los mil peligros', 'Blue y Goku se enfrentan, el general está siendo vencido hasta que utiliza su habilidad especial y paraliza al joven. Cuando el techo comienza a desplomarse Blue amenaza a Goku con un arma y hace que Bulma le diga la ubicación de la Bola de Dragón, pero justo cuando iba a deshacerse de Goku es asustado por una rata, y Goku se libera de la parálisis y vence al general. Goku y sus amigos tratan de escapar de la cueva que se está derrumbando, no sin antes encontrar la Bola de Dragón; y aunque el pasillo por donde entraron está cerrado encuentran un mini-submarino pirata.', 25, '1987-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 54, '¡Sálvese quien pueda!', 'Goku llega justo a tiempo donde sus compañeros aguardan en el mini-submarino, pero después de una breve travesía, el vehículo se queda sin combustible. Goku utiliza entonces un Kame Hame Ha para impulsarlos hasta la superficie del océano. Usando la nube Kinton, todos llegan una isla cercana, pero tras ellos resurge Blue que ha logrado escapar sano y salvo. La isla a la que llegan es la base de Blue y ahí se llevan una nave del ejército hasta la isla del maestro Kame Sen''nin. Lunch, en su forma violenta, huye robando un diamante que Bulma había logrado recuperar de los Piratas. Justo después, Blue logra llegar a Kame House y se dispone a robarles las Bolas de Dragón.', 25, '1987-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 55, 'La aldea de los juguetes mecánicos', 'Blue logra paralizar y atrapar a Goku y sus amigos y huye con las tres Bolas de Dragón, dejándoles una bomba que estallará en 5 minutos. Lunch, en su forma inofensiva, vuelve justo a tiempo para salvarlos de la bomba. Goku liberado sale de inmediato persiguiendo al General Blue en la nube Kinton. Tratando de huir de Goku, el avión del General Blue llega a Villa Pingüino y se estrella contra una montaña. El joven por su lado, aterriza en la aldea y conoce a Arale.', 25, '1987-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 56, 'Arale sube en la nube', 'Goku se marcha en la nube voladora a buscar al general, pero es seguido por las tres niñas, con quienes entabla amistad. Blue escapa antes de que Goku llegue al lugar donde cayó el avión y se encuentra con varios de los peculiares habitantes de Villa Pingüino, buscando a Senbei Norimaki para conseguir un avión. Después de un largo rato buscando, a Goku se le ocurre usar el Radar para encontrar al general, pero esta de nuevo estropeado. Arale lo lleva con el Dr. Norimaki para repararlo.', 25, '1987-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 57, 'De nuevo en camino', 'Turbo arregla el Dragon Radar sin que su padre Senbei se de cuenta. Ya con el radar, Goku se da cuenta de hay una Bola de Dragón cerca y comienza a seguir al General Blue sin saberlo. Cuando lo encuentran, Blue toma a Arale como rehén pero su plan falla. Aun así, arrebata el Dragon Radar a Goku gracias a su poder paralizador e intenta asesinarlo hasta que es salvado por Arale, quien envía a Blue volando realmente lejos. Goku recupera las tres Bolas de Dragón pero Blue tenía el radar cuando salió despedido. Turbo crea una copia exacta del Dragon Radar para Goku, quien continua su viaje en busca de la cuarta bola.', 25, '1987-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 58, 'La tierra sagrada', 'Goku continua su viaje en búsqueda de la Dragon Ball de su abuelo dirigiéndose al Oeste. El Coronel Yellow, otro miembro de la Red Ribbon, parece encontrar la Bola que busca, pero el volcán donde se encuentra hace erupción y cae en la tierra sagrada de Karin, hasta ser encontrada por unos aborígenes. Yellow entra a la tierra de Karin con sus secuaces, pero son echados por el Indio Bora, quien custodia ahora la Bola de Dragón. El coronel logra escapar en su avioneta y vuelve para secuestrar a Upa, hijo de Bora. Tras ser amenazado con enviarle a Tao Pai Pai, un temido asesino a sueldo, si no recupera la Bola, Yellow es vencido por Goku, que llega justo a tiempo para salvar al niño indio. Una vez en el suelo, Goku se percata que la Bola de Dragón que encontró Bora fue la que le dejó su abuelo. Mientras tanto, el General Blue y Tao Pai Pai llegan al Cuartel General de la Red Ribbon.', 25, '1987-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 59, 'Tao Pai Pai entra en acción', 'El General Blue llega ante el Comandante Red, mientras está reunido con Tao Pai Pai, y le entrega el Radar Dragón, pero Blue es reprendido por no traer las Bolas de Dragón consigo. Red perdonará la vida de Blue si logra vencer en un combate contra Tao Pai Pai, pero termina aniquilado por el asesino a sueldo, simplemente usando su lengua. Mientras, Goku conversa con Bora y el aborigen le explica que se encuentran en la Tierra Sagrada, a los pies de la Torre de Karin, contándole la Leyenda que la envuelve y la misteriosa Agua Milagrosa que se encuentra en lo alto de la misma. Mientras el joven decide si sube a la torre, llega Tao Pai Pai. Bora se enfrenta a él, pero es asesinado frente a su hija.', 25, '1987-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 60, 'La Torre Sagrada', 'Goku, enfurecido por la muerte de Bora, se lanza al ataque contra Tao Pai Pai, pero el asesino es muy superior al joven. Goku utiliza incluso su Kame Hame Ha, pero lo único que logra es destruir sus ropas. El asesino responde con un rayo Dodonpa que impacta sobre el pecho de Goku, aparentemente, matándolo. Tao se marcha, llevando consigo el bulto de Goku con tres Bolas de Dragón, pero no se da cuenta que una bola más se quedó con el niño, salvándole la vida del ataque. Mientras consigue ropas nuevas, el asesino llama a la base del ejército Red Ribbon y es informado de la falta de una Bola. Tao Pai Pai avisa que regresara a por ella en 3 días, cuando tenga su ropa nueva. Mientras tanto, Goku despierta justo cuando un soldado llega a recoger la Bola de Dragón que falta y lo vence fácilmente. Al ver la tumba de Bora, Goku decide que lo revivirá reuniendo las 7 Bolas de Dragón y, con tal de vencer a Tao Pai Pai, decide tratar de escalar la Torre de Karin.', 25, '1987-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 61, 'El Maestro de maestros', 'Goku llega a una edificación en lo alto de la torre. Buscando el Agua Ultramilagrosa (Chōseisui), encuentra unas ánforas con aguas que le permiten ver a sus amigos y otros desconocidos en el reflejo, simbolizando su Pasado, su Presente y su Futuro. Al rato, el joven se encuentra con Karin, maestro de la torre. El ermitaño le señala que lo que busca esta en la vasija en medio del cuarto, pero el felino evita que Goku alcance la botella advirtiéndole que deberá arrebatársela si quiere beber el preciado líquido, por lo que comienza a intentarlo una y otra vez. Cansado de perseguirlo, el joven le pregunta si alguien ha logrado alguna vez beber el agua anteriormente; el ermitaño le responde que solo su maestro Kame Sen''nin lo hizo y que duró tres años en lograrlo.', 25, '1987-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 62, 'El agua sagrada', 'Goku continua intentando atrapar a Karin. El gato le quita la Bola de Dragón de cuatro estrellas a Goku y la deja caer por la ventana hasta el suelo, por lo que el joven debe bajar y volver a escalar la torre. Tras un par de días persiguiendo a Karin, Goku comienza a imitar su respiración y movimientos hasta que logra leer los movimientos del gato y obtener la botella. Cuando Goku bebe el agua por fin, el gato le explica que no es más que simple agua corriente; que el verdadero secreto para volverse fuerte ha sido su fortaleza ganada al volver a trepar la torre y los intentos de conseguir la tinaja. Goku baja la torre preparado para enfrentarse de nuevo a Tao Pai Pai.', 25, '1987-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 63, 'El regreso de Goku', 'Tao Pai Pai regresa a la tierra sagrada de Karin. Poco después Goku baja desde la torre y salva a Upa, quien estaba a punto de ser asesinada. El mercenario luchador ataca al joven insistentemente, pero Goku demuestra ser superior anticipándose a todos sus movimientos, atrapando incluso el rayo Dodonpa con sus manos. Sintiéndose superado, Tao Pai Pai decide beber el Agua Sagrada Chōseisui y comienza a escalar la torre de Karin.', 25, '1987-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 64, 'La derrota de Tao Pai Pai', 'Mientras Tao Pai Pai escala la torre, Goku despreocupado come y descansa. Tao Pai Pai llega donde Karin y este le entrega el agua engañándole acerca de sus efectos. Antes de que el asesino se marche, Karin le ofrece también una nube Negra para que baje más rápido, pero esta lo deja caer desde media torre. Al llegar abajo, Goku y Tao Pai Pai continúan su pelea. El asesino lo ataca viciosamente y todo indica que vence al joven, pero Goku se levanta sin problemas. Acorralado, Tao Pai Pai engaña a Goku para lanzarle una granada a traición, pero el joven se la devuelve y el asesino desaparece con el estallido. Goku revisa el Radar de Dragón y se da cuenta de que las Bolas de Dragón restantes están en la base del ejército, y decide dirigirse hacia allá.', 25, '1987-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 65, 'Camino del cuartel general', 'El regimiento Violeta, comandado por la Coronel Violeta, encuentra la Chii Shinchuu en un río, pero son atacados por un cocodrilo gigante y los nativos aborígenes Paku Paku. Mientras escapan hacia la base del ejército, la coronel es la única que logra sobrevivir y entrega la Bola de Dragón al General Red. En la Kame House Bulma crea una videocámara voladora con la que logra encontrar a Goku y se dan cuenta que el joven se encuentra en ruta a la base del ejército Red Ribbon. Bulma crea un teléfono y llama a Yamcha y compañía para ir a ayudar a Goku contra el ejército. Mientras tanto, el joven llega a la base del enemigo.', 25, '1987-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 66, 'Ataque al ejército del general Red', 'Mientras se dirigen a la base del ejército del General Red, Yamcha y compañía recogen a Krilin que se encontraba de recados en medio del mar. Por otro lado, Goku se acerca a la base y al ser descubierto es atacado por las defensas. Goku evita los ataques con misiles y logra aterrizar en la base, empezando a abatir a los soldados del ejército uno a uno. El Comandante Red, seguido por su asistente Black, se oculta en lo alto de una torre al ver el ataque del joven. Goku los sigue gracias a la señal del Radar Dragón.', 25, '1987-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 67, 'El final del General Red', 'Goku continua atacando la base del ejército. El Comandante Red ve cómo su ejército le abandona, e incluso la Coronel Violeta asalta la caja fuerte. El comandante deja al sargento asistente Black para que se enfrente al joven, mientras él activa una trampa tratando de matarlos a ambos. Creyéndose vencedor, el comandante aclara que su deseo es incrementar su estatura, discurso escuchado por Black, que sobrevive a la trampa. Black, molesto por haber sido traicionado, asesina a Red y se autoproclama nuevo comandante en Jefe. Tras ello, Goku sale vivo de la trampa también y se enfrenta a Black. Al no ser rival para el niño, el sargento utiliza un robot para enfrentarse a él. Mientras tanto, Yamcha y compañía se encuentran a la Coronel Violeta en el aire y ambos se esquivan por muy poco.', 25, '1987-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 68, 'La última bola mágica', 'Goku continua la pelea contra Black. El oficial dispara un misil que destruiría toda la base, pero el joven logra devolvérselo y Black lo esquiva por poco. Impotente ya ante la fuerza del muchacho, intenta escapar, pero Goku lo alcanza y atraviesa el robot, estallando y acabando con el Sargento. Tras haber vencido al ejército al completo, Goku reúne seis Bolas de Dragón pero para su sorpresa la séptima no aparece en el radar. Yamcha y compañía llegan por fin a la base para ayudar a Goku. Mientras todos discuten cómo abordar el cuartel general, ven a Goku pasar subido en Kinton y lo llaman. El joven les explica que ha acabado él mismo con el ejército al completo, con lo que su ayuda ya no es necesaria. Pide a Bulma que revise el Radar Dragón, pero necesita de instrumental, así que todos se dirigen a Kame House.', 25, '1987-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 69, 'Babá, la adivina', 'Bulma no encuentra nada malo en el radar del dragón, comprobando que funciona correctamente. Ella deduce que algo o alguien se ha tragado la bola y que la pone fuera del campo de detección. El Maestro Mutenroshi sugiere a Goku entonces visitar a la vieja adivina Uranai Baba para encontrar la última Bola de Dragón con su clarividencia. Goku se va con Yamcha, Puar, Krilin y recogiendo también a Upa a su lugar de residencia y, una vez se muestra la adivina, ésta les dice que les costará mucho dinero sus servicios. Ante la falta de dinero, Baba les propone un desafío: Derrotar a 5 de sus guerreros a cambio de su adivinación.', 25, '1987-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 70, 'Los cinco adversarios', 'Krillin es el primero y pelea ante el vampiro boxeador. Krillin es sorprendido por la extraña danza del vampiro y hunde sus colmillos en el cuero cabelludo de Krillin. Krillin pierde mucha sangre y es arrojado al lago, perdiendo. Confiados, Upa y Puar deciden luchar juntos, a lo cual Baba no se opone, empleando una buena estrategia antivampiros y acaban por ganar. Yamcha es el siguiente. Baba dice que su adversario es un enemigo Invisible, lo cual le hace casi invulnerable. Ante los problemas de Yamcha, a Krilin se le ocurre una gran idea.', 25, '1987-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 71, 'La fosa del diablo', 'Goku localiza a Bulma y Roshi que estaban fuera de la Kame House. Yamcha escucha los pasos del hombre invisible, hasta que Baba empieza a hablar y cantar. Goku llega con los dos. Krillin coloca inmediatamente a la chica y al anciano, haciendo que Roshi tenga una fuerte hemorragia nasal que cae sobre el hombre invisible, exponiéndolo a Yamcha. Yamcha realiza un Puño de Lobo, lo que le obliga a Invisible a rendirse, haciendo que el joven gane. Roshi revela que Baba es su hermana. Para la próxima pelea, Baba lleva a todos al interior de su torre, donde comprueba que Goku es un chico fuera de lo normal. Yamcha espera a su siguiente oponente sobre un terrible ring de lucha.', 25, '1987-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 72, 'El combate en La Fosa del Diablo', 'La momia es un oponente mucho más rápido y más fuerte de lo que parece y Yamcha está a punto de caer de la plataforma. La momia realiza un ataque sorpresa sobre Yamcha. Puar intenta ayudar, pero sólo consigue que empeoren las cosas. Goku salva a Yamcha de caer al foso en el último momento y entra al combate para sustituirle.', 25, '1987-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 73, 'El poder mortal del diablo', 'La Momia lucha ahora contra Goku. Tras un intercambio de golpes donde Goku es claramente superior, la Momia decide emplear sus vendajes como técnica de estrangulamiento contra el joven. Después de una intensa pugna, Goku consigue liberarse. Finalmente, el chico derrota a la Momia de un solo puñetazo. El próximo oponente de Goku es un Demonio que posee un movimiento, al parecer, letal.', 25, '1987-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 74, 'El quinto adversario', 'El Rayo del Demonio no hace ningún efecto sobre Goku, al no poseer ningún tipo de maldad. El Demonio se defiende con un Tridente, que hace caer a Goku, pero no es rival para una fuerte patada del muchacho. El último contendiente aparece: Un Hombre misterioso con una máscara de gato y un halo en la cabeza, que ha estado observando de cerca Goku. El Combate se traslada de nuevo al exterior del Palacio. Roshi siente conocer a esta persona. La Lucha da Comienzo.', 25, '1987-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 75, 'Un misterioso adversario', 'Un torrente de golpes y llaves por parte de los dos rivales sorprende a todos. Ninguno de los dos parece ceder en su violento ataque, hasta que el hombre enmascarado lanza un Kamehameha, que Goku logra evitar. Goku hace su propio Kamehameha, lanzando al Enmascarado al suelo. El hombre agarra la cola de Goku en un despiste del muchacho, que le incapacita. El hombre enmascarado es cada vez más familiar para Roshi, y revela que no es otro que el abuelo fallecido de Goku.', 25, '1987-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 76, 'El adversario se quita la máscara', 'El combate continúa; Son Gohan golpea repetidamente contra el suelo a Goku agarrándole del rabo. Mientras tanto, Pilaf está probando su nueva máquina de poder. Finalmente, se descubre que es Pilaf quien tiene la última Bola de Dragón, contenida en un cierre hermético que interfiere señales de radares. Mientras que Gohan sigue castigando a Goku, su cola acaba por desprenderse, con lo que el muchacho ya no tiene puntos débiles. Gohan se rinde ante ello y revela su cara a Goku. Bulma le cuenta al anciano fallecido las aventuras con Goku y sus amigos. Gohan elige permanecer muerto y desaparece después de una despedida. Baba revela la ubicación exacta de la Bola: Un automóvil que se dirige hacia su posición.', 25, '1987-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 77, 'Las tácticas de Pilaf', 'Pilaf se dirige hacia Baba con la esperanza conseguir de una sola vez todas las bolas de dragón, pensando que Goku todavía tiene una debilidad. Goku parte hacia ellos, se detiene y reconoce al trío de enemigos. Pilaf reta a Goku a una batalla, acordando jugar la bola de dragón que posee contra las 6 que tiene Goku. Pilaf, Mai y Shu deciden atacar a Goku con sus respectivos Robots, pero, para horror de Pilaf, encuentran que Goku ya no tiene cola. Pilaf, combina las 3 máquinas en un intento de obtener la victoria, ya que por separado el joven parece inmune a sus ataques. Goku lanza un potente Kamehameha que daña seriamente a la combinación. Finalmente, tras ser vencido, Pilaf entrega a Goku la bola de una estrella y Shu su traje Ninja.', 25, '1987-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 78, 'La vuelta del dragón divino', 'Goku vuela junto con Upa de regreso a su hogar, en las cercanías de la Torre Sagrada de Karin. Goku convoca al Dragón Shenron y Upa solicita que su padre sea resucitado. El Dragón concede el deseo y Bora se levanta de su tumba. Antes de que las Bolas se dispersen por la Tierra, Goku agarra la de cuatro estrellas, ya convertida en piedra. Al volver con sus amigos, Roshi dice que no tiene nada más que enseñar a Goku, así que éste, sin su Nube Kinton, decide entrenarse por su cuenta hasta el próximo Torneo de Artes Marciales, donde todos participarán.', 25, '1987-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 79, 'La calabaza mágica', 'Goku viaja por las montañas cuando ve a una chica a punto de ser devorada por un tigre antropomórfico y la salva. Ella le pide que ayude a su pueblo que está siendo sometida por 2 violentas personas. Al llegar al pueblo, Goku comprueba que ambos hombres están pasando lista a todos los ciudadanos y, que si no responden "presente", desaparecen. Es debido a una calabaza mágica que ambos poseen. Goku los reta y los supera, pero el dúo de criminales absorben a Goku al interior del amuleto, quedando encerrado. Sin embargo, logra liberarse y volver a salir, apoderándose de la Calabaza. Finalmente, Goku libera al pueblo de los malhechores.', 25, '1987-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 80, 'El combate Real', 'Goku hace un viaje para desafiar a Chintaiken, un reputado luchador de Artes Marciales. Chintaiken está ocupado defendiéndose de Rising Dragon y sus dos hombres, cuando este cae enfermo y debe ser defendido por Goku. Chintaiken le pide a Goku que pelee por él contra Rising Dragon en un combate frente al Rey de la Ciudad por lograr el respeto que su escuela de artes marciales merece. Goku pelea contra él, acabando vencedor. Los hermanos Dragón se unen a las enseñanzas de Chintaiken.', 25, '1987-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 81, 'Goku entre los fantasmas', 'Goku llega a la aldea para evitar las trampas que se suceden en el Bosque. En el castillo del rey tienen dudas de que Goku tenga éxito, pero le recluta para hacer frente a Shula después de ver sus habilidades de combate. En ese momento, Los demonios comienzan a aparecer en el pueblo. El rey escolta a Goku hacia la puerta del Mundo Demoníaco, abierta gracias a la espada de Shula. Goku cumple con los guardias Maylay y Gola. Finalmente Shula aparece y Goku logra golpearle, escapando con Misa. Maylay y Gola lo ayudan a salir y saca la espada de Shula, sellando el Portal que unía los dos mundos.', 25, '1987-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 82, 'El jabalí volador', 'Goku encuentra algunas personas huyendo de su pueblo. Dicen que un monstruo llamado InoShikaCho, un cerdo cruce con ciervo, está aterrorizando a su pueblo. Goku va a la aldea y se encuentra a dos hombres, uno con un tercer ojo sobre su frente y el otro con aspecto de pequeño mimo, que han derrotado a Inoshikacho. Los habitantes del pueblo les recompensan por sus servicios. Más tarde, Goku encuentra a esos dos hombres en el bosque con InoShikaCho alrededor de una fogata. Goku se da cuenta de que sólo pretenden fingir matar al monstruo para obtener dinero. Una chica despierta a Goku, diciendo lo encontró inconsciente en el bosque. Goku va tras su búsqueda y se encuentra a Los dos desconocidos haciendo el mismo truco. Goku dice que son amigos de InoShikaCho, pero engañan a los aldeanos para hacerlos creer que Goku es el único que trama algo. Goku recoge InoShikaCho y sale corriendo, pero los aldeanos lo siguen. Finalmente, InoShiakCho es aceptado por los habitantes para tareas del campo y se aclara que Goku solo trataba de ayudar.', 25, '1987-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 83, 'Hacia la Isla de las Papayas', 'Han pasado tres años, y es el día antes del Torneo Mundial de Artes Marciales. Goku salva a Konkichi, un pequeño zorro verde, que es perseguido por tres individuos. Konkichi lleva a Goku al aeropuerto para volar a Isla de la Papaya, sede del torneo. Goku no tiene dinero, por lo que ir a un carnaval de la ciudad para ganarlo a tiempo. Goku consigue obtenerlo en una máquina que mide la fuerza. Baba, la adivina, aparece ante ellos afirmando estar de Vacaciones. De pronto, Konkichi sale corriendo, pero es atrapado por los matones que le perseguían. Ellos le obligan a robar un banco. Konkichi admite a Goku que era un criminal, pero desea cambiar. Baba dice a Goku donde están los tres hombres, les captura y los lleva a la cárcel. Desafortunadamente, pierde su vuelo, por lo que decide ir a nadando hasta la isla de la Papaya.', 25, '1987-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 84, 'Las vísperas del Gran Torneo', 'Krilin, Yamcha, y los demás llegan a la isla de Papaya y esperan a Goku, que está teniendo sus problemas. Aparecen en el torneo el Maestro Grulla (Tsuru Sen''nin) y sus dos mejores alumnos (los mismos que estafaban a los pueblos con el Jabalí Volador y que Goku desenmascaró). Justo cuando el plazo de inscripción está a punto de terminar, Goku aparece. A la mañana siguiente queda Inaugurada la 22º Edición del Tenkaichi Budokai y Goku, Krilin, Yamcha van hacia los tatamis para la primera eliminatoria. El Maestro Roshi desaparece, y Jackie Chun se presenta nuevamente.', 25, '1987-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 85, 'La primera jornada', 'Goku, Krilin, Yamcha y Jackie Chun pasan a octavos de final tras ganar sus primeros combates. Están todos separados, de modo que no se reunirán entre sí hasta la final. En los cuartos, Yamcha, Krillin y el alumno del Maestro Cuervo, conocido como Ten Shin Han, ganan sus peleas. Es el turno de Goku.', 25, '1987-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 86, 'Carrusel de luchadores', 'Goku es mucho más rápido y más fuerte que el Rey Chappa, y le gana sin problemas. Jackie Chun entra entonces en lucha, y aunque es completamente distraído con los pensamientos de una nueva fuerza de Goku, derrota a su oponente con un solo golpe. La ronda preliminar continuará después de un breve receso. Durante la comida, Yamcha y Ten Shin Han están a punto de entrar en una pelea, pero una vez más, Jackie Chun se lo impide. Nam, participante de la anterior edición del Torneo aparece para luchar, esta vez por diversión. En la ronda de selección final, Nam es derrotado violentamente por Ten Shin Han. Goku, Krilin, Yamcha y Jackie Chun son proclamados finalistas, junto con los dos discípulos del Maestro Cuervo.', 25, '1987-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 87, 'Los ocho finalistas', 'Los finalistas se preparan para sacar sus números para elegir el orden de combates. Chaozu usa sus poderes telequinéticos para arreglar las peleas. La primera pelea será Yamcha vs. Ten Shin Han, la segunda es Jackie Chun vs. Lobo Hombre, la tercera es Krilin vs. Chaozu y la cuarta, Goku vs. Pamputt. Después de una comida rápida para Goku, el torneo definitivo empieza. Yamcha y Ten Shin Han comienzan a golpearse velozmente y se sorprenden de la fuerza del otro. Durante una pausa en la acción, Yamcha afirma que usará su nueva técnica.', 25, '1987-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 88, 'Yamcha sufre un traspiés', 'Yamcha utiliza su técnica de Soplo de Lobo, descargando contundentes golpes sobre Ten Shin Han, pero no tienen ningún efecto. Para sorpresa de todos, y al verse acorralado, Yamcha dispara un Kame Hame Ha, pero Ten logra repelerlo de vuelta hacia él. Yamcha pega un salto para evitarlo, sin embargo Ten logra patearlo en el aire hacia el suelo, quedando inconsciente. Pese a todo, el combate no acaba ahí.', 25, '1987-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 89, 'La desgracia del Lobo-Hombre', 'Tras la brutal derrota de Yamcha por parte de Ten Shin Han, comienza el segundo combate. Lobo Hombre ha estado esperando tres años para la oportunidad de luchar contra Jackie Chun. Él está resentido con Jackie por haber destruido la Luna, que le impide cambiar a ser humano. Lobo Hombre trata de golpear a Jackie lo más rápido que puede, pero esquiva todo sin ningún esfuerzo. Lobo Hombre, tras haber sido estampado contra la pared, saca entonces un cuchillo, pero Jackie lo detiene y derrota fácilmente. Tras vencer a Lobo Hombre, llama a Krilin. Hipnotizado, el Lobo Hombre cree que la cabeza de Krilin es la Luna. Lobo Hombre se convierte nuevamente en un humano.', 25, '1987-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 90, 'Una revelación muy peligrosa', 'Krilin y Chaozu disputan el tercer combate. Chaozu muestra a todos su capacidad de volar y comienza a disparar rayos Dodonpa a Krilin, que se ve obligado a moverse y saltar sin parar para evitarlos. Goku identifica el rayo Dodonpa, la misma técnica que fue utilizada por el asesino mercenario Tao Pai Pai. Ten Shin Han se sorprende al saber que Goku fue quien lo derrotó, ya que Pai Pai pertenecía a la Escuela del Maestro Cuervo. Jackie Chun revela a Goku que era el hermano del Maestro Cuervo. Ten le cuenta a su maestro lo sucedido y ordena a Chaozu descargar su furia sobre Krilin para vengarse. Acorralado por Chaozu que flota en el aire, Krilin decide intentar hacer un Kame Hame Ha, aunque él nunca lo ha utilizado antes.', 25, '1987-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 91, 'Una victoria matemática', 'Chaozu dispara su rayo Dodonpa a Krilin, que produce una gran explosión. De repente, Krilin aparece en el aire y utiliza un Kame Hame Ha sobre Chaozu que impacta de lleno. Chaozu, malherido, apenas logra evitar salir del tatami. El pequeño mimo cambia de estrategia y decide utilizar su cabeza, lanzándose en un movimiento de cabezazo giratorio hacia Krilin para empujarlo fuera del ring. Al evitarlo, Chaozu a continuación utiliza sus poderes psicoquinéticos para paralizar y tener a su merced a Krilin, propinándole un severo castigo. En un último aliento, Krilin se da cuenta de que Chaozu necesita sus manos para usar sus poderes, así que le propone un problema de matemáticas. Chaozu empieza a contar con los dedos y Krilin logra ganar gracias a ello. Más tarde, esa noche, alguien se mete a hurtadillas en la habitación de Goku y trata de matarlo. Goku se despierta y el individuo huye, pero Krilin y Goku salen en su busca. Se trataba del Maestro Cuervo, que buscaba venganza por la derrota de Tao Pai Pai, su hermano.', 25, '1987-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 92, 'Justo a tiempo para ganar', 'El representante de Pamputt, estrella de Cine y TV y el próximo rival de Goku en el torneo, ve lo fuerte que es el chico y se da cuenta de que Pamputt no puede vencerlo. Eso supondría la ruina del representante al no poderse firmar contratos nuevos para los medios. Goku sale del recinto a correr un poco y el representante le alcanza en su coche diciéndole que el torneo se ha trasladado a otro estadio. Él se ofrece a llevar a Goku. Mientras, Lunch ve y sigue a Goku y derrota fácilmente a los guardaespaldas del representante. Goku vuelve a toda prisa al tatami verdadero justo a tiempo para su lucha. Pamputt está muy seguro de su victoria, pero Goku esquiva su ataque y le propina tres rápidos golpes a Pamputt dejándolo noqueado.', 25, '1987-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 93, 'Dos rivales de mucho talento', 'La primera semifinal va a comenzar: Jackie Chun y Ten Shin Han inician su combate. Ten ataca primero, y Jackie Chun lo agarra y lo lanza fuera del ring. Ten revela que él también tiene la capacidad de volar, y flota de nuevo hacia el ring. Jackie Chun usa entonces la técnica del espejo-imagen: Crea ocho imágenes de sí mismo y rápidamente giran alrededor de Ten Shin Han, que le cierran y atacan desde todos los lados. Ten utiliza sus tres ojos para saber cuál es el verdadero Jackie, y le da una patada en la cara. Jackie se quita la camisa y se dispone a pelear al 100%. Los dos comienzan a atacarse salvajemente.', 25, '1987-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 94, 'Una decisión inesperada', 'Ten Shin Han y Jackie Chun siguen luchando. Ten da patadas a Jackie, lo que le hace volar hasta situarle justo al borde del tatami. Ten trata de empujarlo hacia fuera, pero Jackie se las arregla para escapar y volver al centro de la arena. Ten Shin Han decide usar su técnica del Puño Solar, que ciega a todos los espectadores presentes, incluyendo a Jackie. Entonces, Ten le propina un duro golpe, casi noqueando a Jackie. El locutor comienza la cuenta atrás, pero antes de que llegue a diez, Jackie se levanta. Jackie a continuación, comienza a hablarle a Ten Shin Han, diciéndole el error de sus caminos malignos en la lucha. Ten le ignora y comienza un furioso ataque. Como Jackie sigue predicando, el Maestro Cuervo de repente se da cuenta de que Jackie Chun es realmente el Maestro Roshi disfrazado. Se comunica telepáticamente con Ten avisándole de ello y es entonces cuando el joven dispara, para sorpresa de todos, un Kame Hame Ha. Jackie Chun logra desviarlo hacia arriba, y tras unas últimas palabras de sabiduría, el combate da por finalizado de una forma totalmente inesperada.', 25, '1987-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 95, 'Goku contra Krilin', 'Tras el abandono voluntario de Jackie y la victoria de Ten Shin Han, Goku y Krilin pueden comenzar la última semifinal. Después de varios minutos de lucha e intercambio de puñetazos y patadas, los dos parecen igualados. Goku salta por los aires y Krilin le sigue. El sol se refleja en la calva de Krilin y ciega a Goku, permitiendo darle una patada hacia el suelo. Mientras tanto, Ten Shin Han se presenta ante el Maestro Roshi para preguntarle por qué abandonó su combate. El Maestro Roshi le dice que no es un asesino, a pesar de que actúa como tal. Él afirma que Ten tiene una conciencia, y esto le convierte en un héroe. El joven trata de ignorar las enseñanzas de Roshi y promete no tener piedad con su rival en la final del torneo.', 25, '1988-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 96, 'Un combate fraternal', 'Goku y Krilin continúan su lucha. Goku corre hacia Krilin y salta en el aire y utiliza un Kame Hame Ha para impulsarse a sí mismo hacia Krilín, que recibe un fuerte golpe que le deja semi-inconsciente. El locutor comienza la cuenta atrás, pero Krillin se levanta. Goku recibe varios golpes poderosos de Krilin, el cual se da cuenta de que sólo tiene una opción para poder ganarle. Krilin decide disparar un Kame Hame Ha hacia Goku, que le advierte que no surtirá efecto, y fácilmente lo bloquea. De repente, Krilin se aprovecha de la explosión para aparecer detrás de Goku y le agarra la cola. Goku se desmaya y el locutor comienza a contar. Antes de que llegue a diez, Goku se levanta y golpea a Krilin, afirmándole que durante los últimos tres años trabajó con la cola hasta conseguir que su único punto débil desapareciera de raíz. Krilin, atónito, trata de propinar a Goku un puñetazo, pero desaparece sin dejar ni rastro. En realidad, él se está moviendo tan rápido que nadie puede verlo. Solo Ten Shin Han, con su visión de tres ojos, se da cuenta de ello. De repente, aparece junto a Krilin sin, aparentemente, llegar a tocarle, y le lanza fuera del tatami.', 25, '1988-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 97, 'Un duelo excepcional', 'Yamcha se escapa del hospital para ver la final del torneo. La pelea final entre Ten Shin Han y Goku comienza: El joven agarra la pierna de Ten con la cola y le logra dar un puñetazo en la cara. Ten se eleva y decide atacar a Goku con un rayo Dodonpa, que lo estampa contra las baldosas del tatami generando un gran socavón. Goku salta de entre los escombros y sigue la pelea. Goku emplea ahora la técnica de la Multiplicación de Imágenes de sí mismo y rodea a Ten Shin Han. Mientras Goku está corriendo alrededor, Ten consigue golpear a la imagen verdadera y lo envía volando al muro del escenario, donde desencadena un ataque continuo y feroz sobre Goku, dejándolo totalmente a su merced.', 25, '1988-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 98, 'Al borde de la derrota', 'Goku sufre el ataque del Volley Ball de Ten Shin Han. Tras el brutal ataque, se logra reponer. El joven afirma que sólo había estado utilizando una fracción de su fuerza para proteger a su oponente, pero ahora va a luchar a plena potencia. Se desencadena una brutal paliza a Ten Shin Han. Ten medita brevemente y sigue peleando, empleando un Puño Solar para tratar de cegar a su oponente, pero gracias a las gafas del Maestro Roshi, el joven consigue noquear a Ten Shin Han. El combate prosigue muy igualado, hasta que Goku comienza a notar una extraña parálisis de su cuerpo que le deja indefenso ante cualquier ataque del hombre de tres ojos.', 25, '1988-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 99, 'Los brazos del diablo', 'Goku, una vez más, se congela en el aire, lo que permite a Ten darle una patada hacia el suelo que le lanza fuera del tatami, pero Goku utiliza un Kame Hame Ha hacia el suelo para evitar que el aterrizaje fuera del ring. Goku sufre una nueva congelación. Al darse cuenta de que está ganando con demasiada facilidad, Ten Shin Han se da cuenta que Chaozu está interviniendo con sus poderes y le obliga a detenerse, ya que quiere vencer a Goku en una pelea justa. El Maestro Tsuru es quien había ordenado a Chaozu a ello, y le dice a Ten que mate a Goku. Al ver el error en las enseñanzas de Tsuru, Ten se niega a matar a Goku. Tsuru vuelve a ordenar a Chaozu usar sus poderes, pero rechaza la orden. Tsuru trata de matarlo, pero el Maestro Roshi lo golpea con un Kame Hame Ha, que lo saca de la zona del torneo. Ahora pueden luchar sin coacciones. Goku ataca a Ten Shin Han con una fuerza increíble. De repente, Ten decide usar una nueva técnica: Le crecen dos brazos extra en su espalda.', 25, '1988-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 100, 'La fuerza absoluta', 'Con cuatro brazos, Ten Shin Han tiene una clara ventaja sobre Goku. Ten agarra los brazos y las piernas de Goku y le da repetidamente cabezazos. Goku no se rinde y utiliza su cola para golpear y liberarse. Entonces, Goku decide emplear su propia técnica de ocho brazos, lo que iguala la tanda de golpes que se propinan uno a otro. Los dos siguen luchando hasta que se dan un fuerte golpe simultáneamente, que hace caer a ambos al suelo noqueados. La cuenta llega a ocho, pero se levantan. Goku hace caer a Ten al suelo y agarra sus piernas, provocándole gran dolor. Los brazos extra de Ten sujetan a Goku por el cuello, pero dichos brazos acaban por desaparecer al perder la concentración. Después de un largo esfuerzo, Ten Shin Han consigue lanzar y estampar al joven contra los muros del escenario. Goku se levanta, por lo que Ten decide utilizar la técnica mortal Ki-Ko-Ho, un ataque devastador ante el cual advierte al joven que lo esquive si quiere conservar la vida. Tras el impresionante ataque, se despeja la humareda y se descubre que el tatami ha desaparecido dejando un enorme agujero rectangular en el suelo. Goku parece haberse volatilizado con el ataque.', 25, '1988-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 101, 'La lucha final', 'Tras momentos de incertidumbre, se descubre que Goku saltó muy alto para esquivar el ataque. Ambos en el aire, Ten va en su busca y le revela que sólo quería expulsar a Goku fuera de los límites. Ahora que ya que no hay suelo y Ten Shin Han puede volar, Goku parece estar perdido. Goku lanza un Kame Hame Ha que lo impulsa y golpea a Ten con la cabeza, dejando sin fuerzas a ambos. Cuando los dos caen a tierra rápidamente, Goku es finalmente golpeado por un coche poco antes de que Ten toque el suelo. El locutor declara a Ten Shin Han ganador. Concluido el torneo, Ten pide disculpas a Yamcha por herir su pierna, y todos deciden ir a una gran cena. Justo antes de comenzar, Goku se da cuenta que dejó la Bola de Dragón de 4 estrellas en el estadio. Krilin va a buscarla. De pronto, Goku siente que algo va mal y decide ir corriendo al estadio también. Al llegar, encuentra a Krilin y el locutor del torneo abatidos en el suelo. Este último afirma que un monstruo les atacó y que robó la Bola de Dragón y una lista con los nombres de los participantes del torneo.', 25, '1988-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 102, 'El regreso de Piccolo', 'Goku y sus amigos encuentran a Krilin asesinado, junto con el cuerpo sin vida del joven descubren una hoja con un símbolo el cual el Maestro Roshi nunca imaginó volver a ver. El árbitro dice que fue obra de un monstruo que entró por la ventana, y luego de una rápida pelea con el joven, lo asesino, recogió la Bola de Dragón y la lista de los peleadores. Al ver el símbolo impreso en el papel dejado al lado del cuerpo, el Maestro Roshi sabe que se trata del enemigo que menos esperaba el gran maestro, es nada más y nada menos que el poderoso Piccolo Daimao. En eso, Roshi les cuenta cómo la Tierra sufrió hace mucho tiempo el ataque de este ser y cómo en su juventud, junto con el maestro Grulla y el mentor de ambos, Mutaito, lo atraparon en un recipiente. Pilaf es quien ha liberado a Piccolo y ahora es su aliado. Goku parte en busca del asesino y así vencerlo y poder vengar la muerte de su mejor amigo, Krilin.', 25, '1988-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 103, 'Tamborino empieza su trabajo', 'Goku alcanza y lucha contra el agresor de Krilin, Tamborino. Al estar débil por el hambre y el cansancio del Torneo de Artes Marciales, pierde la pelea y Tamborino le considera muerto. Roshi y los demás vuelven a casa, ante el retraso de Goku para guarecerse. Tamborino le entrega a Piccolo Daimao la Bola de Dragón y la lista de los luchadores. Éste es enviado a matar a todos los luchadores del Torneo de Artes Marciales uno por uno. Sus primeras víctimas son el Rey Chappa y Pamputt, que caen derrotados fácilmente.', 25, '1988-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 104, 'Un extraño encuentro', 'Mientras Tamborino comienza a matar a los luchadores del torneo por todo el mundo, dejando tras de sí el Símbolo del Demonio, Piccolo crea otro guerrero para recoger las Bolas de Dragón restantes. Goku despierta en mitad del bosque y trata de buscar alimento. Roshi, previendo los problemas que pueden suceder, piensa en trasladar la Kame-House a otra isla para buscar refugio. Goku, mientras, encuentra un gran pez que está siendo asado en una hoguera en mitad del bosque y se lo come. Cuando está terminando, un hombre de la montaña emerge de los matorrales, irritado y reclamando su almuerzo.', 25, '1988-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 105, 'La derrota de Cymbal', 'Goku pelea con el hombre de la montaña. Conocido como Yajirobe, un virtuoso luchador de katana. Roshi encuentra un refugio seguro para sus amigos en una isla nueva y más grande, y decide junto con Tenshinhan y Chaoz encontrar las Bolas de Dragón y detener a Piccolo Daimao. Bulma mete a Krilin en una cápsula de congelación y lo esconde en el cajón de su ropa interior. Mientras pelean, Goku ve que Yajirobe tiene la Bola de Dragón de una estrella. En ese momento aparece Cymbal, el monstruo de Piccolo Daimao, reclamándola. Después de un juego de "piedra, papel o tijeras", Yajirobe gana el derecho a luchar. Finalmente Yajirobe lo vence, rebanándolo por la mitad. En ese momento Piccolo Daimao siente la muerte de Cymbal, ante lo cual se enfurece.', 25, '1988-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 106, 'Un escondite casi perfecto', 'Piccolo Daimao está devastado y herido por la muerte de Cymbal, y ordena a Tamborino vengar su muerte, justo después de que éste acabara con Giran en mitad de un Río. Roshi y los otros encuentran una Bola de Dragón en su radar. Yamcha es el siguiente en la lista de participantes. Tamborino encuentra y ataca a Yamcha, pero antes de que pueda matarlo, Piccolo Daimao le ordena telepáticamente encontrar al asesino de Cymbal. El Maestro Roshi se las arregla para conseguir una de las Bolas de Dragón en un iceberg. Goku cuenta a Yajirobe que tiene la intención de utilizar las Bolas de Dragón para resucitar a Krilin. Mientras Tamborino se dirige hacia Goku y Yajirobe.', 25, '1988-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 107, 'A la memoria de Krilin', 'El maestro Roshi tiene una dura negociación con unos piratas que tienen una de las Bolas de Dragón. Yajirobe se niega a entregar su Bola de Dragón a Goku. Goku no se irá hasta que Yajirobe se la entregue, pero Tambourine los encuentra, aunque tiene dificultades para seguirlos. Tenshinhan se encuentra con un viejo rival en medio de un pueblo fantasma donde se indica que existe una Bola de Dragón. Resulta que el hombre es un oponente al que Tenshinhan atacó salvajemente. Ten intenta pedir muy amablemente la Bola de Dragón pero el hombre se niega. Los soldados entran a la casa pensando que Ten es el asesino de los luchadores de artes marciales, pero el Maestro Roshi les convence de que están equivocados. Para asombro del hombre, Ten se arrodilla y le ruega que le entregue la Bola de Dragón. Por otro lado, Tamborino encuentra finalmente a Yajirobe y Goku, quien está listo para vengar a su amigo.', 25, '1988-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 108, 'Una difícil decisión', 'Se inicia la lucha entre Goku y Tamborino. De inmediato, lo abruma con su velocidad. Roshi y los demás siguen en busca de otra bola en mitad de una escarpada montaña. Harto de los movimientos del joven, Tamborino lanza un haz de energía concentrado, pero Goku logra resistirlo, atemorizado por su poder, Tamborino intenta huir, pero Goku lo alcanza y lo mata con un Kamehameha en el aire. Nuevamente la muerte del Monstruo es detectada por Piccolo Daimao, quien decide matar al asesino de sus "hijos" personalmente. Yajirobe está muy enfadado con Goku por incinerar al Monstruo, que iba a ser su cena. Roshi y Tenshinhan encuentran la Bola de Dragón en una cueva infestada de cuervos. Gracias a Chaoz, consiguen recuperarla. En ese momento, Piccolo Daimao aparece sobre el lugar donde se encuentra Goku.', 25, '1988-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 109, 'Goku contra Piccolo', 'Roshi está a punto de conseguir otra Bola de Dragón. Yajirobe le da a Goku la Bola de Dragón y corre a esconderse. Piccolo Daimao se lanza al vacío para hacer frente a Goku y se dispone a acabar con él.', 25, '1988-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 110, 'La última esperanza', 'Después de algunos golpes Piccolo Daimao deja a Goku gravemente herido y toma su Bola de Dragón. Piccolo Daimao hace su camino para obtener el resto de las Bolas. En su estado, Goku pide a Yajirobe que lo lleve a la Torre Karin. Mientras tanto Chaoz encuentra la quinta Bola de Dragón. Piccolo Daimao se come las dos Bolas de Dragón que tenia en su poder para frustrar el plan de Roshi. Para evitar que Ten entre en combate, Roshi lo paraliza. Piccolo Daimao se lanza al vacío para hacer frente a Roshi.', 25, '1988-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 111, 'El último combate del maestro Mutenroshi', 'Bulma es incapaz de ponerse en contacto con el maestro Roshi. Este, sabiendo muy bien que no es rival para Piccolo Daimao, no tiene ningún deseo de luchar así que soporta el dolor que recibe. Piccolo Daimao no recuerda la su antigua reunión sino hasta que Roshi menciona a Mutaito, y crece el temor al darse cuenta de lo que Roshi está por hacer. Roshi lleva a cabo el Ma-Fuu-Ba. mientras Piccolo Daimao trata de resistir, Ten observa la situación. Por desgracia, Roshi pierde en el último segundo y muere, Piccolo Daimao une las siete Bolas de Dragón e invoca a Sheng-Long.', 25, '1988-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 112, 'En busca de la eterna juventud', 'Chaoz intenta frustrar el deseo de Piccolo Daimao, pero muere en su lugar. Piccolo Daimao convierte su sueño en realidad y rejuvenece. Antes que Shen Long pueda dispersarse, Piccolo Daimao lo mata para que nadie más puede usar las Bolas de Dragón en su contra. Piccolo tiene previsto orientar el Reino de Chow. Allí el Rey Furry es una persona de buen corazón. Ten tiene la intención de usar el Ma-Fuu-Ba contra Piccolo. Pilaf intenta solicitar su recompensa, pero Piccolo Daimao lo echa de la nave. Yajirobe y Goku finalmente llegan a la torre de Karin y son recibidos por Bora y Upa.', 25, '1988-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 113, 'La primera etapa', 'Como Rey, Piccolo prepara su ataque al Castillo. Goku tiene la intención de subir la torre de Karin, pero Yajirobe no quiere ir con él. Yamcha y los demás llegan al lugar en el que Ten les está esperando. Las cosas se ponen feas en el reino, incluso para el rey. Piccolo Daimao mata al comandante y captura al rey. Yajirobe finalmente llega a la cima de la torre.', 25, '1988-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 114, 'En la cima de la torre', 'Piccolo Daimao mata al primer oficial del rey y obliga a éste a anunciarlo como el nuevo amo del mundo. Furry se niega y Piccolo destruye gran parte de la ciudad, mientras tanto Bulma mete a Chaoz y al maestro Roshi en las cápsulas de congelación. Lamentablemente Karin no tiene nada que enseñarle a Goku.', 25, '1988-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 115, 'El laberinto de hielo', 'Karin le dice a Goku que el Agua Ultra sagrada se esconde en un laberinto de hielo en el que muchos han perecido tratando de pasar. Yajirobe no quiere ir, pero accidentalmente entra en el mismo portal en el que entra después de Goku. Goku lucha contra un monstruo de hielo indestructible, despierta la Oscuridad. Yajirobe y Goku escapan deslizándose por un camino sinuoso. La oscuridad tiene algo en el almacén para ellos.', 25, '1988-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 116, 'El maestro Mutenroshi reaparece', 'Yajirobe y Goku van por caminos separados. Goku ve al Maestro Roshi y es llevado a la Kame House en el centro del laberinto en el que todos sus amigos le esperan. Algo no va bien, Goku se da cuenta de que todo esto es una ilusión. Yajirobe cae sobre Goku y ambos caen por un precipicio. Satisfecha, la oscuridad se reúne con Goku y le advierte de la posibilidad de morir, si no es apto para beber el Agua Ultra Sagrada. Goku se arriesga y bebe el agua, que le causa un dolor insoportable. Mientras tanto el Rey Piccolo emite un comunicado, en el que anuncia que los delincuentes tienen libertad para reinar en el mundo.', 25, '1988-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 117, 'Goku se reencarna', 'Goku sobrevive al Agua Ultra Sagrada. Mientras tanto la ola de crímenes se extiende por todo el mundo. Ten logra controlar el Ma-Fuu-Ba y va en busca de Piccolo Daimao. Goku y Yajirobe vuelven a la Torre de Karin. Karin le da a Goku una nueva nube voladora y Goku se dirige hacia donde esta Piccolo Daimao para enfrentarse a él.', 25, '1988-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 118, 'Ten Shin Han toma una decisión', 'El rey Piccolo mantiene el mundo en suspenso mientras elige un sector para aniquilarlo. Piccolo Daimao decide destruir el Sector 29, en el que está la ciudad de Bulma. Toda la ciudad trata de huir, incluidos los padres de Bulma. Ten llega al Castillo justo cuando Piccolo Daimao está a punto de partir. Antes de que Ten pueda iniciar su plan, Piccolo Daimao crea un nuevo guerrero llamado Drum.', 25, '1988-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 119, 'Jugándose la vida', 'Mientras la crisis continúa en la ciudad del oeste, Ten se ve obligado a luchar contra Drum. Goku se detiene en mitad de su viaje para salvar a Ox-Satan y a Chi Chi de los soldados. Mientras tanto Ten se prepara para realizar el Ma-Fuu-Ba, pero Piccolo destruye el contenedor. Goku llega y vence a Drum, matándolo instantáneamente.', 25, '1988-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 120, 'La cólera de Goku', 'Goku comienza su lucha fuera del Castillo. Durante todo este tiempo Ten se ve sorprendido por el nuevo poder de Goku. Piccolo Daimao recibe muchos golpes de Goku, así que aprovecha todo su poder, causando la muerte de Piano en el proceso. Goku recibe un golpe, pero salta y lanza un Kamehameha.', 25, '1988-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 121, 'Un combate difícil', 'Goku sigue haciendo estragos en Piccolo Daimao. La noticia de la lucha de Goku llega a todos lados. Piccolo Daimao daña la pierna derecha de Goku con una explosión de energía, también usa rayos mortales hasta que alcanzan a Goku, destruyendo todo el reino, el rey Furry evade la muerte. Ten es capaz de salvar a Goku de una muerte segura, pero se agota. Goku impide que Piccolo Daimao lance otra onda explosiva, pero es golpeado por Piccolo Daimao, que provoca un enorme cráter. Goku escapa en su nube voladora.', 25, '1988-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 122, 'El final de Piccolo', 'Piccolo Daimao, amenaza a Goku con matar a Ten, si él se mueve. Yamcha y Yajirobe llegan al lugar del combate. Al descubrir que Piccolo Daimao ha matado a Shen Long, Goku se resigna a soportar los dolores de sus heridas. Con Goku inmovilizado, Piccolo Daimao se dispone a acabar con él, pero Goku utiliza todo su poder en su puño derecho para hacer un agujero a través de Piccolo Daimao. Segundos antes de su muerte, Piccolo Daimao utiliza lo que le queda de energía para expulsar un huevo. Yajirobe salva a Goku de caer y ayuda a Ten. Ten decide entrenar más que nunca.', 25, '1988-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 123, 'En busca del bastón mágico', 'Yajirobe lleva a Goku de nuevo a la torre de Karin. El mundo celebra la derrota de Piccolo Daimao. A pesar de que el dragón está muerto, Bulma guarda las piedras de todos modos. Una anciana encuentra el huevo de Piccolo Daimao y lo lleva a su casa donde le pide ayuda a su marido pero de pronto el huevo empieza a eclosionar despertando Piccolo Junior. Karin se sorprende al escuchar que el dragón está muerto, y revela que las personas muertas por Piccolo Daimao y sus hijos, no van ni al cielo ni al infierno. Karin sabe que el creador de las Bolas de Dragón es Kamisama. Goku recupera el báculo sagrado y vuelve a la torre de Karin. Piccolo Junior destruye la casa de la pareja.', 25, '1988-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 124, 'Un templo en las nubes', 'Goku llega al templo sagrado. Una vez allí debe luchar contra Mr. Popo, para ver a Kamisama. Mr. Popo demuestra ser mucho más fuerte de lo que parece. Mientras tanto, la casa del Maestro Roshi se llena de periodistas que buscan a Goku después que se descubre que fue él quien derrotó a Piccolo Daimao.', 25, '1988-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 125, 'Dios aparece', 'Mr. Popo finalmente accede entrenar a Goku después de ver su potencial. Al mismo tiempo, Tenshinhan se entrena para vencer a Goku en el próximo Torneo de Artes Marciales. Al darse cuenta de la determinación de Goku, Kamisama se revela ante él, quien se sorprende por su gran parecido con Piccolo Daimao y la historia que cuenta. Kamisama se compromete a revivir a Shen Long si Goku se queda a entrenar con Mr. Popo durante un tiempo, Goku acepta con gusto.', 25, '1988-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 126, 'La resurrección del dragón', 'Kamisama revive a Shen Long pero a cambio le pide a Goku que se quede a entrenar en el templo hasta el próximo torneo de las artes Marciales. Mientras tanto Bulma, Yamcha y los demás le piden a Shen Long que resucite a las personas que Piccolo mato. Shen-Long, les concede el deseo y Krilin, el maestro Roshi y Chaoz resucitan.', 25, '1988-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 127, 'Más rápido que la luz', 'Goku empieza su entrenamiento con Mr. Popo y pasados unos cuantos ejercicios Goku le dice que él sabe que el entrenamiento de Mr. Popo fue muy duro y que quiere ser entrenado como él, este acepta su petición y él, junto con Kamisama, lo mandan a buscar una corona. Goku la encuentra y al ponérsela caen rayos y el no puede esquivarlos, pasadas unas horas lo vuelve a intentar y logra ser más rápido que un relámpago.', 25, '1988-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 128, 'Sereno como el cielo', 'Goku despierta en el templo y le encomiendan una nueva misión en la que tiene que encontrar a una persona que es muy fuerte y lo transportan a un nuevo sitio donde encuentra una familia que le informa sobre ese hombre. Al otro día el abuelo lo lleva cerca del sitio donde se encuentra aquel hombre, por fin lo encuentra y luchan pero Goku se da cuenta de que él no era la persona que buscaba y se queda confundido de pronto encuentra nuevamente al abuelo y los dos empiezan a pescar, Goku finalmente aprende a estar tranquilo como el cielo.', 25, '1988-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 129, 'Más allá de los límites del tiempo', 'En su entrenamiento, Goku viaja al pasado y se encuentra al maestro Roshi y al maestro Tsuru de jóvenes y estos lo llevan frente a su maestro Mutaito quien le enseña a Goku como controlar su Ki.', 25, '1988-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 130, 'El aprendizaje', 'Goku intenta poner su mente en blanco pero no puede hacerlo y le dice a Mr. Popo que quiere luchar contra él, este le responde que no está preparado para luchar contra él, pero que si tanto quiere luchar vendrá alguien con la misma fuerza que Goku y le arranca un pelo, fabricando un muñeco con el pelo arrancado y el agua de la vida. Por fin llega el contrincante de Goku que tiene una máscara, comienzan a luchar pero Goku no siente el Ki de su oponente y le parece muy raro, entonces le da una patada a su cabeza, lo que hace que salga volando su máscara y descubre que es él mismo. Mr. Popo le explica lo que pasa y continúan luchando hasta que Goku aprende a poner su mente en blanco y sentir la presencia de su oponente, consiguiendo derrotar al muñeco, Mr. Popo le dice que no lo derrotó, si no que, se ha acabado el efecto del agua de la vida y que debe entrenar más. Mientras tanto Tenshinhan, Krilin, Yamcha y Chaoz empiezan su entrenamiento y quieren encontrar la torre Karin para hacerse más fuertes.', 25, '1988-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 131, 'La fiesta de la aldea', 'Tenshinhan, Krilin, Chaoz y Yamcha continúan buscando la torre de Karin y llegan a un lugar en el que están celebrando la protección del dios de la montaña sobre su pueblo. Mientras están en la fiesta, Chaoz siente que la montaña va a hacer erupción y les dice que deben salir de ahí, Tenshinhan decide detener la lava del volcán para poder ser más fuerte que Goku y todos sus amigos lo siguen. Mientras que Goku sigue entrenando con Mr. Popo.', 25, '1988-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 132, 'La cólera del dios de la montaña', 'Yamcha, Tenshinhan, Chaoz y Krilin logran detener la lava del volcán para que no llegue al pueblo usando sus técnicas de artes marciales. Mientras tanto Goku continúa con su entrenamiento y todos se siguen preparando para el próximo torneo de artes marciales.', 25, '1988-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 133, 'El reencuentro', 'Bulma, el maestro Roshi, Lunch, Oolong y Puar se encuentran nuevamente 3 años después de que Goku mató a Piccolo Dai-Ma-Ku. Momentos después de su reencuentro se preocupan de que no ha llegado nadie, de repente aparece Goku con unas vestimentas raras haciendo que todos se sorprendan de lo mucho que ha crecido, pero siguen si llegar sus otros amigos, momentos antes de que se terminen las inscripciones del torneo de las artes marciales llegan Yamcha, Krilin, Chaoz y Tenshinhan alcanzando a inscribirse. Antes de que empiecen las preliminares se encuentran con el hijo de Piccolo.', 25, '1988-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 134, 'Un nuevo campeonato de artes marciales', 'Empiezan las preliminares y Goku pelea de nuevo contra el rey Chapa pero lo derrota con sus nuevas técnicas. Las preliminares continúan y todos los amigos de Goku han ganado pero de pronto, cuando Chaoz está peleando, sucede algo que lo deja gravemente inconsciente, todos van a verlo y descubren que quien cometió esa atrocidad fue Tao Pai Pai, quien ahora es un robot humano, y les dice que se va a vengar de Goku por haberlo dejado así y de Tenshinhan por ser un traidor.', 25, '1988-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 135, 'Los ocho mejores candidatos', 'Las preliminares del torneo de las artes Marciales continúan y en la última batalla Yajirobe pelea por ser uno de los 8 finalistas contra un señor muy tonto que por pura suerte logra derrotarlo haciendo que los 8 finalistas sean Tao Pai Pai, Krilin, Yamcha, Goku, La desconocida, Tenshinhan, Mayunia y Shen. Se realiza un sorteo para ver quien será el contrincante de cada quien y este sorteo queda así: Tao Pai Pai contra Tenshinhan en la primera pelea, Goku contra La desconocida en la segunda, Mayunia contra Krilin en la tercera y Shen contra Yamcha en la última. Entonces la primera pelea inicia.', 25, '1988-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 136, 'El maestro ignorante', 'La primera pelea comienza Tenshinhan pelea contra Tao Pai Pai pero Tenshinhan es más fuerte que Tao Pai Pai y cuando lo va a sacar de la plataforma se le cae la mano con que lo agarraba y de esta saca una espada con la que corta a Tenshinhan pero este se enoja y la rompe con su mano, el árbitro falla a favor de Tenshinhan ya que es ilegal usar armas pero a Tao Pai Pai no le importa y utiliza el super Do-don-pa pero Ten lo rompe con un grito y después golpea a Tao Pai Pai, este se desmaya haciendo que la pelea termine y comience la segunda.', 25, '1988-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 137, 'Goku se casa', 'La segunda pelea comienza y Goku pelea contra la peleadora desconocida, quien está muy enojada con Goku, él le pregunta su nombre y ella se enoja porque él no recuerda nada, le dice que si le logra ganar la pelea le dirá su nombre. Goku la derrota y ella le dice su nombre y le recuerda la promesa que él le hizo, entonces Goku recuerda todo y le pide que sea su esposa a lo cual ella acepta. Después la tercera pelea empieza.', 25, '1988-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 138, 'Shen, un candidato fuera de lo común', 'La tercera pelea continúa pero Krilin finalmente pierde ante Mayunia y este se da cuenta que no le será tan fácil conquistar el mundo. Empieza la cuarta pelea entre Yamcha y Shen, al parecer Shen es muy débil por lo que Yamcha se confía, de pronto Shen lo ataca y Yamcha se da cuenta de que no es oponente común.', 25, '1988-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 139, 'Una derrota sorprendente', 'Se descubre que Shen es en verdad un hombre común y corriente pero que tiene el alma de Kamisama. Yamcha finalmente pierde y empiezan las semifinales; Goku contra Tenshinhan, ellos pelean y se dan cuenta que han mejorado mucho. Pero que, a pesar de todo el más fuerte es Goku.', 25, '1988-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 140, 'Goku y Ten Shin Han se enfrentan de nuevo', 'La pelea continua y Goku pone en ridículo a Tenshinhan pues hace que se le caigan los pantalones, gracias a esto Ten se da cuenta de que Goku es más fuerte de lo que él pensaba y entonces utiliza una técnica para que le salgan doce ojos.', 25, '1989-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 141, 'Todos para uno y uno para todos', 'Tenshinhan se divide en cuatro pero Goku aun sigue siendo más fuerte y siguen luchando, Goku sigue intacto ante los ataques de Tenshinhan, finalmente Goku derrota a Tenshinhan sacando a los 4 Ten fuera de la plataforma.', 25, '1989-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 142, 'Shen contra Junior', 'La segunda pelea de las semifinales comienza con Shen contra Piccolo, Shen intenta detener a Piccolo usando el Ma-fuu-ba pero Piccolo ya sabe como controlar el Ma-fuu-ba y se lo regresa a Kamisama, haciendo que este quede atrapado en lugar de él, Kamisama le dice a Goku que lo derrote aunque tenga que morir Kamisama.', 25, '1989-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 143, 'En lucha por el futuro del mundo', 'Goku les cuenta a Roshi, Krillin, Yamcha y a los demás acerca de como Kami y Piccolo se volvieron dos entidades separadas, el bien y el mal. La pelea comienza, su fuerza parece ser igual. Sin embargo, Piccolo desata una oleada de ataques que deja a Goku acostado en un agujero a medida que aumenta la cuenta.', 25, '1989-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 144, 'El último combate', 'Goku quería probar los ataques de Piccolo. Al reanudar la lucha, Goku parece ser superior a su oponente. Preocupado, Piccolo decide dar rienda suelta a un ataque devastador que acabará con todo el mundo en el torneo. Goku recuerda que, aunque Kami muere en el curso de la explosión Piccolo también morirá, Goku combate la explosión de Piccolo con su más poderoso Kamehameha.', 25, '1989-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 145, 'El gigante del torneo', 'Piccolo revela a todos que él es, de hecho, la reencarnación de rey demonio Piccolo. Al oír esto, todos los espectadores de la arena huyen dejando sólo a Goku y a sus amigos, aunque trabaja en beneficio de Goku, puesto que ya no tiene que preocuparse por hacer daño a otros. Piccolo concentra su energía para convertirse en un gigante de sí mismo. A pesar de que es considerablemente más grande, Goku todavía no tiene ningún problema luchando contra él. Sin embargo, dice que si Piccolo fuese más grande, él estaría en problemas. Por supuesto, Piccolo hace precisamente eso y Goku aprovecha la oportunidad para entrar en la boca de Piccolo y lo golpea desde el interior.', 25, '1989-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 146, 'La lealtad de Goku', 'Piccolo siendo gigante, Goku le dice que no puede crecer más pero este aumenta su tamaño aún más y Goku va hasta su garganta y recupera la botella donde está atrapado Kamisama, le confiesa a Piccolo que lo engaño para que pudiera rescatar a Kamisama. Piccolo le lanza un rayo que sigue a Goku pero este se le regresa a Piccolo dañándole un brazo, Piccolo se lo arranca y le crece uno nuevo y comienza a hacer una técnica muy poderosa.', 25, '1989-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 147, 'Una prueba difícil', 'Pikoro finalmente usa su técnica y destruye todo la isla pero Goku sigue en pie y le lanza un Kame-hame-ha y parece que por fin derrotó a Pikoro pero este se levante y le lanza un rayo de la boca cuando Goku estaba distraído y le atraviesa el pecho, Pikoro cree haber ganado pero Goku se levante de nuevo.', 25, '1989-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 148, 'La victoria final', 'Pelean un poco más pero al final Goku cae y Pikoro le daña sus brazos y sus piernas provocando que Goku no se pueda mover, al ver esto Pikoro hace una nueva técnica para acabar con Goku. Pikoro cree haber ganado pero Goku llega de los aires volando y le da un cabezazo sacándolo de la plataforma haciendo que él gane.', 25, '1989-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 149, 'En busca del abanico mágico', 'Goku y Chichi llegan al castillo de Ox Satan y este les enseña el vestido de novia de la madre de Chichi , pero de pronto salen llamas del suelo y lo único que las puede apagar es el Basho-sen, (una hoja que perdió el maestro Roshi). Van con Uranai Ba Ba y esta los lleva a un lugar donde se enteran de cómo hacer el Basho-sen pero Uranai les dice que el maestro Roshi tiene un libro donde viene esa imagen del Basho-sen.', 25, '1989-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 150, 'El comedor de fuego', 'Goku y Chichi encuentran el libro y tienen que obtener una pluma del ave traga fuego en que vive en un volcán, finalmente la obtiene pero un doctor que estaba ahí les dice que era solo un mito pero les dice el lugar donde pueden encontrar el Basho-sen, Chichi y Gokū se van a esa montaña pero Chichi se lleva un pedazo del huevo del ave traga fuego con ella.', 25, '1989-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 151, 'En la montaña de hielo', 'Al ir en busca del Basho-sen van a una montaña en la que si sube una mujer empieza una tormenta de nieve y todo se congela por lo que Goku sube solo para ir por nieve que en ese lugar es muy fría para poder apagar el fuego en el castillo mientras que Chichi aprende como ser una ama de casa, Goku regresa pero la nieve se derritió, entonces Chichi le dice que encontró el Basho-sen mientras limpiaba y le dan las gracias a la señora que encontraron en la montaña que les da un miel especial de abejas; los dos regresan al castillo y una vez ahí Goku agita el Basho pero este no funciono como para apagar el fuego.', 25, '1989-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 152, 'La montaña de los cinco elementos', 'Uranai Baba le dice a Goku que lo que provoca el fuego es el horno mágico que se encuentra en la montaña de los cinco elementos, pero que esa montaña es muy peligrosa. Por fin Gokū y Chichi descubren el camino correcto encontrando una fisura en el horno que provoca el fuego en la montaña.', 25, '1989-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 153, 'En las llamas del infierno', 'La diosa que cuidaba el horno mágico les dice que para poder arreglarlo necesitan un pedazo de cascarón del huevo del ave traga fuego y miel de abejas del panal octagonal. A lo que Goku y Chichi le dicen que ellos tiene esas cosas, al final Goku repara el horno después de pasar por un gran peligro; pero hace que en la montaña Fry-pan desaparezca el fuego. Finalmente Goku y Chichi se casan y Uranai Baba lee su futuro gratis.', 25, '1989-04-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 1, 'Temporada 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 1, 'El compromiso', 'En este episodio piloto, Sophia llega después de que su casa de retiro se queme y Blanche se prepara para casarse.', 24, '1985-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 2, '¿Adivinas quien viene a la boda?', 'La hija de Dorothy, Kate, llega a Miami con un anuncio. Ella está comprometida con un podólogo llamado Dennis. Dorothy está emocionada, pero su felicidad se convierte rápidamente en ira cuando se da cuenta de que el ex esposo, Stan, será invitado. Después de 38 años de matrimonio, Stan había dejado a Dorothy por una mujer de la mitad de su edad. Dorothy amenaza con hacer una escena en la recepción que coloca a Rose y Blanche en el papel de pacificador.', 24, '1985-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 3, 'Rose la mojigata', 'Al no haber salido desde que murió su marido, Rose acepta a regañadientes ir a una cita a ciegas. Esta fecha se convierte en una relación seria cuando la invitan a un crucero que implica compartir un camarote.', 24, '1985-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 4, 'El trasplante', 'La hermana de Blanche, Virginia, viene a Miami para una visita y Blanche está convencida de que está buscando algo. Más tarde, mientras sale a cenar, se entera de lo que busca Virginia: el riñón de Blanche. Mientras tanto, Rose y Dorothy cuidan niños para un bebé.', 24, '1985-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 5, 'El triángulo', 'Una doctora de citas con Dorothy hace un pase en blanche. Pero cuando Blanche se lo cuenta a Dorothy, Dorothy no le cree. Dorothy la acusa de ser una prostituta y cuando Blanche no puede más, le ordena a Dorothy que se mude.', 24, '1985-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 6, 'Por las chicas de oro', 'El nieto de 14 años de Blanche viene a Miami para una visita y le da un nuevo significado al término "brecha generacional". Mientras tanto, Dorothy estudia para su final francesa.', 24, '1985-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 7, 'La competición', 'En una competencia de bolos, son Dorothy y Blanche los versos de Rose y Sophia. Si Sophia y Rose ganan, Dorothy permitirá que Sophia regrese a Sicilia para visitar a un viejo novio y si Dorothy y Blanche ganan, Sophia le dará un par de pendientes antiguos.', 24, '1985-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 8, 'El robo', 'Después de un concierto de Madonna, las chicas llegan a casa para descubrir que su casa ha sido asaltada. Esto lleva a las niñas a buscar medios para protegerse, incluido un sistema de seguridad, un perro guardián y una maza. Mientras tanto, Rose se vuelve tan paranoica que los ladrones regresarán, ella va tan lejos como para comprar un arma.', 24, '1985-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 9, 'Blanche y el hombre más joven', 'Blanche hace todo lo posible para tratar de verse bien para su último novio, su instructor de aeróbicos de la mitad de su edad. Mientras tanto, la madre dinámica de Rose viene de visita y se cansa de las formas de "maternidad" de Rose.', 24, '1985-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 10, 'El ataque al corazón', 'Después de una cena, Sophia sufre un aparente ataque al corazón con una fuerte tormenta que retrasa a los paramédicos.', 24, '1985-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 11, 'El regreso de Stan', 'El ex esposo de Dorothy, Stan, aparece para arreglar un pedazo de tierra que compraron en su luna de miel. Esto lleva a que Dorothy y Stan pasen la noche juntos. Mientras tanto, Rose y Blanche planean unas vacaciones en las que Sophia no está invitada.', 24, '1985-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 12, 'La batalla por la custodia', 'La hermana de Dorothy, Gloria, viene a Miami para una visita y le pide a Sophia que venga a vivir con ella a California. Mientras tanto, Blanche está furiosa cuando Rose es elegida como Lady Macbeth, en una obra de teatro local, y no como ella.', 24, '1985-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 13, 'Un pequeño idilio', 'Rose ha estado saliendo con el Dr. Jonathan Newman y comienza a pensar que su relación está conduciendo al cambio. Sin embargo, ella comienza a tener dudas, especialmente porque él es un enano.', 24, '1985-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 14, 'No era ninguna dama', 'El último novio de Dorothy, Glen, le da un susto cuando le dice que está casado. Se sorprende a sí misma cuando se encuentra a escondidas para estar con él. Mientras tanto, Blanche descarga su viejo auto en Rose para comprar uno nuevo.', 24, '1985-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 15, 'En un lecho de rosas', 'Una tarde, Rose lleva a un hombre a casa y pasan la noche juntos. Sin embargo, por la mañana ella descubre que él ha fallecido. Peor aún, más tarde descubre que él estaba casado.', 24, '1986-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 16, 'La verdad siempre sale a relucir', 'Rose está preocupada por la visita de su hija y su nieta, ya que su razón para venir es para resolver el testamento del difunto esposo de Rose. Mientras tanto, Blanche se ve atrapada en los tabloides de un asesinato de sociedad.', 24, '1986-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 17, 'Bonito y fácil', 'La sobrina que visita a Blanche es un chip justo al lado del viejo bloque cuando sale con un hombre diferente toda la noche todas las noches. Mientras tanto, Dorothy lucha con un ratón que vive en la casa.', 24, '1986-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 18, 'La operación', 'Dorothy tiene dudas acerca de someterse a una cirugía de pie, ya que estaba programada para bailar con Blanche y Rose en un recital de baile.', 24, '1986-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 19, 'Segunda maternidad', 'Blanche está enamorada de un pretendiente adinerado que ella aprende que tiene varios niños pequeños. Este hecho amortigua su propuesta de matrimonio. Mientras tanto, Dorothy y Rose van a batear con la tubería del baño.', 24, '1986-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 20, 'Educación para adultos', 'La profesora de psicología de Blanche la acosa sexualmente cuando acude a él en busca de ayuda en una prueba difícil. El profesor de Blanche le hace un trato acosador: si tiene relaciones sexuales con él, él le dará una "A" para el examen. Mientras tanto, Dorothy, Rose y Sophia intentan conseguir entradas para un concierto de Frank Sinatra con entradas agotadas.', 24, '1986-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 21, 'La gripe', 'Una semana antes de la ceremonia de entrega de premios, Blanche, Dorothy y Rose se enferman con una gripe desagradable, lo que agrava su discusión sobre quién ganará un prestigioso premio.', 24, '1986-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 22, 'Buscando empleo', 'Cuando Rose pierde su trabajo en el centro de duelo, comienza a buscar otras fuentes de trabajo. Mientras tanto, Blanche intenta perder unos kilos y Dorothy está emocionada cuando un hombre del que una vez estuvo enamorada, la contacta y la invita a salir.', 24, '1986-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 23, 'Ambiciones ciegas', 'La hermana de Rose, Lily, debe lidiar con la vida como una persona ciega después de perder la vista recientemente. Mientras tanto, las chicas tienen una venta de garaje para comprar un televisor nuevo, pero les cuesta separarse de las cosas.', 24, '1986-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 24, 'Papaíto', 'El padre de Blanche, Big Daddy, viene a Miami para una visita, con un anuncio, ha vendido la plantación familiar y se propone convertirse en un cantante de country. Mientras tanto, Sophia coloca una "" maldición "sobre un vecino que se niega a quitar su árbol que cayó sobre el lanai durante una tormenta.', 24, '1986-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 1), 25, 'Tal como nos conocimos', 'Una noche, después de ver "" Psycho "", a las chicas les cuesta dormir, así que permanecen levantadas y recuerdan cómo se las arreglaron todas para vivir juntas.', 24, '1986-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 2, 'Temporada 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 1, 'Una vez al mes', 'Blanche está mortificada después de hacerse una prueba de embarazo que indica que está embarazada. Luego, después de visitar a su médico, ella descubre la verdad, está comenzando la menopausia. Mientras tanto, Dorothy, Rose y Sophia entran en el negocio de la cría de visones.', 24, '1986-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 2, 'Entre busconas', 'La casa está fumigada y las chicas se mudan a un hotel de Miami Beach. Anteriormente, Blanche había ganado tres entradas para ver el estreno de la nueva película de Burt Reynolds y la fiesta que se celebraba después, donde podían reunirse con él. Sin embargo, en la noche de la inauguración, el hotel es asaltadoy, confundidas con prostitutas, Dorothy, Blanche y Rose son llevadas a la cárcel.', 24, '1986-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 3, 'Stanley ataca de nuevo', 'Dorothy deja a un deprimido Stan con Blanche, pero luego se pone increíblemente celosa cuando Blanche y Stan se ponen en marcha. Mientras tanto, Sophia y Rose comienzan a vender sándwiches en el paseo marítimo, pero inadvertidamente se convierten en enemigas de otro vendedor, " Johnny No Thumbs ".', 24, '1986-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 4, 'Que triste es la vida', 'Las chicas hacen circular una petición para salvar un roble de 200 años que se encuentra en la propiedad de la mujer más odiada del vecindario, Frieda Claxton, que quiere que se corte el árbol.', 24, '1986-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 5, '¿Verdad que es romántico?', 'Una vieja amiga de Dorothy, Jean, viene a Miami para una visita y Dorothy decide no decirle a Blanche y Rose que Jean es lesbiana. Luego, después de pasar tiempo con Rose, Jean comienza a enamorarse de ella. Mientras tanto, una nueva videograbadora le pide a Sophia que alquile " películas sucias ".', 24, '1986-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 6, 'La mujercita de papaíto', 'El padre de Blanche viene a Miami para una visita y anuncia que está comprometido para casarse. Blanche está emocionada hasta que conoce a su novia, que resulta ser más joven que ella. Mientras tanto, Dorothy y Rose entran en un concurso de escritura de canciones.', 24, '1986-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 7, 'Un asunto de familia', 'El hijo de Dorothy, Michael, y la hija de Rose, Bridget, vienen a Miami para una visita y cada uno de ellos se vuelve un poco demasiado amigable para el gusto de Dorothy y Rose. Mientras tanto, Blanche le duele la espalda en la clase de aeróbic.', 24, '1986-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 8, 'Vacaciones', 'Las vacaciones de ensueño de las chicas en el Caribe están lejos de lo que se anunciaba en el folleto. Mientras las chicas están lejos, Sofía tiene un romance con el jardinero.', 24, '1986-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 9, 'Rivalidad entre amigas', 'Despedida de su trabajo, Dorothy busca un trabajo de medio tiempo que lleva a Blanche a conseguirle un trabajo en el museo. Luego, la cosa se complica cuando le entrega a Dorothy la tarea de organizar un banquete, el trabajo que Blanche estaba deseando. Mientras tanto, Rose encuentra un perro callejero en el supermercado.', 24, '1986-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 10, 'Con cariño, Rose', 'Rose coloca un anuncio en la columna de personal y se decepciona cuando no obtiene una respuesta inmediata. Esto lleva a Blanche y Dorothy a comenzar a responder bajo el nombre de Isaac Newton.', 24, '1986-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 11, 'Una pesadilla antes de Navidad', 'Cada una de las chicas planea pasar la Navidad con sus familias, pero una serie de acontecimientos extraños las llevan a pasar la Navidad juntas en Miami.', 24, '1986-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 12, 'Hermanas', 'Para el cumpleaños de Sophia, Dorothy para sorprenderla trae a su hermana Angela desde Sicilia. Sin embargo, Dorothy es la que se sorprende cuando la reacción de Sophia es la de disgusto.', 24, '1987-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 13, 'El Stan que vino a cenar', 'Dorothy siente simpatía por Stan cuando le dice que tiene que someterse a una cirugía a corazón abierto. Sin embargo, esa simpatía se desvanece cuando se entera de sus muchas infidelidades mientras estaban casados.', 24, '1987-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 14, 'El actor', 'Dorothy, Blanche y Rose compiten por atraer la atención de un actor en el teatro de la comunidad local, quien a escondidas comienza a tener romances con cada una de ellas.', 24, '1987-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 15, 'Antes y después', 'Rose está convencida de que murió durante un espasmo en la garganta. Esto la lleva a vivir su vida al máximo, interrumpiendo totalmente las vidas de las otras chicas. Luego, cuando las chicas se quejan de su nuevo estilo de vida, Rose se muda.', 24, '1987-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 16, 'Y entonces hubo uno', 'Sophia se prepara para participar en una caminata. Mientras tanto, Dorothy, Blanche y Rose cuidan a los niños participantes de la caminata, pero cuando el evento termina, un bebé queda sin reclamar.', 24, '1987-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 17, 'Historias para dormir', 'Cuando las chicas se enteran de que unos parientes las van a visitar, recuerdan las veces que tuvieron que compartir una cama y los lugares extraños en los que tuvieron que dormir, incluida una estación de tren.', 24, '1987-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 18, 'Perdóneme padre', 'Blanche y Rose planifican una buena cena en casa para Dorothy y su nuevo novio, quien más tarde se entera de que es un sacerdote. Ella más tarde recibe otro shock cuando se entera de que él planea dejar la iglesia.', 24, '1987-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 19, 'Largo viaje a Marinara', 'La hermana de Sophia, Angela, llega a Miami para una visita y decide quedarse a vivir, pero mientras busca un apartamento, Dorothy la invita a quedarse con las chicas. Esto afecta a Sophia ya que ella piensa que Angela está buscando quedarse con todo lo que tiene.', 24, '1987-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 20, 'La cirugía estética', 'Blanche está convencida de que su belleza se está desvaneciendo después de asistir a su reunión en la escuela secundaria y descubrir que muchas de sus compañeras de clase se han hecho estiramientos faciales. Mientras tanto, Rose está haciendo una película casera para la clase a la que está asistiendo.', 24, '1987-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 21, 'El discípulo premiado de Dorothy', 'Dorothy siente culpable cuando su querida alumna gana un concurso de escritura que, sin darse cuenta, le indica al INS que es una extranjera ilegal.', 24, '1987-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 22, 'Un diamante en bruto', 'Mientras Dorothy y Rose planean un banquete de caridad en el hospital, Blanche se enamora de Jake, el proveedor contratado para el evento. Rápidamente se entera de que él es más informal que comprometido, lo que la impulsa a poner fin a su romance.', 24, '1987-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 23, 'Queridísimo yerno', 'La hija de Dorothy, Kate, viene de visita y tiene una gran noticia. Dorothy está emocionada cuando piensa que la noticia será que Kate está embarazada. Sin embargo, cuando Kate llega, la noticia está lejos de ser emocionante. Mientras tanto, Blanche y Rose permanecen arriba y miran una maratón de "I Love Lucy".', 24, '1987-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 24, 'Atrapar a un vecino', 'Dos detectives de la policía vigilan el hogar de las chicas para investigar a los vecinos que se cree que son traficantes de gemas robadas.', 24, '1987-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 25, 'Un pedazo de tarta', 'Mientras se preparan para la fiesta de cumpleaños de una amiga, las chicas recuerdan cumpleaños pasados, incluida la fiesta sorpresa de cumpleaños de Rose para Dorothy, una fiesta sorpresa de cumpleaños para Blanche y un recuerdo del cumpleaños de Sophia con su difunto esposo Sal.', 24, '1987-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 2), 26, 'Nido vacío', 'En esta prueba piloto para otra serie (Nido vacío, obviamente el concepto fue modificado), la amiga de las chicas, Renee, se siente deprimida y solitaria con sus hijos mayores y los hábitos de adicto al trabajo de su esposo.', 24, '1987-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 3, 'Temporada 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 1, 'Viejos amigos', 'Sophia se hace amiga de un anciano en el paseo marítimo con el que se hace rápidamente amiga. Sin embargo, su comportamiento extraño indica que tiene un problema médico, la enfermedad de Alzheimer. Mientras tanto, Blanche regala accidentalmente el oso de peluche de Rose en una venta de garaje.', 24, '1987-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 2, 'Una de dinero', 'El último método para hacerse rica rápidamente de Sophia hace que las chicas recuerden otros planes para hacerse rico rápidamente que han tenido a lo largo de los años, incluido el catering, un maratón de baile y un recuerdo de Sophia de 1954.', 24, '1987-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 3, 'Educando a Bebé', 'Rose se sorprende al saber que en el fallecimiento de su tío fallecido, él le dejó su " Bebé ". Sin embargo, rápidamente se deleita en saber que el " bebé " es un cerdo, pero encantada no es una palabra para describir a Dorothy, Blanche y Sophia, al menos no hasta que descubren que cuando Bebé muere, Rose recibe una gran cantidad de dinero.', 24, '1987-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 4, 'La asistenta', 'La búsqueda de las chicas de un ama de llaves termina cuando contratan a Marguerite, una mujer que parece tener poderes místicos. Sin embargo, cuando la despiden, una serie de eventos extraños convencen a las chicas de que Marguerite les ha puesto una maldición.', 24, '1987-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 5, 'No Hay Que Tener Miedo Mas Que Del Miedo Mismo', 'Cuando Rose debe dar un elogio en el funeral de su tía, Rose debe tratar de superar su mayor temor en el mundo, dando discursos. Esto también trae a colación los mayores temores de Dorothy y Blanche, Dorothy de volar y Blanche de un sueño recurrente.', 24, '1987-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 6, 'Carta a Gorbachov', 'Rose se preocupa por la guerra nuclear cuando las chicas en su tropa de cadetes dibujan un futuro sombrío. Esto la impulsa a escribir cartas a Gorbachov y Reagan. Se asombra cuando recibe una respuesta y se entera de que a Gorbechov le gustaría conocerla.', 24, '1987-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 7, 'Extraños compañeros de cama', 'Las chicas intentan ayudar en una campaña para que Gil Kessler sea elegido como funcionario local. Para su ventaja, sus posibilidades de ganar aumentan cuando los reporteros toman fotos de Blanche entrando a su casa una noche mientras su esposa estaba fuera.', 24, '1987-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 8, 'Amor Fraternal', 'Blanche hace un movimiento hacia Ted, el hermano de Stan cuando se entera de que es un neurocirujano. Está furiosa cuando descubre que la única mujer en la que aparentemente está interesado Ted es Dorothy. Mientras tanto, Rose está sufriendo de insomnio.', 24, '1987-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 9, 'La visita del pequeño Sven', 'El primo de Rose, Sven, llega a Miami para visitarla justo antes de casarse por acuerdo. Sin embargo, cuando Blanche juega un truco con su último novio, que involucra a Sven, el ingenuo novio se enamora de ella. Mientras tanto, Sophia intenta renovar su licencia de conducir.', 24, '1987-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 10, 'La Auditoria', 'Dorothy se sorprende al saber que los problemas fiscales de Stan son sus problemas fiscales, ya que Stan está siendo auditado durante varios años cuando aún estaban casados. Mientras tanto, Blanche y Rose toman una clase de español, cada una por razones diferentes.', 24, '1987-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 11, 'Tres en un Sofá', 'Las disputas constantes hacen que las chicas busquen la ayuda de un terapeuta. Esto lleva a las chicas a recordar las ocasiones en que no se llevaban bien. La conclusión del terapeuta, no deben convivir.', 24, '1987-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 12, 'El viejo camarada de Charlie', 'Un amigo de la guerra del difunto esposo de Rose llega a Miami para ver a Rose, sin embargo, tiene más en cuenta que solo es una visita amistosa. Mientras tanto, Dorothy y Blanche regatean sobre el mismo vestido para usar en un evento social.', 24, '1987-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 13, 'El Artista', 'Dorothy, Blanche y Rose posan secretamente desnudas para un escultor húngaro que dará a conocer la estatua en una exhibición de arte que se inaugurará en un museo. Mientras tanto, Sophia repasa chistes prácticos para recuperar a un bromista en el Senior Citizens Center.', 24, '1987-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 14, 'La nenita de Blanche', 'Blanche está emocionada por la visita de su hija, Rebecca, una ex modelo que ahora ha ganado bastante peso. También visitando a Rebecca está su novio que constantemente baja su peso. El pateador: está pensando en casarse con él.', 24, '1988-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 15, 'La nueva amiga de Dorothy', 'Dorothy se hace amiga de una novelista, Barbara Thorndyke, y rápidamente infringe la relación de Dorothy con Blanche y Rose, quienes creen que Barbara no es más que una esnob.', 24, '1988-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 16, 'Trinca la Pasta', 'Sophia les dio a las chicas la oportunidad de aparecer en el exitoso programa de juegos Grab that Dough en California. En el hotel, pierden sus reservas y deben dormir en el vestíbulo ... como resultado, todas sus pertenencias personales son robadas. Sophia aún tiene los boletos, pero una vez que llegan al juego, las chicas pelean y se dividen en dos equipos que compiten por separado.', 24, '1988-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 17, 'Mi Hermano, mi Padre', 'El hermano de Sophia, Angelo, un sacerdote, vendrá a Miami para una visita y no sabe que Dorothy y Stan están divorciados. Así que para evitar sus sentimientos, Sophia convence a Dorothy y Stan de fingir que están casados. Mientras tanto, Rose y Blanche se preparan para protagonizar una obra de teatro, The Sound of Music.', 24, '1988-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 18, 'Momentos Dorados (Parte 1)', 'Sophia anuncia sus intenciones de mudarse y salir con su hijo Phil. Esto hace que las chicas recuerden los buenos tiempos y los malos momentos que han pasado juntos.', 24, '1988-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 19, 'Momentos Dorados (Parte 2)', 'Cuando Sophia decide si mudarse o no con su hijo, las chicas siguen recordando los años que compartieron juntos.', 24, '1988-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 20, 'Y con mamá somos tres', 'Sintiéndose apenada por una Sophia solitaria, Dorothy le permite ir a una cita con ella y con el último novio de Dorothy. Sin embargo, muy pronto, Sophia comienza a marcar a lo largo de cada cita lo que rompe los planes románticos de Dorothy.', 24, '1988-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 21, 'Hurto y Encaje Antiguo', 'El último novio de Sophia, Rocco dice haber estado involucrado en la mafia, así que cuando las chicas descubren una bolsa de Rocco con miles de dólares en ella, asumen que robó un banco. Mientras tanto, Dorothy y Blanche alcanzan un pico en el diario de Rose.', 24, '1988-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 22, 'La Gran Aventura De Rose', 'El último novio de Rose se acaba de jubilar y está lista para pasar mucho más tiempo con él, pero su retiro lo convierte rápidamente en un teleadicto. Mientras tanto, las chicas se ocupan de remodelar el garaje en una habitación de invitados.', 24, '1988-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 23, 'Bendición Contradictoria', 'El hijo de Dorothy, Michael hace otra visita a Miami y esta vez tiene una noticia, está comprometido. Sin embargo, Dorothy tiene otras dos sorpresas en la tienda, su futura nuera también es negra y veinte años mayor que Michael.', 24, '1988-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 24, 'Mister Tremendo', 'Rose comienza a salir con el "Sr. Estupendo", el presentador de un programa infantil, que es despedido cuando Dorothy obtiene un trabajo a tiempo parcial como consultora en el programa, un trabajo que él la ayudó a conseguir.', 24, '1988-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 3), 25, 'El Día De La Madre', 'Mientras esperan las llamadas telefónicas de sus hijos para desearles un feliz día de la madre, las chicas recuerdan los pasados días de la madre.', 24, '1988-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 4, 'Temporada 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 1, 'Si, no tenemos habanos', 'El último novio de Blanche es un encantador cubano que se deshace de ella, pero no es la única cuando Blanche descubre que ha estado saliendo con Sophia a sus espaldas. Mientras tanto, Rose toma un curso impartido por Dorothy para obtener un diploma de escuela secundaria.', 24, '1988-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 2, 'Los días y las noches de Sophia Petrillo', 'Este episodio hace un estudio en contraste, el día ajetreado de Sophia con el día perezoso de Blanche, Dorothy y Rose. Mientras Sophia organiza una banda para recaudar fondos, los voluntarios en el hospital y las políticas de devolución en el supermercado, Blanche, Dorothy y Rose se sientan a discutir qué deben hacer, eso es constructivo.', 24, '1988-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 3, 'El que se escapó', 'Blanche está decidida a dormir con el único hombre que la rechazó una vez en el pasado. Mientras tanto, Rose afirma haber visto un OVNI e involucra a la Fuerza Aérea.', 24, '1988-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 4, 'Héroes de pega', 'Rose se postula para la Mujer del Año de St. Olaf y con un poco de ayuda de Blanche y Dorothy, modificando su lista de calificaciones en el formulario de inscripción, es una ganadora segura. Mientras tanto, una ola de calor golpea a Miami y el aire acondicionado de las chicas se apaga.', 24, '1988-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 5, 'Golpea el tambor, Stanley', 'En un juego de béisbol, Sophia es golpeada, lo que incita a Stan a convencerla de que presente una demanda por el pago de sus heridas severas, haciendo que ella lo falsifique. Mientras tanto, Blanche y Rose se preparan para los papeles en la obra " Gatos ".', 24, '1988-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 6, 'La boda de Sophia (Parte 1)', 'La muerte de una amiga cercana, Esther Weinstock, enfrenta a Sophia cara a cara con el esposo de Esther, un hombre al que ella juró que nunca más volvería a hablar debido a las cosas que sucedieron en el pasado. Sin embargo, cuando Dorothy les pide que se reconcilien, se acercan un poco y terminan juntos en la cama. Poco después, anuncian su compromiso, algo contra lo que Dorothy está totalmente en contra. Mientras tanto, Blanche y Rose comienzan un club de fans de Elvis Presley.', 24, '1988-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 7, 'La boda de Sophia (Parte 2)', 'Sophia y Max regresan de su luna de miel sin un lugar donde quedarse, por lo que Blanche, Dorothy y Rose los acogen hasta que puedan encontrar un lugar. Mientras tanto, Sophia y Max deciden reiniciar el viejo negocio que Max tenía con el difunto esposo de Sophia, una pizzería. A todo esto, Dorothy comienza a fumar de nuevo.', 24, '1988-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 8, 'Hermano, te sobra esa cazadora', 'La búsqueda para encontrar el boleto de lotería ganador que le daría a las chicas $10,000 ha comenzado. Lo pusieron en el bolsillo de una chaqueta de aviador, que Sophia confundió con un artículo para enviar a una tienda de segunda mano. La búsqueda lleva a las chicas a dicha tienda, luego a una subasta de celebridades y, finalmente, a un refugio para personas sin hogar.', 24, '1988-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 9, 'Un susto de muerte', 'El hermano de Blanche, Clayton, viene a Miami para una visita y Blanche hace todo lo posible para arreglarle una cita a ciegas. Sin embargo, Rose descubre la verdad, Clayton es gay y teme decirle a Blanche la verdad sobre él.', 24, '1988-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 10, 'Stan toma esposa', 'Stan da la noticia de que está comprometido para casarse, algo que Dorothy al principio parece aceptar. Sin embargo, después de que Sophia cae enferma, Stan reconforta a Dorothy, lo que despierta viejos sentimientos en ella y se plantea tratar de volver con Stan.', 24, '1989-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 11, 'La subasta', 'Las chicas tratan de ganar el dinero suficiente para pagar un nuevo techo. Mientras tanto, el trabajo voluntario de Sophia en el hospital es lo que les brinda una información privilegiada que podría darles el dinero suficiente para el nuevo techo y aún sobraría. La información es que un artista famoso se está muriendo, por lo que las chicas se dirigen a una subasta para ofertar por una de sus pinturas.', 24, '1989-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 12, 'Cita a ciegas', 'Después de ser abandonada por su novio, Blanche se hace amiga de un hombre en un bar y hace una cita sin darse cuenta de que es ciego. Mientras tanto, Dorothy y Rose intentan entrenar a un equipo de fútbol infantil.', 24, '1989-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 13, 'La impotencia de llamarse Ernesto', 'Rose está loca por su último novio, Ernie, pero no puede entender por qué no aborda el tema del sexo, por lo que cuando lo obliga descubre la verdad, él es impotente.', 24, '1989-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 14, 'Ámame tiernamente', 'Cuando Sophia le organiza a Dorothy una cita a ciegas, Dorothy se enamora secretamente del hombre aparentemente simple, y afirma que "es el mejor amante que jamás haya tenido". Mientras tanto, Blanche y Rose se unen al "Be a Pal" y se convierten en amigos de dos chicas sin madre.', 24, '1989-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 15, 'El día de San Valentin', 'Es el día de San Valentín, y las chicas están emocionadas hasta que cada una de sus citas se cancele en el último minuto. Esto las hace recordar el pasado del día de San Valentín.', 24, '1989-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 16, 'Dos cabalgaron juntas', 'Dorothy quiere pasar un tiempo de "calidad" con Sophia, así que se lleva a Sophia el fin de semana a los Cayos de Florida. Sin embargo, sus intentos fracasan cuando una Sophia se harta de las tormentas. Mientras tanto, Rose y Blanche intentan escribir cuentos infantiles.', 24, '1989-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 17, 'Hay que tener esperanza', 'Dorothy está a cargo de un programa de caridad del hospital y las cosas no van como ella quiere. No puede encontrar ningún talento para el show de talentos y su maestro de ceremonias acaba de renunciar. La solución de Rose para su problema empeora las cosas cuando las chicas recorren Miami con la esperanza de que Bob Hope se presente en el espectáculo.', 24, '1989-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 18, 'El violinista en las cuerdas', 'Sin el consentimiento de las otras chicas, Sophia apuesta sus ahorros de su vida, Pepe, un luchador premiado. Sin embargo, en la víspera de la pelea, las chicas descubren que Pepe está desaparecido y hacen un descubrimiento sorprendente.', 24, '1989-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 19, 'Hasta la muerte bolearemos', 'Una vieja amiga de Dorothy, Trudy viene de visita y esto reaviva su antigua rivalidad entre ellas. Sin embargo, la visita se vuelve trágica cuando Trudy muere repentinamente y Dorothy se culpa a sí misma.', 24, '1989-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 20, 'Alta ansiedad', 'Después de que Sophia golpea accidentalmente una botella de las píldoras de Rose en el fregadero, se descubre que es adicta a ellas. Luego debe luchar contra la abstinencia cuando no puede coger otra botella. Mientras tanto, Dorothy y Sophia son contratadas para estar en un comercial de pizza.', 24, '1989-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 21, 'Hermanita', 'La hermana de Rose, Holly viene de visita y se hace amiga rápidamente de Dorothy y Blanche, y deja a Rose de lado. Sin embargo, cuando Rose pilla a Holly con el novio de Blanche y trata de decirselo a Blanche, Dorothy y Blanche se niegan a creerla.', 24, '1989-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 22, 'La decisión de Sophia', 'Sophia entra en acción para sacar a su amiga Lillian de "la peor residencia de ancianos de la ciudad". Sin embargo, Lillian demuestra ser un hueso duro de roer para que Sophia la maneje. Mientras tanto, Blanche considera agrandar sus pechos.', 24, '1989-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 23, 'Ritos de primavera', 'Una semana antes de la fiesta anual de una amiga, las chicas debaten sobre qué deben hacer para mejorar su apariencia. Esto las lleva a recordar los intentos anteriores de mejorar su apariencia.', 24, '1989-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 24, 'Intercambio extranjero', 'Los viejos amigos de Sophia, Philomena y Dominic, vienen de Sicilia desde Miami, para una visita y tienen noticias impactantes para Dorothy. Philomena y Sophia se habían reunido en el hospital cuando estaban dando a luz y ahora Philomena y Dominic afirman que hubo una confusión y que Dorothy fue cambiada al nacer. Mientras tanto, Blanche y Rose toman lecciones de "baile sucio".', 24, '1989-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 25, 'Nos vamos de aquí (Parte 1)', 'Blanche, Dorothy y Rose regresan a casa de una obra para descubrir a Sophia en medio de la venta de la casa. Más tarde, se descubrió que un cartel de venta se colocó accidentalmente en el jardín delantero, pero Blanche comienza a considerarlo después de ver la cantidad que le ofrecieron.', 24, '1989-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 4), 26, 'Nos vamos de aquí (Parte 2)', 'Blanche debate si vender o no la casa, ya que ella y el resto de las chicas recuerdan los momentos que pasaron juntas (a través de flashbacks).', 24, '1989-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 5, 'Temporada 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 1, 'Enferma y cansada (Parte 1)', 'Dorothy se siente agotada, cansada todo el tiempo y carece de energía. Está segura de que está enferma, pero todos los médicos que visita le dicen que está bien. Mientras tanto, Blanche decide escribir una novela romántica.', 24, '1989-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 2, 'Enferma y cansada (Parte 2)', 'Dorothy sigue buscando consejo médico y busca ayuda en Harry Weston. Mientras tanto, Blanche tiene una borrachera de escritura que resulta en una novela que es menos de todo menos cautivadora.', 24, '1989-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 3, 'Una concepción de precisión', 'La hija de Blanche, Rebecca tiene una maravillosa noticia. Se convertirá en madre, a través de la inseminación artificial. Sin embargo, Blanche está menos emocionada, está totalmente en contra de todo.', 24, '1989-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 4, 'Rose contraataca', 'Cuando la compañía para la que trabajaba el esposo de Rose corta su plan de pensiones, Rose debe enfrentar el hecho de que va a tener que conseguir un nuevo trabajo, uno que pague más. Sin embargo, rápidamente se encuentra lidiando con algo que nunca esperó, la discriminación por edad. Mientras tanto, Sophia se vuelve loca comprando cosas en cantidad en un Almacén de compradores.', 24, '1989-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 5, 'Amor bajo la carpa', 'Dorothy tiene una relación seria con un abogado y llega a la conclusión de que está a punto de hacerle una propuesta. Sin embargo, su anuncio es impactante, va a dejar las leyes para convertirse en un payaso de circo. Mientras tanto, Rose y Blanche organizan una protesta para salvar a algunos delfines.', 24, '1989-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 6, 'Bailando en la oscuridad', 'Rose ha estado saliendo con Miles Webber, un profesor universitario, pero lo único que parecen tener en común es la pista de baile. Pero cuando Miles la invita a una fiesta, Rose se siente como un pez fuera del agua rodeada de todos sus amigos inteligentes. Mientras tanto, Blanche lucha contra una disminución de las citas.', 24, '1989-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 7, 'Ni un lunes más', 'La amiga de Sophia ha tenido una idea que cambiará su vida. Ella quiere suicidarse y quiere que Sophia esté allí para tomar su mano. Mientras tanto, Blanche, Rose y Dorothy se convierten en enfermeras cantantes de un bebé enfermo que cuidan durante el fin de semana.', 24, '1989-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 8, 'Ese viejo sentimiento', 'Blanche recibe la visita de su cuñado y queda impresionada por su parecido con su difunto esposo. Rápidamente se  enamora con la esperanza de contraer matrimonio.', 24, '1989-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 9, 'La comedia de los errores', 'Dorothy encuentra una lista de cosas que quería hacer antes de cierta edad y descubre que no ha logrado muchas de ellas. Así que decide ir tras una de ellas, entreteniendo a la gente. Esto la lleva a inscribirse para hacer una rutina de pie en un club nocturno. Mientras tanto, Blanche se encuentra luchando contra el IRS.', 24, '1989-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 10, 'Todo ese jaleo', 'El hijo de Dorothy, Michael, aparece en su puerta con noticias de que se ha separado de su esposa y necesita un lugar para quedarse. Sin embargo, Dorothy se cansa rápidamente de él y se lo deja a Stan. Mientras tanto, el estrés de Rose se está volviendo terrible y se muestra reacia a hablar con su jefe acerca de reducir su lista de "cosas por hacer".', 24, '1989-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 11, 'Marea baja', 'Blanche se derrumba después de que su padre, Big Daddy, fallece. Sin embargo, cuando regresa a su hogar de la infancia, tiene una gran discusión con su hermana, Virginia, y decide no asistir al funeral.', 24, '1989-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 12, 'Que tengas una Navidad muy pequeña', 'Es época de Navidad y las chicas están hartas de las compras navideñas en una ola de calor. Así que deciden comprar regalos para la persona que escogen de un sombrero. Más tarde, las chicas deciden servir la cena de Navidad para las personas sin hogar, incluido un Stan recientemente sin hogar.', 24, '1989-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 13, 'Mary tiene un corderito', 'Las chicas acogen a una niña de 15 años que acaba de descubrir que está embarazada y tiene miedo de decírselo a su padre. Mientras tanto, el amigo por correspondencia de la prisión de Blanche acaba de ser liberado y la está buscando.', 24, '1990-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 14, 'Grandes esperanzas', 'Rose se une a un grupo de pensamiento positivo y trata de que una Dorothy pesimista se una. Mientras tanto, Blanche tiene miedo de ponerse seria con su último novio, especialmente después de un ataque al corazón.', 24, '1990-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 15, 'Triple jugada', 'Blanche intenta atraer a los hombres colocando un anuncio falso en el periódico tratando de vender un Mercedes. Mientras tanto, Rose tiene que lidiar con conocer a la hija de Miles, que deja en claro que quiere que su relación no vaya a más y Dorothy descubre que Sophia está acaparando dinero de la Seguridad Social, gracias a un error de computadora.', 24, '1990-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 16, 'Recuerdos de Clinton Avenue', 'Dorothy se alarma cuando Sophia olvida la fecha de su aniversario de boda. Esto lleva a Dorothy a enfrentar el hecho de que Sophia se está volviendo más y más olvidadiza con la edad. Después de visitar a un médico, Sophia decide recuperar algunos de los recuerdos que ha perdido y decide hacer un viaje a Brooklyn y su antiguo apartamento.', 24, '1990-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 17, 'Como el bib bib del tam tam', 'Después de visitar al médico, Blanche se entera de que quiere ponerle un marcapasos. Sin embargo, después de la operación, Blanche tiene tanto miedo a la intimidad que decide abandonar el sexo.', 24, '1990-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 18, 'Una preocupación ilegitima', 'Blanche se sorprende cuando un hombre se acerca a la puerta principal y afirma ser el hijo ilegítimo de su difunto esposo. Mientras tanto, Dorothy y Sophia entran en un concurso de madre e hija en Shady Pines.', 24, '1990-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 19, '72 horas', 'Rose descubre que puede estar portando el virus del VIH después de saber que la sangre que utilizaron en su operación de vesícula biliar puede haber contenido anticuerpos contra el VIH. Sin embargo, lo que realmente le afecta son las 72 horas que debe esperar antes de escuchar los resultados de la prueba. Mientras tanto, Dorothy se hace de la organización benéfica "Save the Swamplands".', 24, '1990-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 20, 'Dos veces en la vida', 'Rose debe decidir entre su novio, Miles o un viejo novio que acaba de venir a la ciudad y le pide que vaya a Europa con él. Mientras tanto, harta de las reglas de Dorothy, Sophia decide mudarse.', 24, '1990-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 21, 'Hermanas y otros extraños', 'Blanche y su hermana, Charmaine, se reconcilian después de una rivalidad de por vida. Sin embargo, la reconciliación no dura mucho después de que Blanche lee su libro recientemente publicado y se da cuenta de que la heroína se basa en ella. Mientras tanto, Dorothy se cansa del primo visitante de Stan.', 24, '1990-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 22, 'Timadores', 'El hombre casado con quien Dorothy salió una vez más vuelve a entrar en su vida y tiene le comunica que ahora está divorciado y le gustaría reconciliarse con Dorothy. Mientras tanto, Blanche y Sophia se convierten en víctimas de un juego de estafa.', 24, '1990-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 23, 'La maldición Mangiacavallo hace un regalo de boda nefasto', 'Las chicas asisten a la boda de la sobrina de Dorothy, cuyo padre una vez estuvo comprometido con Sophia. Sophia cree que la recepción de la boda es el lugar perfecto para la venganza después de supuestamente maldecirlo hace años.', 23, '1990-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 24, 'Fuera todas las apuestas', 'El problema de los juegos de azar de Dorothy reaparece después de una visita a la pista de carreras y rápidamente comienza a endeudarse y se vuelve apática en su trabajo. Mientras tanto, Rose comienza a pintar y Blanche se siente insultada después de que un hombre con el que trabaja rechaza sus avances.', 24, '1990-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 25, '¡Que viene el presidente! (Parte 1)', 'Un agente del FBI investiga la vida de las chicas para una posible visita del presidente Bush. Esto lleva a las chicas a recordar los momentos que han pasado juntas.', 24, '1990-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 5), 26, '¡Que viene el presidente! (Parte 2)', 'Cuando el agente del FBI anuncia que George Bush visitará su hogar, las chicas seguirán recordando y Dorothy prepara rápidamente una lista de las preguntas que quiere hacerle al presidente.', 23, '1990-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 6, 'Temporada 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 1, 'Blanche la Comadrona', 'La hija de Blanche quiere dar a luz en un centro de maternidad, mientras que Blanche está preocupada por la posibilidad de que Rebecca dé a luz en un hospital local. Blanche no quiere sentirse avergonzada por el hecho de que su hija fue inseminada artificialmente.', 24, '1990-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 2, 'Érase una vez en St. Olaf', 'Rose hace un descubrimiento sorprendente al admitir a un paciente en el hospital. Mientras tanto, Sophia tiene que someterse a una cirugía, pero se produce una confusión después de la operación y Sophia se pierde en el hospital.', 24, '1990-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 3, 'Al fin tienes éxito', 'Stan finalmente ha tenido éxito con un nuevo invento, pero aún así Dorothy no puede estar feliz por él. Mientras tanto, Rose y Blanche pelean por algunos bonos de guerra que, si se cobran, podrían llevar a la quiebra a St. Olaf.', 24, '1990-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 4, 'Anímate', 'Dorothy decide ayudar a Sophia con el programa Meals on Wheels y se encuentra con un hombre solitario que no ha salido de su apartamento desde la década de 1960. Mientras tanto, se acerca el cumpleaños de Blanche y Rose está decidida a descubrir su edad real.', 23, '1990-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 5, 'Gracias Mammy', 'Blanche recibe una visita inesperada de su infancia, su " mammy " (niñera), pero Blanche se resiste a hablar con ella desde que la abandonó cuando era niña. Mientras tanto, Sophia contrata a una casamentera para Dorothy que tiene una cita con un convicto.', 24, '1990-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 6, 'Sentimientos', 'Dorothy recibe amenazas después de fallarle a una estrella del fútbol, lo que significa que no puede jugar en un próximo partido. Mientras tanto, Rose debe tratar con su dentista que ella cree que la acarició durante su última visita.', 24, '1990-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 7, 'Zborn otra vez', 'Dorothy está siendo cortejada por Stan y parece que sus viejos sentimientos por él están resurgiendo. Mientras tanto, Rose tiene que lidiar con un compañero de trabajo molesto.', 24, '1990-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 8, '¿Como se resuelve un problema como Sofia?', 'Después de la muerte de una amiga, que había sido monja, Sophia decide que le gustaría serlo también. Así que se une a un convento y se muda. Mientras tanto, Blanche sufre un accidente automovilístico con el automóvil de Rose, dejando a Rose con una demanda.', 24, '1990-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 9, 'La señora de George Devereaux', 'Blanche tiene un admirador secreto y se sorprende cuando lo conoce, su esposo supuestamente muerto, George. Mientras tanto, Dorothy está siendo cortejada por dos hombres, Sonny Bono y Lyle Wagoner.', 24, '1990-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 10, 'Las chicas solo quieren divertirse antes de morir', 'Tanto Sophia como Rose siguen el consejo de Blanche y aterrizan a cada una de ellas en agua caliente. Debido a una sequía en St. Olaf, Rose jura ser célibe y Blanche le aconseja que no le diga la verdad a Miles. Mientras Sophia sigue los consejos de Blanche para atraer a un hombre a la cama, pero cuando ella le dice que lo ama, él no responde con lo que ella esperaba.', 24, '1990-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 11, 'Apoya a tu hombre', 'Blanche se encuentra con un hombre en la biblioteca y solo después de que hacen una cita se da cuenta de que está en una silla de ruedas. Mientras tanto, Rose quiere mantener a uno de los cachorros de la basura de Dreyfuss a pesar de los sentimientos de Blanche.', 24, '1990-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 12, 'La Venganza de Ebbtide', 'Dorothy debe hablar de su hermano Phil (un travesti), el su funeral. Mientras tanto, una disputa entre Sophia y la viuda de Phil alcanza un pico, lo que lleva a Sophia a revelar sus sentimientos ocultos sobre el estilo de vida alternativo de su hijo.', 24, '1990-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 13, 'La flor es de Rose', 'Rose quiere más aventura en su relación con Miles, por lo que los inscribe en clases de paracaidismo. Mientras tanto, la relación de Blanche con un hombre machista hace que Dorothy exprese sus sentimientos.', 24, '1991-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 14, 'La hermana de la novia', 'El hermano gay de Blanche, Clayton, que visita a Miami por sorpresa, ha encontrado a la persona adecuada para comprometerse, pero Blanche aún no puede superar la orientación sexual de Clayton. Mientras tanto, Rose espera ganar un premio al Voluntario del Año.', 24, '1991-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 15, 'La despedida de Miles', 'Después de escuchar que un mafioso ha muerto, Miles revela que ha estado en un programa de protección de testigos. Sin embargo, cuando se revela que el mafioso fingió su muerte, Miles debe abandonar Miami y esconderse.', 24, '1991-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 16, 'Ahí va la novia (1)', 'Dorothy se ha estado escondiendo para que Sophia no descubra que ha estado saliendo con Stan. Sin embargo, cuando Stan le propone matrimonio, Dorothy debe revelar la verdad a Sophia.', 24, '1991-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 17, 'Ahí va la novia (2)', 'En vista de las inminentes nupcias de Dorothy y Stan, Sophia jura no dejar que la ceremonia se realice. Mientras tanto, Blanche comienza a entrevistar a un nuevo compañero de cuarto ya que Dorothy planea mudarse.', 23, '1991-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 18, 'Más vieja y más sensata', 'Queriendo que alguien vigile a Sophia durante el día, Dorothy le consigue un trabajo con falsas pretensiones. Mientras tanto, Blanche y Rose están entusiasmadas con ser contratadas como modelos para un Penny Saver.', 23, '1991-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 19, 'Melodrama', 'Blanche quiere intensificar su relación con su infame hombre de una noche, Mel Bushman. Mientras tanto, Rose hace una prueba en los reportajes de televisión, su misión, una exposición canina.', 24, '1991-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 20, 'Hasta las abuelas se ponen tristes', 'Mientras cuida a su nieta, un hombre confunde a Blanche con la madre del bebé y Blanche no hace nada para aclararlo. Mientras tanto, Sophia se prepara para el Festival de las vírgenes bailarinas, una celebración de madres e hijas, pero Dorothy no quiere participar.', 24, '1991-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 21, 'Testigo', 'Rose tiene un nuevo hombre, Carl, en su vida, pero de repente se acuerda de Miles, todavía encubierto en el Programa de Protección de Testigos. Sin embargo, las cosas se complican cuando Carl se revela como el mafioso que está buscando a Miles. Mientras tanto, Sophia pierde sus gafas.', 23, '1991-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 22, 'Lo que hace diferente una fecha', 'El hombre que defendió a Dorothy por su graduación la contacta y tienen una cita. Después de saber por qué la dejó, Dorothy desata su ira sobre la persona culpable, Sophia.', 24, '1991-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 23, 'Amor en venta', 'Las chicas se preparan para la Subasta de Bachelorette del Children''s Hospital y Dorothy decide participar. Le espera una rápida sorpresa cuando Stan entra y comienza a ofertar. Mientras tanto, el hermano de Sophia, Angelo, llega a Miami, se quedo en bancarrota y no tiene un lugar donde vivir.', 24, '1991-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 24, 'Nunca grites fuego en un asilo abarrotado (1)', 'La confesión en el lecho de muerte de una ex paciente de Shady Pines, significa una mala noticia para Sophia, ya que en su confesión declaró que Sophia y ella provocaron el incendio de 1985 en Shady Pines.', 24, '1991-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 25, 'Nunca grites fuego en un asilo abarrotado (2)', 'Sophia no puede recordar los acontecimientos que condujeron al incendio de Shady Pines.', 24, '1991-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 6), 26, 'La Gallinita Penny', 'Dorothy está a cargo de dirigir una obra escolar, "La Gallinita Penny", pero cuando el reparto se pone en cuarentena, consigue que Rose, Blanche y ella actúen como directoras. Pero cuando Rose lee el final, no quiere participar en la obra.', 24, '1991-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')), 7, 'Temporada 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 1, 'Échame un vistazo', 'Rose descubre una vieja cámara de Charlie con una película sin revelar aún en ella. Después de revelarla, Rose se sorprende cuando una de las imágenes muestra a Charlie en la cama con Blanche. Mientras tanto, Dorothy intenta que Sophia haga revisar su audición.', 24, '1991-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 2, 'El caso de la Bella Libertina', 'Las chicas participan en un fin de semana de misterio de asesinato y Dorothy se divierte cuando resuelve un misterio. Sin embargo, cuando Blanche es acusada de cometer un asesinato real, Dorothy tendrá que usar todas sus habilidades de detective para encontrar al verdadero asesino.', 24, '1991-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 3, 'La Bella y la Bestia', 'Blanche es visitada por su nieta, Melissa, y lo único que Blanche tiene en mente es a Melissa ganando el Concurso de Belleza Little Miss. Mientras tanto, Dorothy contrata a una enfermera para que se ocupe de la recuperación de Sophia.', 24, '1991-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 4, 'Eso es asunto mio', 'Blanche se entera por un inspector de la ciudad que tiene que perder un inquilino o hacer modificaciones a su casa, lo que costaría $ 10,000. Mientras tanto, Dorothy exige saber quién es el novio en una foto oculta de la boda de Sophia.', 24, '1991-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 5, '¿Dónde está Charlie?', 'Después de que Miles le da a Rose un anillo de amistad, Rose se convence de que Charlie está tratando de contactarla desde el más allá con el mensaje de que desaprueba su relación con Miles. Mientras tanto, Blanche comienza a entrenar con su nuevo novio, jugador de béisbol.', 24, '1991-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 6, 'Madre no hay mas que una', 'Blanche comienza a salir con un presentador de noticias que tiene a otra mujer interfiriendo en su vida, su madre. Mientras tanto, Stan le pide a Dorothy que asista a una sesión de consejería con él. Una vez allí, Stan comienza a rogarle a Dorothy que lo lleve de regreso.', 24, '1991-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 7, 'Sellado en Miami', 'Es sábado por la noche y Dorothy, siendo la única con una cita, hace que las otras chicas recuerden algunas de las peores citas que han tenido.', 24, '1991-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 8, 'El Show del Mono (1)', 'Se está gestando un huracán y no es justo después de que Dorothy recibe la primera visita de Stan con la noticia de que la ha superado y que sigue adelante con su vida. Dorothy descubre rápidamente con quién está saliendo, con su hermana, Gloria. Mientras tanto, Blanche y Rose apoyan un telemaratón para salvar un faro.', 24, '1991-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 9, 'El Show del Mono (2)', 'Dorothy descubrendo a Gloria durmiendo con Stan solo se suma a la rivalidad que entre hermanos y Sophia ha tenido, por lo que se va justo antes del huracán.', 24, '1991-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 10, 'Rose ama a Miles', 'Rose lo recibido el dinero de Miles y decide seguir el consejo de Blanche y salir con ella y algunos grandes gastadores. Mientras tanto, Blanche se ha quedado a cargo de Sophia mientras Dorothy está ausente, y Sophia decide que este sería el mejor momento para hacer un viaje a Sicilia.', 24, '1991-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 11, 'Habitación 7', 'Sophia tiene una experiencia más allá de la muerte, al ver a su difunto esposo en el cielo mientras se atraganta con un dulce. Mientras tanto, Blanche está angustiada por la demolición de la plantación de su abuela, por lo que las chicas viajan a Atlanta. Una vez allí, Blanche se esposa al radiador.', 24, '1991-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 12, 'De aquí a la farmacia', 'Un hombre que Blanche no recuerda ha regresado del Golfo Pérsico con la esperanza de cumplir la promesa que supuestamente le hizo antes de irse, que ella será suya y solo suya. Mientras tanto, Sophia tiene a Rose que la ayuda a escribir su testamento.', 24, '1991-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 13, 'El anillo del papa', 'El papa está en la ciudad y Sofía va a su misa. Cuando ella va a besar su anillo, se desliza en la mano de ella. Mientras tanto, Rose está convencida de que Miles le está ocultando algo, así que como regalo de cumpleaños, Blanche le da a Rose un detective para espiar a Miles.', 24, '1991-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 14, 'Todos amigos', 'Los intentos de Sophia por encontrar a un hombre se desorientan cuando un hombre con quien se encuentra a través de las personas, como una sombra, su hermana. Mientras tanto, Rose se encuentra con un viejo novio de St. Olaf, a quien ella no puede recordar.', 24, '1992-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 15, 'Adiós Sr. Gordon', 'Dorothy es contactada por un maestro de secundaria del que una vez estuvo enamorada. Rápidamente comienzan a verse y Dorothy está convencida de que sus sentimientos son verdaderos. Mientras tanto, Rose prepara un programa de entrevistas.', 24, '1992-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 16, 'Obligaciones', 'Dorothy se ve envuelta en  la" Beatlemania " y comienza a salir con un imitador de los Beatles. Mientras tanto, Blanche comienza a preocuparse por su aspecto después de que ella usa todas sus armas para llevar a cierto hombre a la cama, pero en vano.', 24, '1992-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 17, 'Preguntas y respuestas', 'Dorothy está muy emocionada cuando se entera de que ''Jeopardy'' está haciendo pruebas en Miami. Esto la lleva a comenzar a prepararse para la prueba de audición pero luego resulta ser una molestia para todos en la audición.', 24, '1992-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 18, 'La ira de Stan', 'Es el día anual de " Comprar Sophia New Shoes ", y Dorothy se ve obligada a llevarla. Blanche también las acompaña, mencionando que podría ser divertido. Mientras tanto, el tío Angelo pasa por casa y Rose está allí. Ya que está tratando de encontrar una buena historia sobre la cual informar, está más que feliz de escuchar la historia de Angelo. Al parecer, su edificio de apartamentos está infestado de enormes insectos. Cuando las damas ven las noticias, Rose insiste en que vean las noticias sobre los insectos. Dorothy le dice a Rose que ella y Stan son los propietarios. Rose luego le dice que no se dio cuenta de que había un aspecto familiar en la historia. Ella no renunciará a la historia, y un minuto después, los policías aparecen para arrestar a Dorothy. Tienen un juicio, y Stan deja a su abogada por una mujer más joven que no sabe nada. El abogado defensor es imbatible al felicitar a los testigos, lo que los hace vulnerables a su favor. Stan y Dorothy terminan perdiendo y se ven obligados a vivir en un edificio de apartamentos sórdido por un tiempo.', 24, '1992-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 19, 'Viaje al centro de ayuda', 'Blanche trae a una solitaria Dorothy al Rusty Anchor para una noche de emoción. Sin embargo, Blanche no tenía la intención de ser ofuscada por Dorothy, quien comienza a cantar y al instante se convierte en el centro de atención.', 24, '1992-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 20, 'El sueño de una noche de invierno (1)', 'Una luna llena en el año bisiesto, incita a Blanche a lanzar una Fiesta de locura a la luz de la luna. Sin embargo, sus planes de ser ofendidas por los hombres van muy mal cuando Dorothy recibe toda la atención. Mientras tanto, Rose contempla casarse con Miles luego de ganar una luna de miel gratis en París.', 24, '1992-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 21, 'El sueño de una noche de invierno (2)', 'La luna llena y las festividades provocan sucesos extraños, como desvanecer las joyas de Blanche, Sophia tratando de romper una maldición y Dorothy y Miles compartiendo un apasionado beso.', 24, '1992-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 22, 'Rose, retrato de una dama', 'Es el cumpleaños de Miles y Rose planea regalarle un club de golf. Sin embargo, Blanche le da una idea que le daría sabor a su relación, fotos picantes. Mientras tanto, Dorothy comienza un nuevo trabajo.', 24, '1992-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 23, 'En casa otra vez, Rose (1)', 'Rose está molesta cuando se ha perdido la reunión de la escuela secundaria debido a que estaba enferma, por lo que Blanche la convence, a ella, a Dorothy y Sophia para que se reúnan en una reunión celebrada en Miami, haciéndose pasar por ausentes de esa escuela. Dorothy va como la aburrida reina de baile Cindy Lou Peoples, Blanche es la aparentemente guarra Susan, Rose es la estudiante de intercambio coreana Kim FongToi y Sophia es la Sra. Gonzales. Con eso, las chicas se mezclan con sus "ex" compañeras de clase, solo para darse cuenta de que las vidas de sus contrapartes son tan aburridas como las de ellos, sin embargo, cuando las chicas son descubiertas por los invitados ... ¡Rose tiene un ataque al corazón!', 24, '1992-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 24, 'En casa otra vez, Rose (2)', 'Mientras Rose se somete a una cirugía severa, las chicas intentan entretenerse con buenos recuerdos y risas, ¡solo para que la hija de Rose, Kirsten, las descubra y se diviertan! Kirsten es rencoroso con ellos y no les permite visitar a Rose. Kirsten visita a Rose, que está casi agotada, y trata de tener una conversación ... muy cómicamente, ya que la pobre Rose no lo es en absoluto. Con Rose entrando en cirugía, Kirsten se reconcilia con las chicas preocupadas. ¡Por fin, liberan a Rose y todos lanzan una fiesta sorpresa en casa para nuestra adorable St. Olafian!', 24, '1992-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 25, 'Alguien voló fuera del nido del cuco (1)', 'El tío de Blanche, Lucas Hollingsworth, está de visita pero, para sorpresa de nadie, Blanche está ocupada con una cita. Para negar su intrusión, Blanche le dice a Dorothy que él desesperadamente quiere conocer a una mujer de su inteligencia. Dorothy acepta verlo, pero ambos se enteran más tarde de que Blanche simplemente mintió para deshacerse de ellos y deciden vengarse actuando como si se estuvieran casando, para consternación de Blanche. Como resultado, Rose decide que debe irse a vivir con su hija Kirsten para ser la "Sofía de la casa", ya que Blanche finalmente acepta la idea de casarse con ella. Justo cuando Lucas está a punto de revelar la verdad, él decide hacerle la pregunta a Dorothy de verdad ...', 24, '1992-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088526')) AND numero_temporada = 7), 26, 'Alguien voló fuera del nido del cuco (2)', 'Dorothy acepta la propuesta de Lucas. Los dos planean atar el nudo dos meses después y en el camino a la capilla, Dorothy toma una limusina. Sin embargo, esta limusina es conducida por nada menos que Stanley Zbornak. Los dos comparten un momento bastante cómico, pero no obstante conmovedor, juntos antes de llegar a la capilla. En el pasillo, junto con Sophia, las chicas piensan para sí mismas acerca de la hermosa amistad que compartieron. Rose, Blanche y Sophia deciden que las tres no deben irse y dejar que Dorothy se vaya a Atlanta, pero no se va sin compartir algunas palabras finales con las chicas ...', 24, '1992-05-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 1, 'Temporada 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 1, 'La leyenda del Caballero Negro', 'Volviendo tarde del cine, Scooby-Doo y Shaggy descubren una antigua armadura en el asiento de un extraño camión. Cuando llegan Freddy con las chicas, descubren que la armadura pertenecía al "Caballero Negro", y un arqueólogo la iba a llevar al museo local. Al ir a entregarla, el señor Wickles (encargado del museo), les dice que cada noche de luna llena el caballero vuelve a la vida, y hace valer el hecho diciéndoles que el arqueólogo estaba desaparecido. Más tarde, los chicos se meten al museo para investigar, Freddy se va con Daphne, y Vilma con Shaggy y Scooby. Sin embargo, esa noche descubren que tal vez, la leyenda del caballero negro no puede ser falsa después de todo.', 22, '1969-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 2, 'Una pista para Scooby-Doo', 'Mientras disfrutan de una fiesta en la playa, los chicos se topan con el fantasma de un viejo buzo. El marino Tiburcio Tiburón clama que aquel es el fantasma del capitán Cutler, quien según la leyenda, murió en el mar hace muchos años. Luego de visitar a la esposa del capitán y encontrar pistas en los alrededores de la Marina, la banda, equipada con trajes de buceo, van bajo el agua para buscar al fantasma.', 22, '1969-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 3, 'El fantasma del castillo', 'Los chicos salen a dar un paseo en bote, pero se pierden en la niebla y llegan a una isla aparentemente desierta. Entonces deciden aventurarse a entrar en el castillo del pirata Morán, donde no solo encontrarán sorpresas, si no también a un fantasma transparente que puede atravesar las paredes. Fantasma que aparentemente flotaba y al final del episodio descubren que el fantasma no es real si no que se trata de un mago, quien auyentaba a los visitantes en la isla porque temía que encontraran su tesoro.', 22, '1969-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 4, 'El fantasma de Ciudad de Oro', 'Gracias a que Shaggy, leyó el mapa al revés, la pandilla termina en un típico pueblo del Viejo Oeste llamado Ciudad de Oro. El encargado del hotel en el que se hospedan, les dice que todos se han marchado del pueblo, debido a que están aterrados por el fantasma del Minero 49, cuyo lamento se oye por las noches, y cuyo fantasma no descansará hasta encontrar hasta la última beta de oro. Luego, los chicos deciden salir a buscar pistas, y al no encontrar nada, se meten en las profundidades de la mina de oro abandonada, donde terminarán encontrando algo más que pistas.', 22, '1969-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 5, 'El señuelo', 'Una banda de robaperros aterroriza la ciudad en la que están los chicos, así que van a ver al entrenador Buck Masters, cuyo perro está en peligro de ser robado. Los chicos tienen la idea de colocar a Scooby-Doo como señuelo para atrapar a los secuestradores. El plan sale tan bien, que la banda descubre que el líder de los secuestradores aparentemente es el fantasma de un médico brujo, lo que los lleva a investigar a un escalofriante poblado indio. Mientras los chicos son separados por una banda de murciélagos y Vilma pierde sus anteojos, Shaggy y Scooby descubren a los perros que habían sido raptados.', 22, '1969-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 6, 'Con mil demonios, ¿qué pasa aquí?', 'Los chicos van a visitar a su amiga Sharon Weatherby, esperando divertirse mucho. Pero descubren que el tío de Sharon está siendo amenazado por el fantasma de Elias Kingston. Luego de que Shaggy y Scooby encontraran al fantasma y de que el tío Stuart desapareciera, los chicos entran a la vieja y abandonada Mansión Kingston para buscarlo. ¡Pero lo encuentran convertido en un esqueleto! Ahora, deberán hacer de todo para resolver el misterio, desde enfrentarse a una mesa flotante, hasta visitar una casa de adivinos.', 22, '1969-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 7, 'Jamás persigas a un hombre mono', 'El tío de Daphne, John Maxwell, les da trabajo a los chicos como extras en su más reciente película: El Hombre Mono de la Montaña Prohibida, estelarizada por la protagonista Dulce de Miel, y el equilibrista Carl como el Hombre Mono. Pero los problemas empiezan cuando el verdadero hombre mono comienza a destruir el lugar y a lastimar a los actores. El tío de Daphne decide suspender la filmación hasta que el Hombre Mono sea capturado, y los chicos se quedan en el lugar a buscar pistas para resolver el misterio.', 22, '1969-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 8, '¡Falla divertida en los juegos mecánicos!', 'Mientras estaban en una playa pescando almejas, los muchachos hablan sobre el parque de atracciones que está cerca de allí y próximo a abrirse. Pero, de pronto, todas las atracciones en el sitio empiezan a funcionar sin que nadie las control y, después, se detienen tan misteriosamente como arrancaron. Los muchachos van a avisar a los cuidadores del lugar, pero ellos no saben nada al respecto. El autor de todo parece ser un extraño robot en forma de hombre. Ahora, todos, juntos o separados, deberán defenderse del comportamiento de aquel extraño humanoide.', 22, '1969-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 9, 'El teatro de los billetes falsos', 'Mientras comían una pizza, Shaggy y Scooby encuentran un estuche de violín lleno de dinero. Scooby se queda cuidándolo mientras Shaggy llama a los demás por teléfono, pero una perrita lo distrae y alguien se lleva el estuche. Siguiendo el rastro, los chicos terminan en el Teatro Marionetas Pietro, donde aparte de encontrar un amable titiritero, descubren un billete falso. Los muchachos deciden irse, pero vuelven a medianoche a investigar y son asustados por una macabra sombra encapuchada.', 22, '1969-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 10, 'El caso del Payaso Fantasma', 'Los chicos y Scooby ayudan a un enano llamado Max, y a Sansón el hombre fuerte, quienes tienen un aparatoso accidente al romperse la bicicleta donde viajaban. Max y Sansón trabajan en un circo cuyas estrellas han renunciado, ya que están siendo aterrorizadas por un Payaso Fantasma. Al ir a investigar, uno a uno (excepto Vilma y Fred), todos son víctimas del payaso fantasma, quien mediante sus poderes hipnóticos los convierte en sus esclavos. Ahora, deberán lidiar con Scooby convertido en equilibrista, Shaggy queriendo domar a los leones, y Daphne usando un vestido y andando en un monociclo.', 22, '1969-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 11, 'El castillo de Frankenstein', 'Los chicos van a visitar el castillo del Dr. Frankenstein, que fue transportado piedra por piedra desde Transilvania. Sin escuchar las advertencias de la gitana Carlota y del vigilante del castillo, los chicos entran y, después de que Daphne fuera secuestrada, descubren que al parecer el castillo está habitado por tres monstruos: un vampiro, un hombre lobo, y un monstruo Frankenstein, y ellos intentan auyentar a los muchachos para que se vayan. La famosa frase: "¡Y lo habría conseguido de no haber sido por estos chicos entrometidos y su perro!", es por primera vez presentada en este capítulo.', 22, '1969-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 12, 'Scooby-Doo y una momia también', 'Los profesores de Arqueología de una universidad les muestran a los chicos su última adquisición: la momia de Ankha (antiguo faraón egipcio), quien convertiría en piedra a todo aquel que osara violar su tumba. La maldición se cumple cuando los chicos encuentran a los profesor convertido en piedra, y una momia los persigue y asusta, ya que ellos tienen una moneda antigua que al parecer es muy importante.', 22, '1969-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 13, 'Cómo pescar una bruja', 'Regresando de un viaje de pesca, los chicos se topan con el misterio de una bruja y un zombi, que habitan un pantano y han asustado a todos en el pueblo. Al ir a investigar a la cabaña de la bruja, esta captura a Daphne, y ahora, siendo acediados por el zombi, la banda deberá buscarla en un viejo bote abandonado.', 22, '1969-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 14, 'Esfúmate, barco fantasma', 'El periódico dice que los barcos del rico propietario C.L. Magnus están siendo robados por el fantasma del pirata Barbarroja. Después de leer esto y visitar a Magnus, los chicos van en su bote para atraparlo, sin saber que pronto ellos son los que van a ser atrapados por el pirata y hechos prisioneros en su barco.', 22, '1969-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 15, 'El fantasma del aeropuerto abandonado', 'Una extraña nave y un fantasma de otro mundo aterrorizan un campo aéreo abandonado. Cuando la máquina del misterio se queda sin gasolina cerca del aeropuerto, los chicos se enteran de la situación, así que se aventuran a explorar el campo aéreo y resolver el misterio.', 22, '1969-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 16, 'Una noche de espanto, causa quebranto', 'Scooby-Doo podría heredar un millón de dólares del coronel Beaureguard Sanders... claro, siempre y cuando pase una noche en la vieja mansión familiar. Eso no sería problema, solo que la casa está embrujada. Y aunque Freddy, Daphne, Vilma y Shaggy estén ahí para acompañarlo, la tarea será difícil de cumplir, sobre todo con dos fantasmas verdes asustándolos y persiguiéndolos por todas partes. Los demás herederos (parientes del coronel) ya han huido de la casa.', 22, '1970-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 17, 'El Fantasma de las Nieves', 'Los chicos invitan a Vilma y Daphne a un viaje de esquí en la posada El Fin del Lobo, pero todo se complica cuando el fantasma del Yeti (o abominable hombre de las nieves), empieza a asustarlos. Después de visitar a un extraño hombre a quien el Yeti también persigue, los chicos investigan en las montañas donde encuentran pistas y peligro.', 22, '1970-01-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 2, 'Temporada 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 1, 'El espectro de Hyde', 'Después de una seción de magia en la escuela secundaria, los chicos van a tomar unos helados y al ver que ya es tarde, suben a la máquina del misterio, pero son asustados por el espectro de Hyde (un ladrón de joyas), que estaba escondido en la parte trasera de la furgoneta. La pandilla lo sigue en los pantanos y luego dentro de una casa, cuando de pronto caen en el laboratorio del doctor Jekyll, (un científico) que les cuenta que tal vez él mismo sea el espectro, ya que al igual que su tatarabuelo, podría estar transformándose en el temible señor Hyde, debido a una fórmula vitamínica que tomó. No creyendo esta historia, los chicos buscan en la casa, y pronto encuentran evidencias que aparentemente apuntan a que la culpable de todo es Helga, el ama de llaves del doctor.', 22, '1970-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 2, 'La máscara de Zen-Túo', 'Cuando los chicos van al barrio chino a ver el magnífico desfile, Daphne compra una misteriosa máscara, sin saber que esta le perteneció al antiguo dios chino de la guerra, Zen-Túo, y ahora su fantasma ha enviado a sus emisarios (zombis encapuchados), para recuperarla y llevarla de vuelta al templo. Después de una persecución, los zombis capturan a Daphne y a la máscara, así que Fred, Vilma, Shaggy y Scooby van al templo a buscarla. ¿serán capaces de salvar a Daphne y encontrar alguna pista?', 22, '1970-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 3, 'La noche de los pies helados', 'Shaggy y Scooby van a pescar y enganchan a un cavernícola congelado de hace dos millones años que se perdió en el mar durante una tormenta violenta. La pandilla se lo lleva a Oceanland, pero cuando alguien se derrite el cavernícola del hielo y los científicos están actuando de manera extraña, la banda decide quedarse e investigar.', 22, '1970-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 4, 'El papel misterioso', 'Camino al baile de la escuela que se realizará en un viejo granero, los chicos encuentran a un guardia bancario tirado en el camino, que les entrega un papel en blanco y les dice: "la llama les dirá quién es el rastreador". Al llevarlo con el presidente del banco, el señor Carlswell, este les dice que el banco había estado siendo robado por un fantasma conocido como el Rastreador. Los chicos se van a divertir al baile, pero este es interrumpido por la aparición del fantasma. Mientras los chicos buscan pistas en los bosques y el campo, Scooby encuentra un pollito que lo confunde con su mamá y la pandilla visita la cueva de un ermitaño para buscar pistas.', 22, '1970-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 5, 'La leyenda del decapitado', 'Los chicos van camino aun concierto en camino la Máquina del Misterio se recalienta en frente de una vieja mansión espeluznante, y la banda va a buscar ayuda, pero solo encuentran el horror en un fantasma sin cabeza. Pero, ¿qué son los sonidos que golpean misteriosas que oyen?, y ¿son las pistas por toda la casa lo que lleva a un tesoro escondido?', 22, '1970-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 6, 'La aldea encantada', 'Shaggy y Scooby paquete de vacaciones de Hawái es interrumpido por un médico brujo, quien advierte a los turistas y nativos que se encuentran en los terrenos sagrados del dios isla Mano Tiki Tia. La banda busca a Sr. Simms, su guía, en una antigua aldea de una tribu perdida y descubrir un montón de perlas y un misterio.', 22, '1970-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 7, '¿Quién teme al lobo feroz?', 'La pandilla va a acampar y escucha los sonidos de un lobo que rastrean a un antiguo cementerio y la tumba abierta de Silas Long, que era sospechoso de ser un hombre lobo. Ellos siguen sus huellas a un viejo, serrería abandonada llena de lana y barriles vacíos y el hombre lobo espeluznante.', 22, '1970-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 8, 'No juegues con un fantasma', 'Al participar en el Johnny Sands Dance Game Show, los adolescentes se encuentran con el fantasma de la cera que se roba una caja fuerte llena de dinero y secuestra a la gerente de la estación. Es el fantasma de un engaño o es la maldición de un empleado de edad en busca de venganza por la cancelación de su programa.', 22, '1970-10-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 3, 'Temporada 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 1, 'El caso de la criatura de la garra de búho', 'Vilma se presemtó en casa de su tío a Dave para visitar. Pero durante su visita, se enteran de que él desapareció. Luego, se encontraron con el legendario Willawaw y dos hombres búhos que pueden ser responsables de la desaparición tío Dave. Según la leyenda, si un búho llama a su nombre, usted será la próxima víctima del Willawaw afirma.', 22, '1978-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 2, 'Un enredo en el Triángulo de las Bermudas', 'Si bien en un barco que fluye por la corriente del Golfo, poner fin a la cuadrilla para arriba en el Triángulo de las Bermudas y descubre un platillo volante del avión por rapto y un trío de hombres esqueléticos.', 22, '1978-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 3, 'Noche de terror con el monstruo de las nieves', 'Después de haber sido invitado por el profesor Krueger en el polo Norte, la pandilla descubre que ha sido capturado. Después de que cumplan un esquimal nombrado jefe Minook, él es capturado también. Según cuenta la leyenda de los esquimales lo tiene, el Monstruo de la Nieves vendrá a buscarte si vives en su tierra sagrada.', 22, '1978-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 4, 'Cambiando a la bruja', 'En la noche de Halloween, la ciudad de Nueva Inglaterra de Salem está siendo perseguido por la bruja de Melissa Wilcox, que fue quemada en la hoguera en 1778. Después de recibir una llamada angustiada de su amiga Arlene Wilcox, un descendiente de la bruja acusada, la banda llega para ayudar, a pesar de haber sido advertido por el alcalde de la ciudad. La bruja, al parecer, es exactamente igual a Arlene. Poco después de la llegada de la banda, la gente del pueblo tienen un consejo y deciden tomar Arlene en custodia y que confesara que ha sido tomado por la bruja. Como Shaggy y Scooby a prepararse para Halloween, se encuentran con la bruja y descubre que ella lo hace, de hecho, se parecen a Arlene.', 22, '1978-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 5, 'El Monstruo del Alquitrán', 'La banda va a la antigua ciudad de Bizancio en Turquía. En el camino, se encuentran con el monstruo de Tar, que asusta a los trabajadores nativos de distancia, mientras que la apertura del santuario interior.', 22, '1978-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 6, 'El monstruo que emerge de las profundidades', 'La banda viaja a Escocia para visitar a su amigo Aggie MacDuff. Ella dice que la gente ha dejado a su castillo con miedo después de avistamientos de fantasmas. Ella dice que el fantasma es su bisabuelo, que no quiere visitantes. Parece que el fantasma juega gaitas a invocar el monstruo del lago Ness para ayudarle a asustar a la gente lejos del castillo.', 22, '1978-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 7, 'El caso del hombre de la cara de metal', 'A medida que la banda va el esquí acuático, se encuentran con Viejo Cara de Hierro. Según la leyenda, era un preso de una cárcel en la isla de la Calavera, y ahora su fantasma acecha. La historia transcurre en una nota más personal cuando la guía de la banda, el capitán Morgan, desaparece, y se dirigió a la isla para encontrarlo.', 22, '1978-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 8, 'Jeepers es el jaguar', 'Después de un aterrizaje de emergencia en una selva en Brasil, la banda se ve atrapado entre nativos headhunter y el Jaguaro: una criatura con la cabeza de un jaguar, y el cuerpo de un simio.', 22, '1978-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 9, 'El felino y las rayas de abeja', 'Mientras que en la ciudad de Nueva York, la banda está a punto de visitar de Daphne tía Olivia Dervy. Al visitarla, la banda se encuentra con una joyería que acaba de ser robado. Shaggy vislumbró una criatura gato vicioso dentro de la tienda. Pero a medida que la banda va a visitar a la tía de Daphne, ella dijo que un extraño paquete inesperado llegó a la puerta que tenía un medallón gato. Ella cree que todas las noches, ella se convierte en la criatura gato, la misma criatura gato que se dice que ha robado la tienda de joyas.', 22, '1978-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 10, 'Episodio 10', NULL, 22, '1978-11-11');
