INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 14, 'Episodio 14', NULL, 22, '1978-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 15, 'Episodio 15', NULL, 22, '1978-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 16, 'Episodio 16', NULL, 22, '1978-12-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')), 1, 'Miniserie', 'Tras el enorme éxito mundial de su libro "Cosmos", el carismático astrónomo y divulgador científico norteamericano Carl Sagan (1934-1996) lleva sus teorías y explicaciones sobre el conocimiento del Universo a la pequeña pantalla en esta aclamada serie que intenta responder a las grandes preguntas del Cosmos y la vida. Entre los temas que se abordan en los diferentes capítulos están los orígenes de la vida, la búsqueda de vida en Marte, la composición de las estrellas y las galaxias, los viajes interestelares, los efectos de la velocidad de la luz, los peligros de la destrucción de la Tierra por la tecnología humana y la búsqueda de vida extraterrestre, entre otros muchos temas. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 1, 'En la orilla del océano cósmico', 'Años luz, galaxias, estrellas, planetas: números y distancias, donde nos encontramos (Grupo Local). La Biblioteca de Alejandría. Eratóstenes y su cálculo de la circunferencia de la Tierra. Calendario Cósmico: desde los comienzos del universo hasta el destino de la humanidad.', 60, '1980-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 2, 'Una voz en la fuga cósmica', 'La historia de los Heike y la selección evolutiva artificial de los cangrejos que parecen samuráis. La evolución biológica a través de la selección natural, de las bacterias al hombre. Especulación sobre la existencia de vida en las nubes jovianas.  Creación de las "moléculas de la vida" en el laboratorio. El desarrollo de la vida en el Calendario Cósmico y la explosión cámbrica.', 60, '1980-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 3, 'La armonía de los mundos', 'Astronomía contra astrología. Ptolomeo y el modelo geocéntrico. Johannes Kepler y Tycho Brahe. Las leyes de Kepler', 60, '1980-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 4, 'Cielo e infierno', 'El evento de Tunguska, la composición y el origen de los cometas. Asteroides y cráteres de impacto. El planeta Venus en la ficción y en la realidad. Venus como ejemplo de efecto invernadero.', 60, '1980-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 5, 'Nostalgia por un planeta rojo', 'H. G. Wells y La guerra de los mundos. La visión errónea de Percival Lowell sobre los canales de Marte. Robert Goddard y los primeros cohetes. El Programa Viking y la búsqueda de vida en Marte', 60, '1980-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 6, 'Relatos de viajeros', 'Los Países Bajos en el siglo XVII. La vida y obra de Christian Huygens y sus contemporáneos. Las Voyager (primeras imágenes detalladas de Júpiter y sus lunas).', 60, '1980-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 7, 'El espinazo de la noche', 'La comprensión humana de que las estrellas son soles lejanos. La Vía Láctea y su historia en la mitología. Los filósofos jónicos: Anaximandro, Demócrito, Anaxágoras, Aristarco de Samos, Empédocles, Tales de Mileto. La curiosidad de los niños por los misterios del Cosmos. Dioses y Naturaleza', 60, '1980-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 8, 'Viajes a través del espacio y el tiempo', 'Las constelaciones y cómo cambian a lo largo del tiempo. La velocidad de la luz y la Teoría de la Relatividad de Albert Einstein. Dilatación temporal, corrimiento al rojo, corrimiento al azul en una Vespa. Los diseños de Leonardo da Vinci y los diseños de naves espaciales que viajarán a velocidades cercanas a la de la luz. Viajes en el tiempo y sus hipotéticos efectos en la historia de la humanidad. Los orígenes del Sistema Solar y otros mundos; la historia de la vida.', 60, '1980-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 9, 'La vida de las estrellas', 'Para hacer una manzana, primero hay que crear el universo...Potencias de diez, el gúgol y el gúgolplex, infinito. Átomos (electrones, protones, neutrones). La tabla periódica de los elementos. La creación de diferentes núcleos atómicos en las estrellas. El ciclo de las estrellas; enanas blancas, estrellas de neutrones, agujeros negros. La muerte del Sol y de la Tierra, supernovas, gigantes rojas, púlsars. Radiactividad y rayos cósmicos. La gravedad y sus efectos; la gravedad como curvatura del espacio-tiempo, la hipótesis de los agujeros de gusano. Agujeros Negros.', 60, '1980-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 10, 'El filo de la eternidad', 'Los orígenes del universo, la teoría del Big Bang. Tipos de galaxias, colisiones galácticas y quasars. Efecto Doppler, vida y obra de Milton Humason. El universo cuatridimensional. Dios contra un universo infinito; mitos de la creación, cosmología hindú. Contracción y reexpansión contra expansión eterna. El Very Large Array de Nuevo México, materia oscura, la hipótesis del multiverso.', 60, '1980-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 11, 'La persistencia de la memoria', 'Bits, las unidades básicas de la información. La diversidad de la vida en los océanos. Las ballenas y sus cantos. Las interferencias en las comunicaciones cetáceas por los humanos. La caza de las ballenas. El ADN y el cerebro como bibliotecas. Las estructura del cerebro humano: tronco cerebral, modelo de Paul MacLean: el cerebro reptil, sistema límbico y corteza cerebral. Los lóbulos frontales como sistema crítico en la planificación a largo plazo. Las neuronas y las conexiones entre ellas, los dos hemisferios cerebrales, y el cuerpo calloso. La evolución de las ciudades y la historia de las bibliotecas, libros y escritura. El desarrollo de los ordenadores y los satélites, potencial para la inteligencia global colectiva. La inteligencia en otros mundos y el disco de oro de las Voyager.', 60, '1980-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 12, 'Enciclopedia galáctica', 'La supuesta abducción alienígena de Betty y Barney Hill y los ovnis. La traducción de los jeroglíficos egipcios por parte de Jean François Champollion. Posibilidad matemática de existencia de más civilizaciones en nuestra galaxia. Nuestro camino en la comunicación con extraterrestres (SETI). Ecuación de Drake, autodestrucción de civilizaciones avanzadas. Reflexión acerca de una hipotética enciclopedia escrita por muchos mundos.', 60, '1980-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081846')) AND numero_temporada = 1), 13, '¿Quién habla en nombre de la Tierra?', 'Los Tlingit y el viaje de descubrimiento de La Pérouse. La destrucción llevada a cabo por los conquistadores españoles. Esta parte fue censurada y retocada en el doblaje original en España. Una visión de Sagan (descrita como un sueño) en la cual el mundo es destruido en una guerra nuclear. El "equilibrio de terror" de la Tierra hoy día. La destrucción de la Biblioteca de Alejandría y la muerte de Hipatia. El inicio del universo y los logros de nuestra civilización. Razonamiento de Sagan, en el que nos invita a amar y a proteger la vida, y de esta forma, continuar con nuestro viaje a través del Cosmos.', 60, '1980-12-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 1, 'Temporada 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 1, 'Dame el anillo alguna vez', 'Diana Chambers llega a Cheers acompañada de su novio, y termina aceptando el puesto de camarera que le ofrece Sam. ¿El inicio de una gran amistad? ¡Ni mucho menos!', 25, '1982-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 2, 'Las chicas de Sam', 'Diana entra poco a poco en la rutina de Cheers, y rápidamente se da cuenta de qué tipo de mujeres son las que a le gustan a Sam para pasar las noches. La cuestión es: ¿por qué le enfurece tanto este tema? ¿Es porque Sam es un machista redomado… o por algo más?', 24, '1982-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 3, 'El agravio de Carla', 'Nada más llegar a Cheers, Ed Kellner lanza una serie de improperios contra los Medias Rojas, el equipo de fútbol americano del que Sam había sido jugador estrella y el entrenador, pues… entrenador, claro. Curiosamente, el único que no se siente ofendido por estos comentarios es Sam.', 24, '1982-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 4, 'Sam a las once', 'Sam está encantado con que un antiguo compañero del equipo, Dave Richards, que recientemente se ha convertido en periodista deportivo de televisión, venga a Cheers a entrevistar a Sam para su serie de programas sobre viejas glorias del deporte.', 24, '1982-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 5, 'La hija del Entrenador', 'La llegada de Lisa Pantusso alegra enormemente al entrenador ya que no ha visto a su hija desde hace algún tiempo. El problema es que también Sam está encantado con ella.', 24, '1982-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 6, 'Cualquier amigo de Diana', 'Rebecca Prout acaba de sufrir un duro golpe al romperse su relación sentimental con un hombre inteligente. Cuando llega a Cheers, Rebecca le confiesa a Diana que está buscando a un hombre con poco cerebro.', 24, '1982-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 7, 'Amigos, romanos y contables', 'Norm es elegido como maestro de ceremonias de la fiesta anual de su empresa. Ante tal responsabilidad, Norm tratará de impresionar a su jefe.', 24, '1982-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 8, 'Tregua o sus consecuencias', 'Carla y Diana se pasan todo el día discutiendo, sin nada agradable que decirse. Todo cambia en el momento en que Carla se decide a confiar en Diana y le cuenta un secreto sobre uno de sus embarazos.', 24, '1982-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 9, 'El Entrenador vuelve a la acción', 'A pesar de que ha transcurrido mucho tiempo desde que el entrenador no tiene ninguna cita, poco a poco comienza a sentirse atraído por una de sus vecinas, Ninda Bradshaw.', 24, '1982-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 10, 'Caída sin fondo', 'Rick Walker, uno de los pitchers de los Medias Rojas, llega a Cheers totalmente abatido y desanimado. ¿El motivo? Que los aficionados están su contra.', 23, '1982-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 11, 'Frases para el libro', 'Kevin, un joven que está a punto de ingresar en un convento, llega a Cheers para disfrutar de su última aventura amorosa con una botella.', 23, '1982-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 12, 'Un espía en Cheers', 'Eric Finche, un auténtico "gentleman" inglés, lleva algún tiempo acudiendo a Cheers para contar historias sobre su pasado como agente secreto durante la Segunda Guerra Mundial.', 24, '1982-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 13, 'Lanzando ahora… Sam Malone', 'Cuando la atractiva agente comercial de televisión Lana Marshall llega a Cheers, se ve rápidamente atraída por Sam. Y, como ya sabemos, para conquistar a Sam no hace falta esforzarse mucho…', 23, '1983-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 14, 'Un modo de contarlo', 'Diana se encuentra totalmente hundida. Su gata, Elizabeth Browning, acaba de morir, y la camarera no logra sobreponerse a su pérdida.', 23, '1983-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 15, 'El papá es el último que lo sabe', 'Carla vuelve a quedarse embarazada, pero esta vez está dispuesta a encontrar a un hombre que asuma la responsabilidad como padre.', 23, '1983-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 16, 'Los chicos del bar', 'Sam, que siempre disfruta hablando de su pasado, se muestra encantado de que un antiguo compañero de habitación y de equipo, Tom Jackson, le haya pedido que organice una fiesta en Cheers con motivo de la publicación de su autobiografía.', 23, '1983-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 17, 'El ligue perfecto de Diana', 'Sam y Diana se ven inmersos en una de sus típicas disputas en las que el uno se dedica a criticar las citas del otro y viceversa. Sin embargo, esta no va a ser una discusión como las demás…', 23, '1983-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 18, 'Nada de concursos', 'Creyendo hacer lo correcto, Sam inscribe a Diana en el concurso de Miss Camarera de Boston que tendrá lugar en Cheers. Evidentemente, Diana no estará demasiado de acuerdo.', 23, '1983-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 19, 'Elige un delincuente... a cualquier delincuente', 'Los habituales de Cheers se llevan una buena sorpresa cuando se enteran de que el entrenador ha contraído una deuda de 8.000 dólares por mezclarse en asuntos turbios junto a su amigo George Wheeler.', 23, '1983-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 20, 'Alguien soltero... alguien triste', 'La madre de Diana, Helen, llega a Cheers con un ultimátum: si Diana no se casa en menos de 24 horas, Helen perderá la herencia que le ha de dejar el padre de Diana.', 23, '1983-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 21, 'Desapareces (1ª Parte)', 'Derek, el hermano de Sam, aparece en Cheers, e inmediatamente impresiona a todo el mundo, y muy especialmente a Diana. Diana sigue saliendo con Derek, y Sam se refugia en una vida social cada vez más activa para así poder olvidarse de ella.', 23, '1983-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 1), 22, 'Desapareces (2ª Parte)', 'Derek, el hermano de Sam, aparece en Cheers, e inmediatamente impresiona a todo el mundo, y muy especialmente a Diana. Diana sigue saliendo con Derek, y Sam se refugia en una vida social cada vez más activa para así poder olvidarse de ella.', 23, '1983-03-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 2, 'Temporada 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 1, 'El juego del poder', 'La pandilla habitual encuentra que el romance de Sam y Diane es difícil de creer, una visión aparentemente compartida por Diane, quien arroja a Sam fuera de su apartamento después de solo cinco minutos.', 23, '1983-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 2, 'La hermana tímida', 'Carla se va de licencia por maternidad y es reemplazada por su supuestamente tímida e inocente hermana.', 23, '1983-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 3, 'Negocios personales', 'Diane, enojada por la implicación de que no podía tener un trabajo en otro lugar que no fuera Cheers, se va para una mejor posición y Norm deja a Vera.', 23, '1983-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 4, 'El actor homicida', 'Andy, el hombre al que Sam pagó para salir con Diane en una cita a ciegas, regresa a Cheers para mostrar su habilidad como actor.', 23, '1983-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 5, 'La vuelta de Summer', 'El ex novio intelectual de Diane regresa para reclamarla y pone a Sam en un ataque de ansiedad cuando intenta medirse leyendo a Tolstoy.', 23, '1983-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 6, 'Asuntos del corazón', 'Carla rechaza a un hombre interesado en ella románticamente, convencido de que debe tener algún "defecto fatal" para encontrarla atractiva.', 23, '1983-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 7, 'La vieja llama', 'El viejo amigo de Sam, Dave Richards, le apuesta a Sam que puede romper su romance con Diane en 24 horas y parece algo seguro cuando Diane se entera de que todavía tiene su pequeño libro negro.', 23, '1983-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 8, 'El entrenador entrena otra vez', 'El entrenador se convierte en un conductor esclavo cuando es puesto a cargo del equipo de la Liga Pequeña.', 23, '1983-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 9, 'Me llaman May-Day', 'Sam y Diane se ponen al trabajo después de que Dick Cavett sugiriera que la autobiografía de Sam podría venderse.', 23, '1983-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 10, 'Como te quiero', 'Sam casualmente le dice a Diane que la ama y le provoca un análisis profundamente introspectivo de su relación.', 23, '1983-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 11, 'Sólo tres amigos', 'Diane al principio es incrédula y luego furiosa cuando se vuelve evidente que Sam y su amiga de la vieja escuela se encuentran muy atractivos mutuamente.', 23, '1983-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 12, 'El testamento', 'Sam deja que un hombre agonizante barra el bar solo por diversión, pero el hombre deja a los clientes del bar 100,000 dólares en una servilleta de papel.', 24, '1983-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 13, 'La batalla de los Ex', 'Como no quiere parecer solitaria y sin pareja mientras va a la ceremonia nupcial de su ex marido, Nick, a la rubia bretita Loretta, Carla le pide a Sam que la acompañe.', 24, '1984-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 14, 'No se necesita ayuda', 'Sam se arrepiente de pedirle a Norm que haga sus impuestos cuando el contable desempleado obtiene una devolución de cinco cifras.', 23, '1984-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 15, 'Con el entrenador ya somos tres', 'Sam y Diane quieren pasar un tiempo solos juntos, pero el solitario entrenador sigue uniéndose a ellos, sin darse cuenta de que está echando a perder su relación. En lugar de herir sus sentimientos al pedirle que no los moleste, Sam y Diane deciden juntarlo con una mujer para que los dejen en paz.', 24, '1984-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 16, 'Cliff se pone gallito', 'La actitud de sabelotodo de Cliff finalmente lo lleva a una pelea.', 24, '1984-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 17, 'El destino y el peso de los hombres', 'El entrenador se ve obligado a comprar una báscula vieja que también imprime fortunas. Cada uno de la pandilla de Cheers ve con ella su fortuna, a excepción de Diane, que piensa que es todo un montón de basura. Mientras tanto, Norm y Vera progresan en su relación.', 24, '1984-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 18, 'Problemas con la nieve', 'Sam le miente a Diane sobre el fin de semana que ha planeado persiguiendo conejos de nieve en Vermont.', 24, '1984-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 19, 'El entrenador entierra el rencor', 'Un viejo amigo de El Entrenador muere y decide hacerle un memorial en el bar, invitando a todos sus viejos amigos. Pero luego el entrenador descubre que su amigo fallecido tuvo encuentros con su difunta esposa.', 24, '1984-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 20, 'La conquista de Norman', 'Los habituales de Cheers animan a Norm a salir con una nueva clienta muy atractiva que parece estar interesada en él.', 24, '1984-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 21, 'Ya nos veremos (1ª Parte)', 'Sam encarga un retrato de Diane de un artista tan detestable que pronto le prohibe a Diane seguir posando para él.', 24, '1984-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 2), 22, 'Ya nos veremos (2ª Parte)', 'Sam encarga un retrato de Diane de un artista tan detestable que pronto le prohibe a Diane seguir posando para él.', 24, '1984-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 3, 'Temporada 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 1, 'El Rechazo (Parte 1)', 'El entrenador le pide a Diane que regrese a Cheers de su auto-impuesto "vacaciones" para ayudar a Sam, que se ha caído del carro.', 24, '1984-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 2, 'El Rechazo (Parte 2)', 'El entrenador le pide a Diane que regrese a Cheers después de sus ''vacaciones'' autoimpuestas para ayudar a Sam, quien se ha descarriado.', 24, '1984-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 3, 'Yo pronuncio tu nombre', 'Frasier le pide a Sam un consejo sobre su relación más íntima con Diane y Cliff se esconde de un compañero de trabajo postal vengativo.', 24, '1984-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 4, 'Un cuento de hadas se hace realidad', 'Cliff conoce a una mujer durante una fiesta de disfraces en Cheers que le gusta mucho, pero tiene miedo de volver a verla como él mismo.', 24, '1984-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 5, 'Sam pone la otra mejilla', 'Sam inventa una historia elaborada para explicar cómo le dispararon en el trasero, sin querer contarles a todos la verdadera razón: un marido celoso le disparó.', 24, '1984-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 6, 'El entrenador se enamora (Parte 1)', 'El entrenador se enamora de una mujer que lo deja después de ganar una gran lotería, mientras Sam se enfrenta a su hija.', 23, '1984-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 7, 'El entrenador se enamora (Parte 2)', 'El entrenador se enamora de una mujer que lo deja después de ganar una gran lotería, mientras Sam se enfrenta a su hija.', 23, '1984-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 8, 'Diana conoce a mamá', 'Diane conoce a la madre de Frasier, quien silenciosamente amenaza con matar a Diane si no deja a Frasier en paz.', 24, '1984-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 9, 'Una familia americana', 'Nick regresa y exige a Carla una división más equitativa de su propiedad conyugal: a saber, él obtener la custodia de uno de sus hijos, una demanda a la que Carla está de acuerdo.', 24, '1984-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 10, 'La alergia de Diana', 'Diane sufre una misteriosa reacción alérgica después de mudarse con Frasier.', 24, '1984-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 11, 'Peterson Crusoe', 'Norm se da cuenta de su propia mortalidad y decide dejarlo todo y partir hacia Bora Bora.', 24, '1984-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 12, 'Retirada a tiempo', 'Sam conoce a uno de los intensos amigos de Diane, quien invita a sus padres a conocer a Sam, su futuro yerno, horas después de su primera cita.', 24, '1984-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 13, 'Dr. Ladlow', 'Frasier queda devastado cuando se entera de que su erudito mentor ha estado saliendo con Carla, quien también tiene su propia sorpresa.', 24, '1985-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 14, 'Cazando gamusinos', 'Los chicos llevan a Frasier a una cacería de ''agachadizas'' en el bosque después de que Diane les pide que incluyan al psicólogo en sus actividades masculinas.', 24, '1985-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 15, 'El rey de la colina', 'Sam regresa al montículo para un juego benéfico de softbol contra las conejitas de Playboy, pero su espíritu competitivo arruina el día en que las poncha a todas.', 24, '1985-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 16, 'El favorito de la maestra', 'Sam y el entrenador están tomando el mismo curso nocturno de geografía, pero mientras el entrenador estudia, Sam sale con la maestra.', 24, '1985-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 17, 'Correo a la cárcel', 'Norm es arrestado cuando termina la ruta para Cliff enfermo, pero Cliff se niega a respaldar la explicación de Norm a las autoridades.', 23, '1985-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 18, 'Apuesta en el bar', 'Sam corre el riesgo de perder el título ante un viejo amigo debido a una apuesta de que se casaría con Jacqueline Bissett antes de cierta fecha.', 24, '1985-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 19, 'Detrás de todo gran hombre', 'Sam enfrenta el desafío definitivo a sus habilidades como animal macho; una reportera que ha estado investigando la escena de los solteros de Boston y ha escuchado cada línea del libro.', 24, '1985-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 20, 'Si alguna vez te abandonara', 'Después de que su segunda esposa, Loretta, lo echa, el exmarido de Carla, Nick Tortelli, llega a Cheers y le pide a Carla que lo acepte de regreso.', 24, '1985-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 21, 'El ejecutivo ejecutor', 'Norm es ascendido a hombre hacha de la empresa debido a su estilo único para dejar ir a la gente.', 24, '1985-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 22, 'Adiós', 'Diane anuncia que dejará Cheers para acompañar a Frasier a Italia y Sam le organiza una fiesta de despedida.', 23, '1985-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 23, 'El cuento de la camarera', 'Carla insiste en que Sam debería contratar a una mujer mayor para reemplazar a Diane, pero no cuenta con la atracción de Sam por la hija de la mujer.', 24, '1985-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 24, 'Las bellezas de San Anacleto', 'Carla reúne a sus antiguos compañeros de la escuela St. Clete''s School for Wayward Girls para planear venganza contra su ex sádico director, a quien ve bebiendo en Cheers.', 24, '1985-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 3), 25, 'Rescátame', 'Frasier le propone matrimonio a Diane mientras están en Italia y ella hace una llamada de emergencia a Sam, con la esperanza de que él la convenza de no hacerlo.', 24, '1985-05-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 4, 'Temporada 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 1, 'Nacer, morir, amar y arroz', 'Después del triste fallecimiento del entrenador, Sam contrata a un nuevo barman: Woody Boyd, el amigo por correspondencia del entrenador que se mudó a Boston. Frasier regresa de Europa con la noticia de que Diane lo dejó en el altar durante seis meses de vida decadente en toda Europa y ahora busca renovación en un monasterio de Boston.', 24, '1985-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 2, 'El romance de Woody', 'La pandilla trae a la antigua novia de Woody a Boston para visitarlo y Frasier, que aún no está seguro de regresar a la psiquiatría, decide pagar la cuenta del bar trabajando como conserje.', 24, '1985-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 3, 'Un día llegará mi príncipe', 'Diane fantasea con un abrigo caro que dejó un cliente y acepta salir con quien lo reclame.', 24, '1985-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 4, 'El novio impetuoso', 'Carla le pide a Sam que le cuente a su hijo adolescente las alegrías de la soltería y que desalente sus ganas de casarse.', 24, '1985-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 5, 'Las pesadillas de Diana', 'Diane pasa una noche oscura y tormentosa preocupándose de que Andy Schroeder haya escapado y esté decidido a matarla.', 24, '1985-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 6, 'Te pagaré el martes', 'Sam le presta a Diane 500 dólares para comprar un libro autografiado por Ernest Hemmingway. Más tarde le da el libro a Sam como garantía hasta que pague el préstamo, pero Sam lo destruye accidentalmente.', 24, '1985-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 7, 'Amor por correspondencia', 'Los chicos del tromántico responden a un piloto de aerolínea ficticio. El bar siente lástima por Carla porque nadie ha respondido a su anuncio de solteros en el periódico. Entonces empiezan a enviarla.', 24, '1985-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 8, 'Ama a tu vecino', 'Norm teme que Vera pueda estar teniendo una aventura con su vecino y Sam pierde el tiempo como comentarista deportivo de radio disculpándose con Diane.', 24, '1985-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 9, 'De Cheers a la eternidad', 'Sam tiene que convencer a Woody para que ayude a Cheers a ganar un partido de bolos con Gary''s Old Towne Tavern en un bar rival.', 23, '1985-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 10, 'Taburete de bar', 'Cliff se niega a identificarse ante su padre separado cuando el hombre llega a Cheers con un mensaje importante para su hijo.', 24, '1985-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 11, 'Ser un Don Juan es un infierno', 'Sam está feliz de ser el tema del trabajo final de psicología de Diane hasta que descubre exactamente qué es el síndrome de Don Juan.', 24, '1985-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 12, 'Los tontos y su dinero', 'Sam cree que le está haciendo un favor a Woody al no hacer una apuesta por el joven, pero la posibilidad remota llega y Sam tiene que pagar.', 24, '1985-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 13, 'Llévate mi camiseta, por favor', 'El ego de Sam queda aplastado cuando nadie puja por su vieja camiseta de béisbol durante una subasta de la televisión pública.', 23, '1986-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 14, 'Sospecha', 'Diane hace arreglos para que un extraño entre en Cheers como parte de un experimento de comportamiento paranoico, pero luego ofrece un ejemplo aún mejor mientras espera que la pandilla se venga de ella.', 24, '1986-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 15, 'Vaya tres', 'Diane y Sam intentan reconstruir el ego destrozado de Frasier cuando empieza a beber demasiado.', 24, '1986-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 16, 'Cliff, el mejor cartero', 'Cliff tiene dos citas para el baile del cartero: con Carla y Diane.', 24, '1986-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 17, 'La segunda vez por aquí', 'Frasier tuvo una cita con una colega psiquiatra, la Dra. Lilith Sternin, pero las cosas no salieron muy bien. Frasier se siente deprimido, por lo que, sintiendo lástima por él, Sam organiza una cita entre Frasier y una mujer que conoce llamada Candy. Pero Sam y Diane se llevan una sorpresa cuando Frasier le propone matrimonio a Candy después de una sola cita.', 24, '1986-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 18, 'El principio de Peterson', 'Norm descubre algo sucio sobre su principal competidor para un ascenso, pero duda en usarlo.', 23, '1986-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 19, 'Oscuros pensamientos', 'Después de intentar (y fracasar) coquetear con una linda clienta, Sam siente que ha superado la colina y desafía a Woody a un partido de ráquetbol. Desafortunadamente, Sam termina lastimándose y tiene que ir al hospital.', 24, '1986-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 20, 'Reserva el último baile para mí', 'Carla le pide a Sam que la acompañe en un concurso de baile donde su principal competencia son Nick y Loretta.', 24, '1986-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 21, 'El miedo es mi copiloto', 'Un temerario volador con el que Diane arrasó por toda Europa los lleva a ella y a Sam a dar un paseo y muere a 20.000 pies de altura.', 24, '1986-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 22, 'El día de Diana Chambers', 'Diane se siente deprimida y excluida de las actividades de la pandilla, por lo que Frasier organiza un día solo para ella en la ópera.', 24, '1986-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 23, 'Relevo de Barman', 'Sam contrata a un nuevo barman y se nombra a sí mismo anfitrión/gerente de Cheers. Pero cuando su nueva estrategia fracasa y se ve obligado a regresar al bar, alguien tiene que ser despedido.', 24, '1986-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 24, 'Extraños compañeros de cama (1ª Parte)', 'La concejal local Janet Eldridge llega a Cheers como parte de su campaña de reelección y Sam se enamora de ella. Janet y Sam se convierten en pareja, pero Diane, celosa, se une a la campaña de la oposición por temor a que si Janet gana las elecciones, también se ganará el corazón de Sam. Mientras tanto, Frasier también se une a la campaña de oposición con la esperanza de recuperar a Diane.', 24, '1986-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 25, 'Extraños compañeros de cama (2ª Parte)', 'La relación de Sam y Janet se hace cada vez más fuerte mientras Diane se pone más celosa. Janet sugiere que Sam despida a Iane para cortar todos los lazos con su pasado, pero Diane escucha y renuncia antes de que él pueda despedirla. La hermana de Vera, Donna, está visitando a los Peterson y a Norm le preocupa que Donna coquetee con él como lo hizo en su última visita.', 24, '1986-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 26, 'Extraños compañeros de cama (3ª Parte)', 'Janet ganó las elecciones y ofrecerá su conferencia de prensa en Cheers. Diane aparece para disculparse con Sam, pero termina haciéndole a Janet algunas preguntas personales, lo que hace que Sam la eche del bar. Más tarde, Sam y Janet hablan y se dan cuenta de que su relación no funcionará, así que la rompen. Luego, Sam levanta el teléfono, llama a alguien y luego le pide que se case con él... Mientras tanto, han llamado a Vera, por lo que Donna se queda sola con Norm, para su horror.', 24, '1986-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 5, 'Temporada 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 1, 'El último intento', 'Finalmente descubrimos a quién fue la propuesta telefónica de Sam al final del último episodio: ¡Diane! Pero Diane teme que Sam simplemente esté recuperándose después de romper con Janet, por lo que le pide que repita la propuesta en una ocasión más romántica, pero cuando lo hace (en un barco), ella se niega, lo que hace que Sam la haga caminar por la tabla. . Más tarde, Diane dice que quiere casarse, pero Sam ahora se ha retractado de la propuesta.', 24, '1986-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 2, 'El cabo Cad', 'Diane sigue a Sam a Cape Cod en un esfuerzo por arruinar su fin de semana con otra mujer.', 24, '1986-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 3, 'Mi querido dinero', 'Cliff está extasiado cuando su madre decide casarse con un hombre rico hasta que el novio decide donarlo todo a la caridad.', 23, '1986-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 4, 'Psicología anormal', 'Diane intenta ayudar a Lilith, la psicóloga atraída por Frasier, a suavizar su apariencia y sorprender a Frasier durante su debate televisivo.', 23, '1986-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 5, 'La casa de los horrores', 'Cliff encuentra una casa antigua a un precio razonable para que la compre Carla y que resulta estar encantada.', 24, '1986-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 6, 'Bronceado y lavado', 'La pandilla insiste en participar en la nueva inversión comercial de Norm y luego se queja amargamente cuando parece un fracaso.', 23, '1986-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 7, 'El joven Dr. Weinstein', 'Picado por la actitud de Diane, Sam intenta impresionarla consiguiendo reservas en el restaurante más exclusivo de Boston.', 24, '1986-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 8, 'Caballeros de la cimitarra', 'Cliff insta a Norm, reacio a unirse a su logia, y Sam cree que Diane ha inventado un pretendiente para ponerlo celoso.', 24, '1986-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 9, 'Día de acción de gracias para solitarios', 'La pandilla se reúne en la casa de Carla para una cena de Acción de Gracias con pavo congelado y guisantes exagerados.', 24, '1986-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 10, 'Competición de poetas', 'Diane se obsesiona con localizar un poema que está segura que Sam plagió y publicó en una revista literaria que ha rechazado repetidamente su trabajo.', 23, '1986-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 11, 'El libro de Sam', 'Woody se adentra en el legendario libro negro de Sam para encontrar una cita con la que impresionar a su ex novia, que viene a Cheers para presentarle a su prometido.', 24, '1986-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 12, 'Danza, Diana, danza', 'El esfuerzo de Frasier por aligerar las duras críticas de un instructor de baile a los esfuerzos de Diane fracasa cuando ella decide hacer una audición para el Ballet de Boston.', 23, '1986-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 13, 'Chambers vs Malone', 'Sam le propone matrimonio a Diane nuevamente y termina acusado de agresión cuando ella lo rechaza nuevamente.', 24, '1987-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 14, 'El diamante de Sam', 'Sam se arrepiente de haber intentado comprarle a Diane un anillo de compromiso que es una imitación barata.', 24, '1987-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 15, 'Fascinación', 'Diane y Carla consuelan a Loretta, quien descubrió a Nick engañándola. Le aconsejan que se pare por sí misma y deje a Nick. Cuando Nick entra al bar para reclamarla, un caballeroso Sam la defiende. Nick toma eso como una señal de que Sam le ha robado a Loretta. Entonces Nick amenaza con robarle lo mismo a Sam, siendo esa Diane. Nick intenta tomar vino y cenar con Diane, luego Loretta, luego Carla y luego cualquiera de los tres que le darán la hora del día. Mientras tanto, Frasier, el experto en ajedrez, ha encontrado su rival en el simplón Woody.', 24, '1987-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 16, 'Rumores de un guardameta (1ª Parte)', 'Carla se enamora de Eddie, un portero de hockey; Mientras tanto, Diane es la presidenta del jurado en un juicio por intento de asesinato.', 24, '1987-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 17, 'Rumores de un guardameta (2ª Parte)', 'Carla y Eddie ahora están en una relación. Desde que Carla le lanzó el beso y Eddie dejó entrar ese gol barato, Eddie ha estado en una mala racha. Eddie y Carla, la pareja más supersticiosa de todos los tiempos, analizan la rutina de vida de Eddie desde que comenzó la depresión; el único cambio en la rutina es Carla en su vida.', 24, '1987-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 18, 'Despedida de soltero', 'Para la despedida de soltero que los chicos del bar le organizan a Sam, Woody le pregunta a Diane si ella sería la chica que saltaría del pastel. Aunque aborrece esos rituales sexuales masculinos, acepta aunque sólo sea para evitar que otra persona ''complace'' a Sam. En la fiesta, justo cuando Diane está lista para salir del pastel, Norm hace un comentario que hace que Sam vuelva a examinar en voz alta por primera vez esta boda y el hecho de que Diane ahora será la única mujer en su vida.', 24, '1987-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 19, 'Un perro muerde a Cliff', 'En su ruta postal, Cliff es mordido por un perro y decide demandar al propietario por 200.000 dólares. Madeline, la dueña del perro, termina siendo una mujer hermosa y voluptuosa, pero sincera al querer ayudar a Cliff a pesar de que tiene poco dinero. Cliff y Madeline comienzan a salir, y la pandilla en el bar piensa que es solo una estratagema de su parte para que Cliff no presente una demanda.', 23, '1987-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 20, 'Cena a las ocho', 'Frasier y Lilith invitan a Sam y Diane a cenar para celebrar su primera semana de convivencia. Pero las cosas empiezan a ir mal cuando Lilith descubre que Frasier y Diane estaban comprometidos y se encierra en el baño. Entonces Sam y Diane también tienen una discusión. Mientras tanto, Cliff acepta cuidar a los hijos de Carla.', 24, '1987-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 21, 'Simón dice', 'Diane acosa a un destacado consejero matrimonial británico para que los vea a ella y a Sam para una sesión prenupcial, y luego se niega a seguir su consejo.', 24, '1987-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 22, 'El padrino', 'La ahijada de Sam, Joyce Pantusso (sobrina del difunto entrenador), ha venido a Boston de visita. Como no quiere que ella se meta en problemas, Sam le pide a Woody que la ayude y le muestre los alrededores, ¡pero Woody y Joyce le tienen una sorpresa a Sam cuando se comprometan!', 23, '1987-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 23, 'El primer hurra de Norm', 'Norm explica su nuevo puesto en una importante firma de contadores públicos y queda atrapado en sus pequeñas mentiras piadosas cuando la pandilla decide sorprenderlo en el trabajo. Mientras tanto, Cliff encuentra un billete de 20 dólares y Woody ha perdido uno.', 23, '1987-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 24, 'Cheers, la película', 'La pandilla intenta tranquilizar a los nerviosos señor y señora Boyd en Indiana diciéndoles que Woody está bien y que tiene amigos maravillosos en Boston haciendo una película casera de un día normal en Cheers.', 24, '1987-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 25, 'Una casa no es un hogar', 'Diane está atormentada por los recuerdos de la pareja que vivió una vida larga y feliz juntos en la casa que ella y Sam compraron.', 24, '1987-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 26, 'Acepto, adiós', 'El Dr. Sumner Sloane regresa a Cheers el día de la boda de Diane y Sam para decirle que un editor está interesado en uno de los manuscritos de su clase si puede ponerse a trabajar inmediatamente en las reescrituras.', 24, '1987-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 6, 'Temporada 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 1, 'La vuelta de Sam', 'Sam regresa a Cheers seis meses después de venderlo a una gran corporación para dedicarse a una vida de ocio a bordo de un barco nuevo. Ahora el barco se ha hundido y está buscando trabajo.', 24, '1987-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 2, 'Yo en los deportes', 'Sam intenta eludir sus deberes en el bar para poder sustituir a un amigo como locutor deportivo.', 24, '1987-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 3, 'La pequeña Carla, feliz al fin (1ª Parte)', 'Carla y Eddie planean casarse si logran superar la superstición, la madre de Eddie, los hijos de Carla y los nervios de Rebecca mientras espera que su jefe aparezca en el bar.', 23, '1987-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 4, 'La pequeña Carla, feliz al fin (2ª Parte)', 'Carla y Eddie planean casarse si logran superar la superstición, la madre de Eddie, los hijos de Carla y los nervios de Rebecca mientras espera que su jefe aparezca en el bar.', 23, '1987-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 5, 'El motín de Crane', 'La pandilla intenta convencer a Frasier de que Rebecca lo desea después de que él se pelea con Lilith y Rebecca reemplaza la foto de Sam con una de Robert Urich.', 24, '1987-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 6, 'Pinta tu oficina', 'Norm llega a conocer mejor a Rebecca cuando pinta su oficina como una forma de pagar la cuenta del bar.', 24, '1987-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 7, 'El último cartero enfadado', 'Cliff se opone a vender la casa familiar para poder construir una tienda de conveniencia allí, pero su madre está totalmente de acuerdo con la idea. Mientras tanto, la pandilla intenta averiguar sobre el apodo universitario de Rebecca: "Backseat Becky".', 24, '1987-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 8, 'La subasta', 'Sam y Woody están en puja en una subasta benéfica, pero no están muy entusiasmados con sus nuevos ''dueños''.', 24, '1987-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 9, 'Woody en el teatro', 'Woody conoce a una anciana mientras se maquilla para el papel de Mark Twain y comienza a salir con ella.', 24, '1987-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 10, 'Un beso es siempre un beso', 'Rebecca le pide a Sam, ansioso, que la acompañe a una función de la empresa para corregir una impresión falsa que tiene su jefe.', 24, '1987-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 11, 'My fair Clavin', 'Cliff ayuda a su amiga a mejorar su apariencia y luego se arrepiente cuando todo tipo de personas comienzan a coquetear con ella, incluido Sam.', 24, '1987-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 12, 'Navidad en Cheers', 'La víspera de Navidad es deprimente en Cheers cuando Sam se apresura a buscarle un regalo a Rebecca, Rebecca hace que todos trabajen hasta tarde y los amigos de Norm de Santa Claus se reúnen para celebrar el final de la temporada.', 24, '1987-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 13, 'Woody encuentra su vocación', 'Woody intenta convencer a sus amigos de que consiguió un pequeño papel en Spenser: For Hire y Cliff y Norm se pelean por una broma que involucra a un chimpancé.', 24, '1988-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 14, 'Y Dios creó a la mujer', 'Woody se hace responsable de un jarrón que Rebecca rompió en una fiesta de la empresa y termina siendo amigo del gran jefe.', 24, '1988-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 15, 'La hija del jefe', 'Annie Tortelli reemplaza a Carla en Cheers y el Sr. Drake hace que Rebecca se vuelva verde al contratar personalmente a una hermosa joven para trabajar en Cheers.', 23, '1988-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 16, 'Barco de locos', 'Rebecca cree que finalmente tiene una oportunidad con Evan Drake cuando él los invita a ella y a Sam a pasar un fin de semana a bordo de su yate.', 24, '1988-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 17, 'A todas las chicas que he amado antes', 'La despedida de soltero de Frasier resulta deprimente y sombría, mientras que la ducha de Lilith amenaza con estallar en llamas.', 24, '1988-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 18, 'Deja dormir al señor Drake', 'Rebecca contempla el dormitorio de Evan Drake mientras Norm lo vuelve a pintar, pero la atrapa cuando el hombre regresa inesperadamente.', 24, '1988-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 19, 'Aeropuerto V', 'Carla intenta superar su miedo a volar con la ayuda de Frasier y Rebecca espera tensa la visita de un crítico de restaurantes.', 24, '1988-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 20, 'El traje de Sam', 'Rebecca se siente herida y celosa cuando Sam es ascendido a la sede corporativa hasta que descubre por qué lo ascendieron.', 24, '1988-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 21, 'Nuestro pan de cada día', 'Rebecca decide aceptar la sugerencia de Woody de rifar unas vacaciones en el Caribe para sacar al bar de la crisis.', 24, '1988-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 22, 'Fiesta de pijamas mortal', 'Lilith y Rebecca organizan una fiesta de pijamas para adolescentes para animar a Carla después de que se entera de que pronto será abuela.', 24, '1988-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 23, 'Guerra de bares', 'La pandilla de Cheers declara la guerra cuando el bar rival, Gary''s Old Town Tavern, roba el trofeo que celebra su única victoria deportiva en un torneo de bolos.', 23, '1988-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 24, 'El beso', 'Sam y Woody apuestan sobre quién puede ser el primero en darle un beso de tres segundos a Rebecca.', 24, '1988-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 25, 'La declaración de Rebecca', 'Rebecca, desesperada, hace todo lo posible por estar un momento a solas con Evan Drake mientras él se prepara para mudarse a Japón.', 23, '1988-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 7, 'Temporada 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 1, 'Cómo retroceder en los negocios', 'Rebecca todavía está dolida por la partida de Evan Drake a Japón. Así que, en lugar de los hombres, concentra sus energías en avanzar en su carrera: cree que Evan Drake se llevó a todos los jugadores clave de la compañía a Japón con él y, por lo tanto, todos aquellos que sabían que ella era un ''fracaso'' ahora se han ido, y comprando un mercedes.', 23, '1988-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 2, 'Juro por Dios', 'Sam le hace una promesa precipitada a Dios de que permanecerá célibe si alguien más es el padre del bebé de una vieja amiga.', 23, '1988-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 3, 'Ejecutivo dulce', 'Rebecca desanima a Sam diciéndole que de ahora en adelante solo saldrá con hombres que puedan avanzar en su carrera, y luego conoce a su nuevo jefe, más joven que la primavera.', 23, '1988-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 4, 'Una ruptura feliz', 'Sam va a México para abrir un nuevo bar para la empresa, robándole a Rebecca su ''prometido'' y su única defensa contra la propuesta de matrimonio de su bebé jefe.', 24, '1988-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 5, 'Labios de hielo', 'Carla tiene un ataque de celos cuando sospecha que Eddie está jugando con alguien del espectáculo sobre hielo.', 23, '1988-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 6, 'Norm, ¿es usted?', 'Norm intenta ocultar el hecho de que se ha convertido en decorador de interiores.', 24, '1988-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 7, 'Cómo ganar amigos y electrocutar a la gente', 'Cliff altera drásticamente su personalidad después de que nadie del bar viene a visitarlo durante su estancia en el hospital con apendicitis.', 24, '1988-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 8, 'Paracaidistas a la fuerza', 'La pandilla decide dedicarse al paracaidismo como diversión.', 24, '1988-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 9, 'Envía a Crane', 'Sam se siente atraído tanto por una antigua novia como por su hija mayor, mientras que Woody se ofrece como voluntario para ser el payaso en la fiesta de cumpleaños del hijo del jefe que Rebecca está planeando.', 24, '1989-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 10, 'Guerra de bares 2', 'Cheers tiene otra oportunidad de perder un concurso ante sus rivales de la ciudad en Gary''s Old Towne Tap; esta vez el concurso es por el ''Mejor Bloody Mary de Boston''.', 24, '1989-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 11, 'Aventuras vigilando una casa', 'Rebecca se ofrece a cuidar la casa de uno de los ejecutivos de la empresa y pide ayuda a Sam y Woody cuando el amado perro del hombre se escapa.', 24, '1989-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 12, 'Por favor, Sr. cartero', 'La lealtad de Cliff se pone a prueba cuando su nueva amada, una compañera empleada de correos, comete una infracción de las reglas en su nombre.', 24, '1989-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 13, 'El chico de oro', 'Woody decide robarse a Kelly, la chica de un rico snob, cuando el hombre lo humilla.', 24, '1989-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 14, 'No te tomo el pelo', 'Lilith y Frasier practican sus habilidades como padres con el precoz hijo de seis años de Carla.', 24, '1989-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 15, 'No pinte su pollo', 'Rebecca intenta impresionar a la sede corporativa utilizando sus habilidades de marketing para promover el negocio de pintura de Norm y Sam intenta mantenerse al día con una dulce joven apasionada por todo tipo de deportes.', 24, '1989-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 16, 'Un Crane en camino', 'Lilith convence a Frasier para que deje todo lo urbano y se mude con ella a una cabaña en la naturaleza.', 24, '1989-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 17, 'Piedras preciosas', 'Sam les presenta a todos al presidente del Estado Mayor Conjunto, un viejo admirador, pero Rebecca luego cree que el anciano le robó los aretes de diamantes.', 23, '1989-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 18, '¿Qué me pasa, doctora?', 'Sam en realidad finge un caso de impotencia para acercarse a un terapeuta que Lilith y Frasier le presentaron.', 24, '1989-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 19, 'El regalo de Woody', 'La rica amiga de Woody no aprecia del todo su económico pero sincero regalo de cumpleaños y Rebecca se transforma para mejorar sus perspectivas profesionales.', 24, '1989-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 20, 'Llámame irresponsable', 'Woody tiene fiebre por el juego y la tensión aumenta mientras Carla espera que Eddie la sorprenda en su segundo aniversario.', 24, '1989-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 21, 'Amor de hermana', 'Sam intenta reconciliar a Rebecca y su hermana.', 24, '1989-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 22, 'La visita', 'Rebecca acusa a una respetada autoridad en fidelidad conyugal de insinuarse con ella.', 24, '1989-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 8, 'Temporada 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 1, 'Un sueño imposible (1ª Parte)', 'Justo cuando Rebecca teme por su cordura debido a los sueños eróticos que ha estado teniendo sobre Sam, el multimillonario Robin Colcord la sorprende.', 23, '1989-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 2, 'Un sueño imposible (2ª Parte)', 'Justo cuando Rebecca teme por su cordura debido a los sueños eróticos que ha estado teniendo sobre Sam, el multimillonario Robin Colcord la sorprende.', 23, '1989-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 3, 'Ha nacido un bar', 'Rebecca se prepara para pasar su primera noche con Robin Colcord mientras Sam da el primer paso para volver a ser dueño del bar.', 23, '1989-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 4, 'Cómo casarse con un cartero', 'La joven que Cliff entregó por robar un vehículo de la oficina de correos regresa de Canadá con una oferta que literalmente deja ciego a Cliff.', 23, '1989-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 5, 'Las dos caras de Norm', 'Norm inventa un estricto y cascarrabias como socio para mandar a su tranquilo equipo de pintura, mientras Sam se vuelve loco de preocupación después de vender su precioso Corvette.', 23, '1989-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 6, 'La cigüeña trae un Crane', 'Lilith arruina la elaboradamente planeada celebración del centenario de Cheers al ponerse de parto.', 23, '1989-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 7, 'La muerte tarda un día de fiesta en el hielo', 'Carla se entera de que Eddie llevaba una vida secreta cuando una segunda viuda aparece en su funeral.', 24, '1989-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 8, 'Sólo para hombres de verdad', 'Frasier y los chicos se avergüenzan de los planes de asistir a la circuncisión de su hijo, mientras Rebecca lucha por organizar una interesante fiesta de jubilación para un empleado corporativo muy aburrido.', 22, '1989-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 9, 'Dos chicas para Woody', 'Woody tiene problemas con las escenas de amor para su primer papel protagónico y los chicos tienen una competencia para dejarse crecer la barba.', 23, '1989-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 10, 'El arte de robar', 'Rebecca y Sam quedan atrapados durante la noche en el lujoso apartamento de seguridad de Robin Colcord mientras la pandilla pasa el tiempo jugando Monopoly.', 22, '1989-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 11, 'Atracción débil', 'Norm despide a su secretaria, quien lo ve como una prueba de que se siente tremendamente atraído por ella y Rebecca se obsesiona con una sorpresa escondida en el escritorio que Robin le dio.', 22, '1989-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 12, 'Sam a la vista', 'Robin les presta a Sam y a la pandilla su yate de regata en una regata, pero la variada tripulación descubre una bomba en el refrigerador, justo al lado de la cerveza.', 22, '1989-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 13, 'Sammy y la profesora', 'Carla se enfrenta a una auditoría mientras el mentor de Rebecca, su profesor de la escuela de negocios, hace una inversión en Sam.', 23, '1990-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 14, '¿Qué es Cliff Clavin?', 'Jeopardy hace acto de presencia en Boston y Cliff aparece en el programa. ¡El peligro! La ronda tenía las 6 categorías en las que Cliff se especializa, como celebridades o el Servicio Postal de EE. UU. Pero cuando se acerca Final Jeopardy, pierde todo su dinero con una respuesta estúpida: ''¿Quiénes son tres personas que nunca han visitado mi cocina?'' y luego se deprime. Mientras tanto, alguien robó el pequeño libro negro de Sam y empezó a llamar a todas las chicas que estaban en él.', 24, '1990-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 15, '¡Finalmente! (1ª Parte)', 'Esta noche podría ser la noche en que Rebecca y Robin finalmente se reúnan, a pesar de la presencia de Sam.', 23, '1990-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 16, '¡Finalmente! (2ª Parte)', 'Las consecuencias de su reunión no son todo lo que esperaba, cuando Rebecca encuentra a Robin con otra mujer.', 23, '1990-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 17, 'Woody lo hará o no lo hará', 'Un toro mecánico vence a Cliff mientras Woody intenta lidiar con las insinuaciones románticas de la madre de su amiga.', 23, '1990-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 18, 'Daños severos de Crane', 'Lilith va a un programa de entrevistas para promocionar su nuevo libro sobre los hombres que son malos para las mujeres y lleva consigo a su principal ejemplo: Sam.', 23, '1990-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 19, 'Un poco de diversión con Sam y Robby', 'Rebecca sueña con un día perfectamente romántico con Robin. Robin, por otro lado, ha desafiado a Sam a una serie de desafíos adolescentes.', 23, '1990-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 20, 'Los repartos de Carla', 'Carla y Gloria, la otra viuda de Eddie, se convierten en mejores amigas, pero la amistad se ve amenazada cuando Carla se entera de que el doblez dejó 50.000 dólares en seguro y Woody se preocupa por una escena de desnudo cuando lo eligen para una reposición de Hair.', 23, '1990-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 21, 'Guerra de bares 3, el regreso de Tecumseh', 'A pesar de la tregua negociada por Rebecca, la pandilla decide calentar la guerra fría contra la taberna Olde Towne de Gary cuando notan que falta la estatua de Tecumseh el indio.', 22, '1990-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 22, 'Amante Woody', 'Woody se lamenta por el hecho de que Kelly irá a Europa para asistir a la escuela y Norm sufre por ser el conductor designado para esa noche.', 23, '1990-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 23, 'El fantasma y la señora Lebec', 'Carla se siente obligada a llamar a un exorcista cuando el fantasma de Eddie aparece en el bar y Rebecca se queja ante una estación de televisión sobre un sistema de depilación defectuoso.', 23, '1990-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 24, 'El señor Otis se arrepiente', 'Sam pone celosa a Rebecca de muchas maneras extrañas al decirle que se anotó con la otra amiga de Robin, y Woody se queda estupefacto cuando una chica responde a su anuncio de un compañero de cuarto.', 23, '1990-04-19');
