INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 8), 26, 'Llora más fuerte (2ª Parte)', 'Rebecca y Sam tienen emociones encontradas al enfrentar el hecho de que Robin Colcord, después de proponerle matrimonio a Rebecca, es arrestado por uso de información privilegiada basándose en información proporcionada por el antiguo y futuro propietario de Cheers.', 23, '1990-05-03');
