INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 9), 1, 'El amor está francamente bien', 'Después de su encuentro íntimo, Rebecca está decidida a negar que esto haya sucedido alguna vez, a la pandilla en el bar, a Robin y a ella misma.', 23, '1990-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 9), 2, 'Viva Cheers manque pierda', 'Sam intenta vencer a Gary en su propio juego en un partido de baloncesto reclutando a la estrella de los Boston Celtics, Kevin McHale, como camarero sustituto en Cheers.', 23, '1990-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 9), 3, 'El regreso de Rebeca', 'Sam contrata a un nuevo gerente de bar que parece gustar a todos y luego descubre lo bajo que ha caído Rebecca en su búsqueda de un nuevo empleo.', 22, '1990-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 9), 4, 'Donde nadie conoce tu nombre', 'Rebecca está secretamente muy molesta cuando uno de los amantes anteriores de Robin hace público que es su aventura actual.', 23, '1990-10-11');
