INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 9, 'Atracción fatal', 'Sam se enoja cuando Carla se desvía de la venganza hacia un romance con su eterno enemigo John Hill.', 22, '1991-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 10, 'Un buen vino francés', 'Woody quiere proponerle matrimonio a Kelly, pero Henri y su visa vencida tienen prioridad.', 22, '1991-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 11, 'Yo estoy bien, tú eres el que no funciona', 'Frasier tiene que afrontar la redacción de un testamento mientras Sam se prepara para recibir malas noticias del médico especialista en fertilidad de Rebecca.', 22, '1991-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 12, 'Id a hacerlo', 'Sam y Rebecca dejaron volar su imaginación durante un fin de semana haciendo bebés e idearon diferentes versiones de su futura progenie.', 22, '1991-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 13, 'No dispare, sólo soy el psiquiatra', 'Cliff y Norm ayudan al grupo de autoayuda de baja autoestima de Frasier a ayudarse a sí mismos y Woody le corta el cabello a Sam.', 22, '1992-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 14, 'No hay descanso para Woody', 'El trabajo extracurricular de Woody como sepulturero puede pagar el anillo de compromiso de Kelly, pero también pone en peligro su primer encuentro con su abuela.', 22, '1992-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 15, 'Mi hijo, el padre', 'Sam encuentra una manera de vengarse de John Hill. Uno de los hijos de Carla decide hacerse sacerdote.', 22, '1992-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 16, 'Una abraza, la otra no', 'Una actuación en Boston de la cantante infantil Nanny Gee para el cumpleaños de Frederick arroja luz sobre el pasado de Frasier mientras Lilith y los barflies descubren que Nanny es la primera esposa de Frasier. Frasier se había olvidado de mencionarle este hecho a Lilith y cuando Nanny llega a Cheers, ¡ella y Lilith pronto se pelean!', 22, '1992-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 17, 'Rebeca rechazada y Cliff suspendido', 'La prima de Woody se enamora de Rebecca y Cliff está muy descontento con los nuevos uniformes postales.', 22, '1992-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 18, 'Licencia para matar', 'Rebecca insiste en que puede manejar la barra mientras el resto de la pandilla juega al póquer, luego se entera de que ha permitido que su licencia de venta de bebidas alcohólicas caduque.', 22, '1992-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 19, 'Hombre rico, hombre Woody', 'La pandilla intenta traer a Woody de vuelta a la tierra después de unas vacaciones en Londres con Kelly y su dinero.', 22, '1992-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 20, 'Hay amores que matan', 'Frasier quiere que Lilith se enfrente a su autoritaria madre y Rebecca quiere que Sam obligue a Norm a pagar la cuenta del bar.', 22, '1992-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 21, 'Sácame fuera del partido', 'Sam considera regresar al béisbol, pero cuando va a jugar algunos juegos descubre que la mayoría de los jugadores son mucho más jóvenes e inmaduros que él. Están actuando como él solía hacerlo, y Sam cree que ya no disfruta actuar así. Mientras tanto, de vuelta en Boston, Frasier pierde la rata de laboratorio favorita de Lilith e intenta conseguir una idéntica antes de que ella regrese.', 22, '1992-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 22, 'El no amante de Rebeca', 'Rebecca espera ver a su novio de la secundaria, sin darse cuenta de los cambios en su vida, y Sam inicia un grupo de apoyo para propietarios de Corvettes robados.', 22, '1992-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 23, 'Guerra de bares VI, esta vez va en serio', 'El nuevo propietario de Gary''s Olde Towne Tavern carece de sentido del humor y responde mal a la última broma de Cheers.', 22, '1992-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 24, 'Con ustedes... ¡Cliff!', 'Norm le cuenta a Cliff una pequeña mentira piadosa acerca de que Carson usó el material de Cliff en The Tonight Show, luego se arrepiente cuando Cliff consigue dos boletos para Burbank. Mientras tanto, Sam y Woody instalan una antena parabólica en Cheers.', 22, '1992-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 10), 25, 'Una boda a la antigua', 'La boda de Woody y Kelly enfrenta algunos obstáculos divertidos, antes y durante la ceremonia, incluido el coqueteo de Sam con un invitado alemán que resulta estar casado, la muerte del sacerdote y el tío Roger de Kelly que tiene que realizar la ceremonia, pero solo si está borracho, Rebecca. tener que congelar el pastel después de insultar al personal de la cocina, y Lilith tener que cantarles a los invitados para evitar que ellos, y Woody y Kelly, descubran los desastres que ocurren detrás de escena.', 42, '1992-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 11, 'Temporada 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 1, 'La cerillera', 'El hecho de que Rebecca fume la mete en un gran problema cuando accidentalmente provoca un incendio en el bar y lo atribuye a un cableado defectuoso.', 22, '1992-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 2, 'La reapertura', 'Carla se ve obligada a arreglar su actuación y comportarse bien cuando se ve obligada a buscar otro trabajo mientras se reconstruye Cheers. La fe de Woody en Kelly se tambalea cuando se entera de que tienen diferencias religiosas.', 22, '1992-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 3, 'El rey de las cervezas', 'Una máquina tragamonedas es enviada accidentalmente al bar. Todo el mundo está enganchado a jugar, lo que para ellos no es malo, ya que la máquina les paga a todos, excepto a Rebecca. Ella ve su mala racha en la máquina como una metáfora de su vida. Sintiendo lástima por ella, Sam tiene la máquina preparada para pagarle a Rebecca y hacerla sentir mejor. Ese acto no sale como estaba planeado. La suerte de Norm parece estar mejorando. Una temporada en un panel de encuestas de cata de cerveza se convierte en un puesto remunerado en la cervecería como probador de sabor de calidad. Norm está en el séptimo cielo y ni siquiera siente la necesidad de que le paguen por ese trabajo.', 22, '1992-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 4, 'Los seis magníficos', 'Sam descubre a Rebecca fumando en la oficina, un no-no considerando que así fue como se quemó el bar. Sam cree que Rebecca necesita ayuda profesional y encuentra el programa para dejar de fumar más estricto para ella. El médico que deja de fumar, el Dr. Kluger, y Rebecca, tienen una guerra de voluntades. Es posible que el Dr. Kluger haya encontrado su rival. Mientras tanto, Sam contrata a Henrí temporalmente como bartender mientras Woody está de luna de miel. En su primer turno, el mujeriego Henrí le apuesta a Sam a que puede conseguir más números de teléfono de mujeres que Sam antes de la medianoche. Aunque inicialmente se muestra reacio a participar en la apuesta a pesar de la presión de la pandilla, Sam finalmente acepta la apuesta basándose en la batalla patriótica entre Estados Unidos y Francia.', 22, '1992-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 5, 'No me abandones, cartero mío', 'Sam descubre a Rebecca fumando en la oficina, un no-no considerando que así fue como se quemó el bar. Sam cree que Rebecca necesita ayuda profesional y encuentra el programa para dejar de fumar más estricto para ella. El médico que deja de fumar, el Dr. Kluger, y Rebecca, tienen una guerra de voluntades. Es posible que el Dr. Kluger haya encontrado su rival. Mientras tanto, Sam contrata a Henrí temporalmente como bartender mientras Woody está de luna de miel. En su primer turno, el mujeriego Henrí le apuesta a Sam a que puede conseguir más números de teléfono de mujeres que Sam antes de la medianoche. Aunque inicialmente se muestra reacio a participar en la apuesta a pesar de la presión de la pandilla, Sam finalmente acepta la apuesta basándose en la batalla patriótica entre Estados Unidos y Francia. Tanto Sam como Henrí hacen todo lo posible y recurren a cualquier táctica que funcione para conseguir números.', 22, '1992-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 6, 'Enseñando con el enemigo', 'Rebecca ve a Lilith con otro hombre y no sabe si decírselo a Frasier. Más tarde, Lilith le confiesa a Frasier que lo engañó... una vez. Frasier está devastado, y después de que él y Lilith hablan de ello, Frasier le pide a Lilith que le diga a su amante que la aventura terminó. Lilith va a verlo y luego regresa diciendo que quiere dejar Frasier. Mientras tanto, Sam contrata a un portero llamado Tiny, pero no se atreve a despedir a Tiny porque nadie quiere acercarse a él.', 22, '1992-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 7, 'La chica en la burbuja de plástico', 'Lilith le informa a Frasier que quiere pasar un año alejada de él, encerrada en una biosfera con su amante. Frasier reacciona a esto como cualquier psiquiatra capacitado: se sube a la cornisa de Melville''s y amenaza con saltar si Lilith lo deja. Lilith y Sam logran disuadirlo, pero Lilith insiste en que su matrimonio ha terminado. Una vez que Lilith se fue, los amigos de Frasier se unieron para apoyarlo.', 22, '1992-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 8, 'Un suegro con malas artes', 'El padre de Kelly está convencido de que Woody tiene un chantaje en mente cuando Woody ve al Sr. Gaines engañando a su esposa. Rebecca planea celebrar una cena de Acción de Gracias en el bar.', 22, '1992-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 9, 'Sentimientos... Whoa, Whoa, Whoa', 'Cliff está convencido de que su nuevo vecino es Adolf Hitler. Si no fuera porque mamá lo defendió, Cliff sería desalojado del edificio por acoso. Pero Cliff todavía no está convencido de la verdadera identidad de su vecino. Mientras tanto, Carla y John Allen Hill continúan su relación de amor y odio. Sin embargo, ha llegado a un nuevo nivel, a una etapa de amor-odio-infarto. Hill sufrió un infarto mientras hacían el amor. Aparentemente indiferente al ataque cardíaco ya que Hill es solo un jugueteo en el heno, Carla finalmente rompe a llorar porque ''su novio'' sufrió un ataque cardíaco. Ella sospecha que la razón por la que tuvo un ataque cardíaco es que ella le soltó las palabras ''Te amo'' a Hill.', 22, '1992-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 10, 'La niña de papá de mediana edad', 'Woody y Kelly discuten una vez más sobre la diferencia en su estatus monetario. Kelly quiere vivir en una casa comprada por su padre. Woody, que no quiere dinero de Gaines, quiere que vivan en su antiguo apartamento, ya que eso es todo lo que puede pagar. Llegan a acuerdos, lo que les demuestra que una de las partes podría tener más razón en su punto de vista que la otra. Mientras tanto, el padre de Rebecca, el capitán de la Armada Franklin E. Howe, viene a Boston de visita. Un hombre y padre duro como las uñas, exige que Rebecca, que ha arruinado su vida en Boston, regrese a San Diego a su antigua habitación en su casa. Aparentemente, él la ha controlado toda su vida, incluso proporcionándole una asignación. Espera que Rebecca se oponga y exija vivir su vida en Boston como mejor le parezca. El capitán Howe tiene un motivo oculto para su visita a Boston que Rebecca desconoce. Si supiera el verdadero motivo de su padre, cambiaría toda la naturaleza de su desacuerdo.', 22, '1992-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 11, 'Ámame, ama mi coche', 'Los padres de Woody reciben un regalo para Kelly y Woody: un pequeño cerdo llamado Snuffles. Pet es un nombre algo inapropiado ya que los Boyd, de origen agrícola, ven a Snuffles como una cena de Navidad. Rebecca tiene una conexión inmediata con Snuffles como animal. Quiere comprar Snuffles después de enterarse de su destino final. Cuando Woody no quiere vender, Rebecca deja libre a Snuffles en el campo. Cuando Rebecca escucha quién termina encontrando a Snuffles, ve la historia como un milagro navideño, hasta... Mientras tanto, Sam comienza a salir con Susan Metheny, la viuda de Kirby, el hombre que compró el Corvette de Sam. Sam solo lo hace porque quiere recuperar su Corvette a un precio reducido. Susan, maestra de jardín de infantes, es una mujer agradable, dulce, inocente y tímida que es vulnerable en el mejor de los casos, y mucho menos en este momento de duelo de su vida.', 22, '1992-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 12, 'Cena dominical', 'Frasier decide empezar a salir con otras mujeres ahora que Lilith los ha dejado a él y a Frederick, y tiene una cita con su secretaria, Shauna. Llega a la casa de Shauna solo para descubrir que Shauna solo lo está usando para molestar a sus padres, ya que no le permiten ver a su novio, quien luego aparece sin previo aviso. Mientras tanto, Cheers organiza una reunión familiar y Cliff y Norm la están grabando en vídeo, pero luego descubren que la cámara nunca estuvo encendida y tienen que intentar recrear el vídeo sin que nadie se dé cuenta.', 22, '1993-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 13, 'La gran auditoría de Norm', 'La pandilla decide ver un viejo partido de los Red Sox en un canal de deportes clásico, un juego en el que jugaba Sam. Como este juego tuvo lugar durante uno de sus años de borrachera, Sam no está seguro de si jugó bien o hizo el ridículo en el juego. Como descubre que lanzó tres entradas en el juego, supone que jugó bien. Después de que Sam le da tanta importancia a ver el partido, Carla le recuerda que ese partido no fue uno de sus mejores momentos. Sam hace todo lo posible para evitar que la pandilla lo vea. Mientras tanto, Norm está siendo auditada. La auditora es Dot Carroll, una chica dura, aterradora, sensata, fumadora empedernida y con voz ronca. Norm, el ex contable, sabe que puede evadir la auditoría incluso sin recibos legítimos, pero cuando sus trucos no funcionan, recurre a una táctica sugerida por Carla: coquetear.', 22, '1993-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 14, 'Este bar está loco loco loco', 'Robin regresa a Cheers, indigente. Ha renunciado a sus costumbres codiciosas anteriores, ha regalado los 6 millones de dólares que había escondido en el cajón del escritorio de Rebecca y ha decidido vivir una vida de simple pobreza. Pero es cierto que todavía siente algo por Rebecca. Rebecca todavía siente algo por Robin, o al menos por los 6 millones de dólares que cree que tiene. Ella piensa que él sólo la está poniendo a prueba y que todavía es rico. Mientras tanto, Robin insinuó a la pandilla de manera indirecta que había escondido otro cinturón con dinero lleno de $ 6 millones en algún lugar del bar. Sam, Carla, Frasier, Norm y Cliff destrozan la barra, investigan a Robin y se enfrentan entre sí tratando de encontrar el cinturón del dinero. Luego piensan que fue quemado en el fuego. Pero cuando descubren que el capitán de bomberos Dobbins que estaba de servicio el día del incendio ahora está retirado con una suma considerable de dinero, suponen que robó el dinero.', 22, '1993-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 15, 'Odio y matrimonio', 'Serafina, de dieciocho años, hija de Carla, anuncia que está embarazada y quiere casarse con el padre, un policía retirado que vive de la discapacidad al que ama. Después de discutir el tema, Carla le da a Serafina su bendición y su apoyo económico para la boda. Con su conexión con Hill, Carla logra organizar la ceremonia en Melville''s (teme la mala historia del karma nupcial en Cheers) y la recepción en Cheers.', 22, '1993-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 16, '¿Está el doctor en casa?', 'Frasier se molesta cuando escucha que Lilith ahora quiere oficialmente el divorcio. El personal de Cheers decide celebrar una fiesta de ''divorcio feliz'' para animarlo, y en la fiesta, mientras Woody bebe demasiado y se vuelve un borracho malo, Frasier se emborracha. Luego, Rebecca lo lleva a casa, pero terminan juntos en la cama. Sin embargo, primero la pandilla aparece para comprobar que Frasier está bien - y para ver ''Los 3 Chiflados'' - pero justo cuando se van, quién debería aparecer sino Lilith, que ha escapado de la cápsula ecológica...', 22, '1993-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 17, 'La gerente del bar, el psiquiatra, su esposa y el amante de ella', 'Después de regresar a Boston y descubrir a Frasier en la cama con Rebecca, Lilith llega a Cheers para buscar el consejo de Sam. Frasier la persigue y Rebecca también aparece para explicarle. Frasier dice que no puede recuperar a Lilith después de lo que hizo, justo cuando su amante, el Dr. Pascal, aparece y toma a la pandilla como rehenes a menos que Lilith regrese con él. Cuando Paul y John Allen Hill aparecen y también son tomados como rehenes, Lilith tiene que persuadir a Pascal para que los deje ir a todos y que ella no quiere regresar. Además, ¿se reconciliará con Frasier?', 22, '1993-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 18, 'La última película', 'Cliff y Norm lamentan el cierre del autocine Twi-Lite y los recuerdos asociados de tiempos más simples. En el clásico convertible de Ma Calvin, Cliff, Norm, Woody y el novato Frasier, que termina siendo el chico del baúl, se dirigen a ver una triple función de Godzilla (1954) en la última noche del teatro. El cuarteto tiene una velada mixta en el teatro, que incluye soportar las reglas de etiqueta en el automóvil de Cliff y Ma y varios enfrentamientos con un vecino enojado. Pero es el convertible de mamá el que se lleva la peor parte de las batallas de la noche. Mientras los cuatro están en el autocine, Gus O''Malley, el anterior propietario de Cheers, pasa por el bar. Sam le ofrece a Gus la oportunidad de revivir viejos tiempos no solo atendiendo el bar, sino también administrándolo durante la noche. Gus recurre a sus viejas tácticas de gritos e intimidación para que el personal se ponga a trabajar.', 22, '1993-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 19, 'Guerra de bares VII, la víctima desnuda', 'Es la batalla anual de ventas del Día de San Patricio entre Cheers y Gary''s Olde Towne Tavern. Cheers no solo pierde la batalla de la maldición con un Woody desprevenido que se lleva la peor parte de la batalla, Cheers también pierde la apuesta de ventas. Sam finalmente ha tenido todo lo que puede soportar, no solo con la derrota una vez más ante Gary, sino también realizando la tarea más humillante que él y los muchachos han tenido que soportar debido a la pérdida. Sam amenaza a Gary y decide sacar una de las armas más grandes que conoce: Harry the Hat. Sam le pide a Harry que diseñe y ejecute el plan definitivo para vencer a Gary. Harry se niega. A pesar de la afirmación de Carla de tomar el asunto en sus propias manos, Sam finalmente se rinde permanentemente ante Gary. Cuando Sam va a casa de Gary para ondear la última bandera blanca, es testigo horrorizado de lo que cree que es el plan maestro de Carla.', 22, '1993-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 20, 'Mira antes de dormir', 'Es la batalla anual de ventas del Día de San Patricio entre Cheers y Gary''s Olde Towne Tavern. Cheers no solo pierde la batalla de la maldición con un Woody desprevenido que se lleva la peor parte de la batalla, Cheers también pierde la apuesta de ventas. Sam finalmente ha tenido todo lo que puede soportar, no solo con la derrota una vez más ante Gary, sino también realizando la tarea más humillante que él y los muchachos han tenido que soportar debido a la pérdida. Sam amenaza a Gary y decide sacar una de las armas más grandes que conoce: Harry the Hat. Sam le pide a Harry que diseñe y ejecute el plan definitivo para vencer a Gary. Harry se niega. A pesar de la afirmación de Carla de tomar el asunto en sus propias manos, Sam finalmente se rinde permanentemente ante Gary. Cuando Sam va a casa de Gary para ondear la última bandera blanca, es testigo horrorizado de lo que cree que es el plan maestro de Carla.', 22, '1993-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 21, 'Woody gana las elecciones', 'Cuando el concejal Kevin Fogarty llega a Cheers en su campaña de reelección soltando un montón de tonterías políticas que, sin embargo, cortejan a la multitud, Frasier apuesta a la pandilla a que incluso puede incluir un mono entrenado en la boleta y obtener el 10% de los votos. Sin un mono entrenado a la vista, Frasier elige a Woody como buen sustituto. De hecho, Frasier obtiene suficientes firmas para incluir a Woody en la boleta electoral. Woody ayuda a su propia causa política cuando Holly Matheson, una reportera local que cubre el área del Ayuntamiento, confunde la charla agrícola de Woody con una analogía de los problemas de la política de la ciudad. En una encuesta inicial, Woody obtiene un 8% de apoyo popular, suficiente para que la pandilla reconozca la derrota ante Frasier.', 22, '1993-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 22, 'Ya estamos cerca del final', 'Debido a la victoria electoral de Woody, Sam necesita otro camarero, un trabajo que le da a Carla. Para celebrar, Carla prepara una tanda de una de sus potentes bebidas para los chicos. Al día siguiente, todo el mundo tiene resaca. Lo que es peor, Carla, que bebió y se emborrachó ella misma, tiene la sospecha furtiva de que llevó a alguien a casa y se acostó con él, ya que cree que esa persona es uno de los clientes habituales de Cheers. Ella confía solo en Sam, y después de que él le dice que no fue él, ella entra en pánico y ambos reflexionan sobre quién podría haber sido, y su peor pesadilla es Cliff. Cuando su compañero de cama finalmente se revela, Carla y Sam tienen que decidir cuál es la mejor manera de manejar la información. Otras dos revelaciones salen a la luz después de la borrachera. Y Sam le confiesa su propia revelación a Carla para hacerla sentir mejor acerca de su propia revelación.', 22, '1993-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 23, 'Rebeca Gaines, Rebeca pierde', 'Después de que Woody, Kelly y su padre Lloyd llegan a Cheers hablando de música clásica (habían asistido a una sinfónica), Rebecca se une a la conversación e impresiona a Lloyd. Él la invita a una función de sociedad. Rebecca cree que es una cita y está encantada, pero se lleva una sorpresa cuando llega. Mientras tanto, Cliff ha internado a Esther Clavin en una casa de retiro, pero mientras Cliff se siente culpable, los demás piensan que ha asesinado a su madre.', 42, '1993-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 24, 'Él no lo puede evitar', 'Don Sentry entra al bar y se adentra en la vida de Rebecca. Es el técnico llamado para arreglar el grifo del bar. Aunque Don no es el tipo habitual de Rebecca, Frasier la convence para que se arriesgue cuando le dice que debería buscar a alguien como Don. Rápidamente, ella cae perdidamente, pero Sam cree que se está conformando con el segundo lugar. Quiere que Rebecca sea su alternativa si en un par de años no encuentra a la ''Sra. Malone''. Rebecca responde que él es un Lotario envejecido que ya pasó su mejor momento. Frasier le sugiere a Sam, quien está herido por los comentarios de Rebecca, que tal vez haya algo de verdad en la afirmación de Rebecca sobre él y que se beneficiaría de una terapia de grupo para los compulsivos sexuales. Sam va a la reunión y, después de un comienzo difícil, admite que tal vez ya no esté contento con su vida.', 22, '1993-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 11), 25, 'Una más para el camino', 'Mientras ven los premios National Cable Ace Awards, la pandilla ve a la ex camarera Diane Chambers ganando el premio al mejor guión en una miniserie. Esto lleva a Sam a llamar a Diane para felicitarla y descubrir que está casada y tiene hijos. Sam le dice a Diane que él también tiene esposa e hijos, e invita a Diane y a su esposo a visitarlos.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 1, 'Temporada 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 1, 'Piloto', 'Un laboratorio subterráneo es destruido por una misteriosa explosión. MacGyver es enviado para rescatar a los científicos atrapados y detener una fuga química letal.', 49, '1985-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 2, 'El triángulo dorado', 'MacGyver recupera unos documentos robados y huye en un coche. Después, le confunden con un narcotraficante cuando intenta recuperar un frasco lleno de una sustancia química mortal.', 48, '1985-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 3, 'El ladrón de Budapest', 'En Budapest, un gitano roba un microfilme que supuestamente estaba destinado a MacGyver.', 48, '1985-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 4, 'La persecución', 'MacGyver se enfrenta a un ejercito entero, cuando ayuda a un reportero americano a escapar cruzando la frontera de una dictadura sudamericana.', 49, '1985-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 5, 'El robo', 'MacGyver debe recuperar de la cámara de seguridad de un casino, unos diamantes destinados a una organización de caridad.', 45, '1985-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 6, 'El mundo de Trumbo', 'MacGyver rescata a una prisionera en los Pirineos y huye con ella en una balsa. Después, ayuda a defender una plantación de un ejército de hormigas que están destruyendo la selva de Brasil.', 45, '1985-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 7, 'Objetivo final', 'MacGyver es retenido como rehén es una pista de aterrizaje que es tomada por unos hombres que han robado un coche armado.', 48, '1985-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 8, 'Fuego infernal', 'MacGyver ayuda a un hombre a extinguir el fuego de un pozo de petróleo.', 45, '1985-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 9, 'El hijo prodigo', 'MacGyver debe ayudar al testigo de un caso federal a visitar a su madre enferma sin que su hermano, que pertenece a la mafia, lo descubra.', 45, '1985-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 10, 'Objetivo MacGyver', 'MacGyver rescata a la esposa de un general, retenida en una casa de la playa, y detiene a sus secuestradores. Más tarde, cuando visita a su abuelo, es perseguido por un asesino a sueldo.', 45, '1985-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 11, 'Pesadillas', 'MacGyver logra escapar de unos agentes enemigos que le han inyectado un alucinógeno, mortal en seis horas.', 45, '1986-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 12, 'Muerte súbita', 'Haciéndose pasar por un cadáver, MacGyver escapa de Berlín. Más tarde, es atrapado en una mansión gracias a una trampa electrónica.', 45, '1986-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 13, 'El fin de la llama', 'Un viejo amigo de MacGyver descubre pruebas de unos robos de uranio en una planta de tratamiento nuclear.', 45, '1986-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 14, 'Cuenta regresiva', 'MacGyver y un viejo compinche del ejército tienen las horas contadas para desactivar dos sofisticadas bombas que están a bordo de un barco de crucero.', 47, '1986-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 15, 'El enemigo dentro', 'MacGyver debe proteger a un desertor que puede identificar al asesino de tres agentes.', 45, '1986-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 16, 'Cada vez que ella sonríe', 'La estadounidense Penny Parker, que quiere escapar de su oficial de seguridad, pone en peligro la misión de MacGyver en Bulgaria para sacar un microfilm.', 45, '1986-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 17, 'Ser un hombre', 'En Afganistán, herido y expulsado por los soviets, una mujer afgana y su hijo dan refugio a Mac.', 45, '1986-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 18, 'El patito feo', 'Los estraperlistas buscan a un joven genio que es la única persona capaz de fijar el sistema de teledirección de un misil.', 45, '1986-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 19, 'Muerte lenta', 'MacGyver y un encargado de un tren de pasajeros son tomados como rehenes por un cacique tribal que busca a los responsables de la muerte de su hijo.', 45, '1986-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 20, 'El escape', 'MacGyver consigue que le envíen a una cárcel norteafricana para ayudar liberar a un misionero estadoundense.', 45, '1986-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 21, 'Prisionero de conciencia', 'MacGyver y Thornton investigan la muerte de un viejo amigo, un prominente disidente ruso.', 45, '1986-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 22, 'El asesino', 'Mac trata de evitar que un asesino, que además es un maestro del disfraz, acabe con la vida de un arzobispo.', 45, '1986-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 2, 'Temporada 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 1, 'El factor humano', 'Los militares le piden a MacGyver que revise un nuevo sistema de seguridad de alta tecnología en una de sus bases. Surgen complicaciones cuando el ordenador atrapa a MacGyver dentro e intenta matarlo.', 45, '1986-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 2, 'El arrasador', 'Engañan a MacGyver que cree que está ayudando a un hombre para encontrar a su hijo. En realidad, está llevando, sin saberlo, a un atacante a su objetivo.', 45, '1986-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 3, 'Doble tormento', 'Un amigo de MacGyver se convierte en suicida después de ser estafado y haber perdido sus ahorros de toda la vida. MacGyver organiza una estafa a la inversa para recuperar el dinero.', 45, '1986-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 4, 'El niño prodigio', 'MacGyver rescata al hermano pequeño de un amigo en Chinatown que se mezcla con algunos estafadores que lo presentan con el Niño Deseoso, un legendario chico chino místico.', 45, '1986-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 5, 'La meta final', 'MacGyver y cuatro jóvenes están perdidos en el desierto después de que se avión se estrellase. Las rivalidades de los chicos de la pandilla harán más difícil esta precaria situación.', 45, '1986-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 6, 'Jackson el mentiroso', 'Jack Dalton solicita la ayuda de MacGyver para rescatar a un botánico en Centroamérica. Una vez allí, MacGyver descubre que el botánico es un viejo amigo suyo.', 45, '1986-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 7, 'El camino no tomado', 'Una monja y algunos huérfanos están secuestrados por soldados asesinos en Asia Sur-Oriental. Además, resulta que la asistente de la monja es una exnovia de MacGyver.', 45, '1986-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 8, 'Águilas', 'Dos águilas de oro se encuentran en peligro de extinción y son ayudadas por MacGyver. Él debe confrontar al cazador furtivo que trata, de manera simultánea, de matar a las águilas y eliminar al agente secreto.', 45, '1986-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 9, 'El mundo en silencio', 'Un maestro de sordos, amigo de MacGyver, tiene muchas pesadillas. MacGyver piensa que estas están conectadas a un plan para secuestran un sistema de guía de misiles.', 45, '1986-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 10, 'Tres por el camino', 'MacGyver está atado y se ve obligado a caminar junto a unos jubilados, pero no saben que tienen dinero robado que la mafia está tratando de recuperar.', 45, '1986-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 11, 'Phoenix es el blanco', 'MacGyver y su abuelo tienen planes para ir a ver un partido de hockey. Sin embargo, cuando van a la Fundación Phoenix para coger las entradas, descubren que unos terroristas quieren hacer explotar una bomba.', 45, '1987-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 12, 'Problema familiar', 'Un exagente secuestra a la esposa y al hijo de Pete Thornton por venganza. MacGyver y Pete tienen la misión de rescatarlos.', 45, '1987-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 13, 'Toque suave', 'MacGyver ayuda a un desertor ruso a buscar asilo en Estados Unidos. Mientras, Penny Parker, que va a quedar unos días en casa de MacGyver, descubre, casualmente, un complot para asesinar a un funcionario extranjero.', 45, '1987-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 14, 'El nacimiento', 'Una embarazada está huyendo de su marido, porque este la quiere matar tras descubrir un oscuro secreto. MacGyver se queda encerrado con ella en una fábrica abandonada.', 45, '1987-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 15, 'Piratas', 'Unos piratas secuestran a un arqueólogo para que les ayude a encontrar 60 millones de dólares en un tesoro que hay hundido en el fondo del mar. MacGyver debe rescatarle en un océano aislado.', 45, '1987-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 16, 'Allá en el frío', 'Un informático oculta algún microfilm en MacGyver, que está esquiando de vacaciones. Una avalancha entierra a MacGyver en la nieve e impide a la Mafia que llegue hasta él, pero no por mucho tiempo.', 45, '1987-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 17, 'Jack Daltónico, el espía', 'Mientras MacGyver está con su amigo Jack Dalton, dos agentes de la CIA han ido a asegurarse que Jack está muerto. MacGyver se sorprende cuando descubre que Jack no está muerto y que planea asesinarle.', 45, '1987-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 18, 'Socios', 'Un hombre vestido del maestro del disfraz amenaza a MacGyver en la tienda y él pensaba que había muerto. Esto hace que MacGyver quiere retroceder hasta la primera vez que se vieron.', 45, '1987-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 19, 'Maestro', 'Juzgan a un piloto por ser un posible espía de un país centroamericano y MacGyver recibe la orden de ir allí a rescatarlo. Las cosas se complican cuando MacGyver descubre que la hija tiene un secreto.', 45, '1987-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 20, 'Amigos', 'Organizan una fiesta de cumpleaños sorpresa para MacGyver en la Fundación Phoenix, lo que le llevará al agente a reflexionar sobre sus viejos amigos y sus recuerdos, algo que le hace considerar renunciar a su trabajo.', 45, '1987-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 21, 'Busquen a MacGyver', 'Una lesión en la cabeza causa amnesia a MacGyver y le hace que se olvide de que ha descubierto la existencia de una bomba en un funeral. ¿Recuperará la memoria MacGyver a tiempo?', 45, '1987-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 22, 'Por amor o dinero', 'MacGyver y una agente que odia se presentan como un matrimonio para infiltrarse en un hospital psiquiátrico de Checoslovaquia para liberar a un activista que pelea por los derechos humanos.', 45, '1987-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 3, 'Temporada 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 1, 'Amor perdido (Parte 1)', 'Los agentes soviéticos utilizan a una antigua amante de MacGyver, que el creía muerta, como peón para robar una valiosa estatua china de dragón de jade.', 45, '1987-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 2, 'Amor perdido (Parte 2)', 'Jack Dalton ayuda a MacGyver a robar la estatua del dragón de jade para liberar así a su antigua amante, que sigue cautiva. Sin embargo, todo parece indicar que está trabajando con los rusos.', 45, '1987-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 3, 'Regreso de la muerte', 'Jimmy "The Eraser" Kendall, un hombre que MacGyver ayudó a entrar en el programa de protección de testigos, ha sido localizado por la mafia que, además, ha secuestrado a su hija a su nieto con el fin de obligar a Jimmy a regresar.', 45, '1987-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 4, 'Barco fantasma', 'Mientras trata de situarse en un desierto de Alaska, MacGyver descubre la existencia de un barco abandonado. En él, un polizón ruso le dice que toda la tripulación fue acusada por Bigfoot.', 45, '1987-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 5, 'Hielo y fuego', 'Un investigador de seguros, amigo de MacGyver, es asesinado por un ladrón de diamantes con inmunidad diplomática. Nikki Carpenter, la hermana del amigo, se asocia con MacGyver para evitar que el diplomático sea deportado.', 45, '1987-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 6, 'GX-1', 'Un avión de combate experimental de los Estados Unidos es derribado sobre la Alemania Oriental. MacGyver es enviado allí para demoler los restos que quedan mientras los soviéticos, respaldados por un psíquico, tratan de alcanzarlo primero.', 45, '1987-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 7, 'Jack en la caja', 'MacGyver acude a una pequeña ciudad de Arkansas para liberar a Jack Dalton. MacGyver acaba arrestado junto a Jack y es enviado a un campo de prisioneros donde tiene que cavar en una mina abandonada donde hay millones de dólares escondidos.', 45, '1987-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 8, 'Adicto a las viudas', 'Muere el mejor amigo de MacGyver mientras iba con él, pero el agente no tiene tiempo para llorar su muerte cuando Murdoc aparece buscando venganza.', 45, '1987-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 9, 'Semana del infierno', 'Un antiguo profesor de MacGyver le pide que sea el juez de una competición física. El hijo del mentor se desespera tras no poder ganar la prueba y se encierra en el laboratorio con una bomba casera.', 45, '1987-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 10, 'Explosión', 'Un terrorista quiere matara Nikki Carpenter. MacGyver busca en los viejos registros de Nikki para averiguar quién quería matarla y por qué.', 45, '1987-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 11, 'Zona mortal', 'Cuando un satélite que traslada un experimento genético se estrella en la Tierra, MacGyver tiene que ir a recuperarlo. Cuando llega, descubre que el experimento ha cambiado en el espacio y ahora envejece a los animales rápidamente. Por ello, MacGyver lo lleva al laboratorio, pero el científico encargado no quiere destruirlo.', 45, '1988-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 12, 'Retiro anticipado', 'Pete, el jefe de MacGyver, supervisa el desarme de una ojiva nuclear. Una explosión mortal en la instalación, devastada, lleva a Pete a asumir la responsabilidad y se retire de la Fundación Phoenix. Sin embargo, MacGyver sospecha que el reemplazo de Pete es responsable de sabotear la ojiva.', 45, '1988-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 13, 'Hielo delgado', 'MacGyver vuelve a Minnesota para ayudar a su antiguo entrenador de hockey a que su equipo de preparatoria pueda entrar en los campeonatos estatales. La parte más difícil será lidiar con el carácter violento de su jugador estrella.', 45, '1988-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 14, 'El triple impar', 'MacGyver se compromete a acompañar a Jack en un vuelo para devuelve a Francia a una mujer rica y sus joyas, que acaba de adquirir. Sin embargo, cuando aterrizan en Francia son arrestados por robo y, a pesar de sus súplicas, son acusados de complicidad.', 45, '1988-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 15, 'Negociante', 'Cuando la investigación de MacGyver en el sitio que se iba a construir un puerto deportivo amenaza el cierre del proyecto, el dueño contrata a una hermosa mujer para que consiga persuadir al agente.', 45, '1988-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 16, 'Los despojadores', 'Un hombre de montaña que vio el vertido de unos residuos tóxicos tiene un testimonio que es de suma importancia para MacGyver y Pete. Sus flashbacks a su etapa en Vietnam lo convierten en una persona inestable y puede llegar a amenazar el caso.', 45, '1988-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 17, 'Máscara del lobo', 'MacGyver y Jack Dalton ayudan a un nativo americano a encontrar una máscara de lobo sagrada. Sin embardo, dos mercenarios lo secuestran para conseguir dicha máscara para ellos.', 45, '1988-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 18, 'Rock de cuna', 'Jack Dalton y MacGyver se convierten en "papás" cuando un bebé aparecen en la nave de los aviones de Jack. Ambos buscan a la madre, una exnovia de Jack, lo que abre la posibilidad de que él sea el padre de la criatura.', 45, '1988-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 19, 'Comprometedores', 'MacGyver acude a una reserva de animales para encontrarse con una exnovia que es la guarda del parque. Su reunión se ve truncada por una batalla que tienen con los cazadores furtivos de animales en peligro de extinción.', 45, '1988-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 20, 'Cielo de asesinos', 'El nieto y único heredero de un rico magnate chino vive en un monasterio. MacGyver reclama su ayuda para luchar contra una toma de posesión criminal del negocio naviero.', 45, '1988-05-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 4, 'Temporada 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 1, 'El secreto de la casa Parker', 'Penny Parker le pide a MacGyver que le acompañe a inspeccionar una vieja casa que heredó de su casa, un domicilio aparentemente embrujado.', 45, '1988-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 2, 'Hermanos de sangre', 'MacGyver regresa a su ciudad natal y le atormentan los recuerdos de un accidente de tiro de cuando era niño. Mientras él está allí, ayuda a dos adolescentes a luchar contra los traficantes de drogas locales.', 45, '1988-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 3, 'Los marginales', 'En medio de la nada, MacGyver se ve involucrado en un accidente de coche. Por suerte, le encuentra una familia Amish y le ayudar a recuperarse. MacGyver decide ayudar a la comunidad Amish para hacer frente a un equipo de construcción que pretende obligarles a abandonar su tierra.', 45, '1988-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 4, 'Sobre un ala y una plegaria', 'Pete cae preso durante un golpe de estado realizado por los rebeldes en Barraca. MacGyver debe meter en la lista a Jack para que le ayude a rescatar a Pete.', 45, '1988-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 5, 'Rumbo de colisión', 'MacGyver se convierte en el conductor de carreras de la Fundación Phoenix cuando este está ciego. Un exrival de MacGyver también participa en la carrera y quiere ganar, a cualquier precio.', 45, '1988-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 6, 'Los sobrevivientes', 'MacGyver y Pete van al desierto para perfeccionar sus habilidades de supervivencia. Allí descubren la existencia de un avión de la DEA estrellado y tienen que lidiar con los traficantes de drogas responsables.', 45, '1989-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 7, 'Sueños tempranos', 'Un asesino ha escapado y MacGyver tiene que buscarle pero, en realidad, es el peón de un criminal intelectual que todavía se encuentra encerrado y planeando vengarse de la detective que lo encarceló.', 45, '1989-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 8, 'Mac Dalton', 'Una vez que Jack Dalton encuentra a su madre, a la que no ve desde hace muchos años, descubre que es una fugitiva. La policía, un cazarrecompensas y un corrupto funcionario del gobierno están decididos a ser los primeros en atraparla.', 45, '1989-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 9, 'Cleo Rocks', 'Penny Parker se convierte en la artista principal de un nuevo musical. MacGyver sospecha que puede ser un montaje de su arquienemigo para atraparlo.', 45, '1989-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 10, 'Fraternidad de ladrones', 'Pete está en problemas cuando descubre que el empleado de la Fundación Phoenix que vende información clasificada es su hijo.', 45, '1989-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 11, 'La batalla de Tommy Giordano', 'El hijo del compañero de trabajo de MacGyver es secuestrado por el padre del niño, que se lo lleva a Canadá. MacGyver debe ir y recuperar al muchacho de la casa del tío del mismo, un poderoso jefe de la mafia.', 45, '1989-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 12, 'El reto', 'Ray, un exmiembro de la organización, se mete en problemas con la policía y el dueño de una tienda. Con la ayuda de MacGyver descubre una comunidad racista en el vecindario que rodea al club.', 45, '1989-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 13, 'Corredores', 'Una prostituta adolescente está tratando de dejar a su proxeneta y volver con su familia. Como MacGyver la ayuda a conseguirlo, ella le reconoce que su padre abusa de ella y la culpa por la muerte de su esposa.', 45, '1989-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 14, 'Envestida dorada', 'Se sospecha que un avión derribado durante la Segunda Guerra Mundial en el Ártico contiene mucho oro. Un equipo ruso-estadounidense va a recuperar el oro pero está desaparecido y MacGyver piensa que un soldado estadounidense es el responsable del accidente.', 45, '1989-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 15, 'El asesino invisible', 'MacGyver lleva a un grupo de empleados de la Fundación Phoenix a un viaje recreativo al desierto, pero se entera que alguien del grupo podría ser un criminal que ha escapado.', 45, '1989-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 16, 'Lavado de cerebros', 'La ceremonia de entrega de premios, organizada por parte de una nación africana que recibió ayuda de MacGyver y Jack, es el escenario de una trama de asesinato del líder de dicha región con Jack como el asesino involuntario.', 45, '1989-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 17, 'Blanco fácil', 'MacGyver y Pete Thornton son capturados como rehenes de un grupo de terroristas que pretenden golpear una ciudad con un arma de pulso electromagnético, que paralizaría a toda la ciudad.', 45, '1989-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 18, 'Renegado', 'MacGyver debe detener a un exmiembro Navy Seal, que una vez salvó su vida, de usar un vial robado de ántrax.', 45, '1989-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 19, 'Negocios sin terminar', 'MacGyver, Jack y Pete van a relajarse en una expedición de oro panning. Desafortunadamente, una mujer que formó parte del la vida de MacGyver los acecha y tiene intenciones de asesinarles como plan de venganza.', 45, '1989-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 5, 'Temporada 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 1, 'La leyenda de Holy Rose (Parte 1)', 'Un arqueólogo amigo de MacGyver va a visitarle y le pide ayuda con un mapa que le llevaría a un anciano artificiero llamado Holy Rose.', 45, '1989-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 2, 'La leyenda de Holy Rose (Parte 2)', 'MacGyver y su amigo arqueólogo continúan en Londres y Francia buscando a Holy Rose. En el camino, se encuentran con un magnate de joyas que tiene la intención de matarles.', 45, '1989-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 3, 'El ramillete negro', 'Una desertora, testigo de un asesinato, está protegida por la Fundación Phoenix. Además, tiene la llave para localizar un collar de un valor inestimable.', 45, '1989-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 4, 'Cese al fuego', 'Mientras que en Ginebra MacGyver sufre un intento de asesinato que acaba con él herido; el francotirador se encuentra con una colegiala estadounidense que le ayuda a limpiar su nombre.', 45, '1989-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 5, 'Segunda oportunidad', 'Unos hombres roban todo lo que pueden en Tailandia, creando el caos y provocando una situación de emergencia. MacGyver ayuda a arreglar las cosas mientras trata de ayudar a un viejo amigo a familiarizarse con un hijo que nunca supo que tenía.', 45, '1989-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 6, 'Rescate mortal', 'Murdoc pide la ayuda de MacGyver para rescatar a su hermana de su antiguo jefe. Ella tiene que desarrollar una misión en la fiesta de Halloween organizada por la fundación de asesinato profesional.', 45, '1989-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 7, 'Los niños de la luz', 'Cuando una estudiante de chino aparece en la puerta de la casa de MacGyver, ella lleva consigo una lucha que comenzó en la plaza de Tiananmen.', 45, '1989-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 8, 'El rinoceronte negro', 'MacGyver se va con un amigo a África. Cuando se une a los activistas con la esperanza de evitar una caza furtiva, Angus se encuentra con que detrás de todo esto hay un persona que maneja los hilos.', 45, '1989-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 9, 'La solución del 10%', 'MacGyver descubre un movimiento masivo neonazi dentro del sistema político estadounidense tras investigar las declaraciones de un superviviente del Holocausto.', 45, '1989-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 10, 'Problema doble', 'Una amiga estrella del rock de MacGyver está grabando un vídeo para la campaña Rock Against Drugs. Una serie de misteriosos accidentes que ocurren durante el rodaje le convencen de que su hermana gemela está tratando de matarla.', 45, '1989-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 11, 'La Virgen', 'MacGyver y los niños en el Club de Desafíos descubren el verdadero significado de Navidad por una misteriosa mujer sin hogar que acude a quedarse allí.', 45, '1989-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 12, 'Serenidad', 'Exhausto del trabajo, MacGyver se queda dormido viendo una película western. Sueña que está en el viejo oeste y allí se encuentra con Murdoc y Pete, que conspiran que obligar a MacGyver a abandonar su tierra.', 45, '1990-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 13, 'Vive y aprende', 'MacGyver es el mentor de un estudiante de secundaria con problemas que abandona el colegio para trabajar en la construcción con su padre. Allí, el chico descubre que el sitio puede no cumplir con las normas de seguridad cuando él averigua que un inspector está siendo sobornado.', 45, '1990-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 14, 'Desforestacion', 'MacGyver se hace pasar por un registrador del noroeste pacífico para exponer las prácticas ilegales de un hombre de negocios japonés.', 45, '1990-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 15, 'El tesoro de Manco', 'Un amigo de MacGyver es asesinado en Perú buscando un mítico tesoro. MacGyver ayuda a la hija de este a terminar su búsqueda.', 45, '1990-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 16, 'La recta final', 'MacGyver organiza una operación de casa de apuestas para atrapar al asesino de un entrenador de caballos.', 45, '1990-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 17, 'Escondite profundo', 'Una científica diseña un innovador sistema de detención para la Fundación Phoenix, pero el propietario de una compañía submarina quiere vender dicho sistema a un cártel de narcotraficantes.', 45, '1990-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 18, 'El Amadeus perdido', 'Un famoso músico es secuestrado por unos criminales que quieren hacerse con un violín de Mozart como rescate. Una joven pide ayuda a MacGyver para derrotar a los que han raptado al artista.', 45, '1990-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 19, 'Corazón de acero', 'Unos trabajadores de la fábrica de acero están muy molestos y por ello secuestran a la hija del jefe que los dejó sin trabajo.', 45, '1990-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 20, 'El juicio', 'MacGyver está secuestrado por un jurado en un juicio en el que él es el acusado. MacGyver se escabulle para investigar la escena de un crimen, descubriendo nuevas pruebas pero desacatando al tribunal.', 45, '1990-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 5), 21, 'Pasajes', 'Mientras está en coma tras una gran caída, MacGyver sufre una experiencia muy cercana a la muerte donde se reúne con su abuelo Harry y sus padres fallecidos.', 45, '1990-04-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 6, 'Temporada 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 1, 'Chicos malos', 'Una banda de vigilantes está destrozando algunas casas de la ciudad. MacGyver sospecha de un exmarine del centro de la juventud como el entrenador de estos jóvenes.', 45, '1990-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 2, 'Humanidad', 'MacGyver salva la vida de un soldado rumano que lo ha tomado como rehén y nuestro héroe trata de apelar al sentido de humanidad del soldado.', 45, '1990-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 3, 'El revólver', 'Tras disparar a un policía, se encuentran con que la pistola que se utilizó fue la misma que la empleada para asesinar a un candidato presidencial hace años, llevando a los investigadores a acusar al amigo de MacGyver del centro juvenil del crimen.', 45, '1990-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 4, 'Veinte preguntas', 'Lisa, la joven amiga de MacGyver, está en problemas con el alcohol. La chica ha sido arrestada porque se la relaciona con varios robos.', 45, '1990-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 5, 'El muro', 'Con la ayuda de MacGyver, un anciano alemán se reúne con la nieta que perdió hace tiempo. Sin embargo, ella es una agente que está implicada en una trama que planea robar el oro de su abuelo.', 45, '1990-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 6, 'Lección demoniaca', 'El infame doctor Zito consigue escaparse. MacGyver y la policía, incluido el mismo oficial que se encargó de encarcelar a Zito, resultan ser víctimas de los juegos sádicos del doctor.', 45, '1990-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 7, 'El testamento de Harry', 'La última voluntad de Harry es que una camioneta vintage acabe en las manos de MacGyver. Sin embargo, un grupo de ladrones tiene gran interés en encontrar el coche, creyendo que dentro se encuentra un colgante de diamantes de un valor incalculable.', 45, '1990-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 8, 'Las mujeres de MacGyver', 'Las mujeres que han pasado por la vida de MacGyver le acusan de tener medio al compromiso. Un sueño lo lleva de regreso al Viejo Oeste donde las mujeres son novias por correo.', 45, '1990-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 9, 'Cosecha amarga', 'Hallan muerto a un organizador de trabajadores agrícolas que descubrió pruebas contra los cultivadores que empleaban pesticidas mortales. MacGyver va encubierto a investigar la muerte de dicho hombre.', 45, '1990-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 10, 'El visitante', 'Mientras conduce por una pequeña ciudad, MacGyver ve algo similar a un aterrizaje de un OVNI. A partir de ahí comienza a investigar.', 45, '1990-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 11, 'Jugada apretada', 'Mama Colton, MacGyver y la hija de una leyenda del béisbol unen sus fuerzas para acabar con un grupo de criminales que producen tarjetas de béisbol, y otro artículos de coleccionista relacionados con este deporte, falsas.', 45, '1990-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 12, 'Los juegos de Jericó', 'MacGyver se vuelve a ver con su novia de secundaria en una competición deportiva internacional que está patrocinada por el marido de la mujer.', 45, '1991-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 13, 'Tierra devastada', 'MacGyver llega a un sitio pruebas de tierras propiedad de la Fundación Phoenix. Allí descubre un sobre que contiene un cassette de audio con instrucciones. Una voz le dice que tiene que esperar a MacGyver y luego descubrir la zona en la que murió; incluso el aire es peligroso para respirar. La voz está convencida de que esto es lo que le sucederá a la ciudad de Maple Ridge si el programa del constructor Bartlett se convierte en una realidad.', 45, '1991-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 14, 'El Ojo de Osiris', 'MacGyver está ayudando a los arqueólogos a encontrar la tumba de Alejandro Magno, pero pronto descubre que no son los únicos que la buscan.', 45, '1991-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 15, 'Libertad condicional', 'Earl Dent ha sido puesto en libertad condicional y pide ayuda a MacGyver. Él le consigue un trabajo, pero algunos de sus antiguos socios quieren que los lleve a la persona que los traicionó. Pero Dent se niega, así que deciden decirle que él los ayude. Cuando Angus se entera de esto, saca su vieja bicicleta y se une a ellos. Sin embargo, el oficial que le concedió la libertad condicional de Dent los sigue.', 45, '1991-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 16, 'A Dios rogando', 'MacGyver inicia una investigación muy personal para encontrar al asesino de un sacerdote, que hacía una gran labor con las personas sin hogar.', 45, '1991-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 17, 'Fé ciega', 'MacGyver deberá substituir a Pete en una misión tras revelar que padece un glaucoma en el ojo. El objetivo es conseguir una cinta de video que tendría importantes repercusiones políticas en un pequeño país de Amérca Latina.', 45, '1991-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 18, 'Fé, esperanza y caridad', 'Tras caer y herirse en una trampa para animales, MacGyver es rescatado por dos mujeres que le llevan a un pequeño hostal para recuperarse. Allí descubrirá que se esconde una banda de mafiosos, junto a su botín recién robado.', 45, '1991-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 19, 'Estrictamente Negocios', 'Murdoc decide acabar con su retiro y volver al negocio de los asesinos a sueldo. Que mejor forma de reaparecer que matando a MacGyver. Tras el intento, MacGyver acaba con amnesia en una granja recibiendo atención de una madre y su hija en contra de su voluntad.', 45, '1991-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 20, 'Sendero de lágrimas', 'Una compañía eléctrica quiere construir una nueva línea de energía cerca de una reserva de indios nativos americanos. Un miembro de la tribu tiene un plan en contra de la empresa, pero MacGyver intenta convencerle de que lo que planea horrorizaría a sus antepasados.', 45, '1991-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 6), 21, 'Retrospectiva', 'Pete está a punto de ser operado de su glaucoma, y junto a MacGyver, recuerdan algunas de sus mayores aventuras. Además, también intentarán averiguar quién puede ser el individuo que ha estado enviando mensajes amenazantes a Pete.', 45, '1991-05-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 7, 'Temporada 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 1, 'Abe, el honrado', 'El viaje de MacGyver a una estación de autobuses para recoger a su ahijado, para el Bar Mitzvah de Jeffrey, no acaba como se esperaba. Un helicóptero robado y unos terroristas caribeños tendrán la culpa de un incidente internacional.', 45, '1991-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 2, 'El barrio', 'Después del incendio de su casa-barco, MacGyver debe mudarse y llega a un nuevo barrio. Allí ayudará a una de sus nuevas vecinas, que está en peligro tras escuchar una conversación entre dos mafiosos.', 45, '1991-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 3, 'Obsesionado', 'MacGyver colabora en la protección de un dictador, quien está siendo juzgado en Estados Unidos. Además, está convencido de que Murdoc intentará matar al dictador. La obsesión de MacGyver pondrá en peligro su puesto de trabajo y el de Pete.', 45, '1991-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 4, 'El síndrome de Prometeo', 'Un pirómano psicópata mata a un amigo de MacGyver, quien colaborará con la brigada de incendios. Dicho individuo ya había cometido bastantes incendios con anterioridad y es conocido como Prometeo.', 45, '1991-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 5, 'Los Coltons', 'Los hermanos Colton, de profesión cazarrecompensas, y con la ayuda de su madre y de un perro bulldog, buscan a una testigo clave de un asesinato en el barrio chino.', 45, '1991-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 6, 'Muertos vivientes', 'MacGyver se predispone a ayudar a un joven activista estudiantil que ha sido secuestrado por un grupo de haitianos. Ellos trabajan para un sacerdote que hipnotiza al joven utilizando el vudú.', 45, '1991-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 7, 'El caballero MacGyver (Parte 1)', 'MacGyver sufre una conmoción cerebral que le transporta a la época de la corte del rey Arturo. Allí deberá encontrar a Cecilia y, pese a hacer sombra al mismísimo Merlín con sus habilidades, ayudar al mago que ha sido falsamente acusado.', 45, '1991-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 8, 'El caballero MacGyver (Parte 2)', 'MacGyver, aún en la corte del rey Arturo, intentará frenar el ascenso al poder del trono por parte de Morgana. Para ello contará con la ayuda de Merlín.', 45, '1991-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 9, 'Mortales películas mudas', 'MacGyver ayuda a una antigua estrella cómica del cine mudo, a quien le han robado las únicas copias de algunas de sus películas. Los malechores intentarán atrapar a MacGyver haciendo valer sus habilidades con los efectos especiales.', 45, '1991-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 10, 'Decisión dividida', 'Earl Dent, un viejo amigo de MacGyver, le pide ayuda ante la situación que se le presenta. Por una parte está luchando por la custodia de su hija, pero también debe preparar su vuelta al cuadrilátero.', 45, '1991-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 11, 'Armas y chicos', 'MacGyver, junto a una asociación de jóvenes, tratarán de ayudar a un niño acusado de asesinato de otro chico. Detrás de todo hay una banda de traficantes que invaden el barrio de miedo y sospecha.', 45, '1991-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 12, 'De paredes afuera', 'Un joven artista pide ayuda a MacGyver cuando el propietario de unos terrenos decide expropiar a su abuela de la casa donde ha vivido durante toda su vida.', 45, '1991-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 13, 'El Stringer', 'MacGyver colaborará con un disidente chino en una investigación sobre la importación ilegal de productor elaborados en campos de trabajo. En esta ocasión será ayudado por un joven fotoperiodista que resulta ser el hijo de MacGyver.', 45, '1992-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 14, 'La montaña de la juventud', 'MacGyver y Jack Dalton siguen la pista de la fuente de la juventud, por lo que parece ser el mítico territorio de Shangri-La. Pero en su camino también encuentran una base militar donde se fabrica una mortífera bomba.', 45, '1992-05-21');
