UPDATE Contenido SET id_tmdb = 704, descripcion = 'Por primera vez los Beatles han decidido romper todas las reglas: saltarse el programa, ignorar sus obligaciones y saborear la libertad. Pero, para ello, tendrán que dar esquinazo a sus admiradores, esquivar a los periodistas y desobedecer a sus mánagers.', trailer_url = 'https://www.youtube.com/watch?v=TWbiVqlSMgc' WHERE id_api = 'tt0058182';

UPDATE Contenido SET id_tmdb = 895, descripcion = 'A comienzos del siglo XV, el monje pintor Andrei Rublev acude junto con sus compañeros a Moscú para pintar los frescos de la catedral de la Asunción del Kremlin. Fuera del aislamiento de su celda, Rublev comenzará a percatarse de las torturas, crímenes y matanzas que tienen aterrorizado al pueblo ruso… La biografía del pintor ruso Andrei Rublev, famoso por sus iconos, sirve de base para hacer un minucioso retrato de la vida social, política y artística en la Rusia de principios del siglo XV.', trailer_url = 'https://www.youtube.com/watch?v=t1d5FSyMEd8' WHERE id_api = 'tt0060107';

